require "import"
import "java.io.File"
import "java.io.FileOutputStream"
import "java.io.RandomAccessFile"
local function laporStatus(teks)
if sFile and sFile ~= "" then
pcall(function()
local fos = FileOutputStream(sFile)
fos.write(luajava.bindClass("java.lang.String")(teks).getBytes())
fos.close()
