local ok, err = pcall(function()
local cL = luajava.bindClass("dalvik.system.DexClassLoader")(pDex, oDir, nil, service.getClassLoader())
local klsMuxer = cL.loadClass("FastMuxer")
local intType = luajava.bindClass("java.lang.Integer").TYPE
local stringType = luajava.bindClass("java.lang.String")
local typesDec = luajava.newArray(luajava.bindClass("java.lang.Class"), 5)
typesDec[0] = stringType
typesDec[1] = stringType
typesDec[2] = intType
typesDec[3] = intType
typesDec[4] = intType
local metDecode = klsMuxer.getDeclaredMethod("decodeToPCM", typesDec)
local sRNum = tonumber(sR) or 44100
local chNum = tonumber(ch) or 2
local prevNum = tonumber(prevSec) or 0
local frameSize = chNum * 2
local fVid = File(inVid)
local namaVidAman = tostring(fVid.getName()):gsub("[^%w]", "_")
local ukuranVid = string.format("%.0f", tonumber(fVid.length()) or 0)
local pcmVidTetap = cDir .. "/vid_" .. namaVidAman .. "_" .. ukuranVid .. "_" .. string.format("%d", sRNum) .. "_" .. string.format("%d", chNum) .. "_" .. string.format("%d", prevNum) .. ".raw"
local fPcmVid = File(pcmVidTetap)
if not (fPcmVid.exists() and fPcmVid.length() > 0) then
laporStatus(TEKS.mengekstrak_suara_asli_dari_video)
local pcmSementara = pcmVidTetap .. ".tmp"
pcall(function() File(pcmSementara).delete() end)
local argDecVid = luajava.newArray(luajava.bindClass("java.lang.Object"), 5)
argDecVid[0] = inVid
argDecVid[1] = pcmSementara
argDecVid[2] = luajava.newInstance("java.lang.Integer", string.format("%d", sRNum))
argDecVid[3] = luajava.newInstance("java.lang.Integer", string.format("%d", chNum))
argDecVid[4] = luajava.newInstance("java.lang.Integer", string.format("%d", prevNum))
local hasilDecVid = tostring(metDecode.invoke(nil, argDecVid))
if hasilDecVid == "SUKSES" and File(pcmSementara).length() >= frameSize then
File(pcmSementara).renameTo(fPcmVid)
elseif hasilDecVid:find("Tidak ada trek audio") or File(pcmSementara).length() < frameSize then
pcall(function() File(pcmSementara).delete() end)
local durDetik = (tonumber(durMs) or 10000) / 1000.0
if prevNum > 0 and durDetik > prevNum then durDetik = prevNum end
local totalBytesHening = math.floor(durDetik * sRNum * frameSize)
totalBytesHening = totalBytesHening - (totalBytesHening % frameSize)
if totalBytesHening < frameSize then totalBytesHening = sRNum * frameSize end
local rafHening = RandomAccessFile(fPcmVid, "rw")
rafHening.setLength(totalBytesHening)
rafHening.close()
else
pcall(function() File(pcmSementara).delete() end)
