local function salin(src, dst)
local fs = File(src)
local fd = File(dst)
if fd.exists() and fd.length() == fs.length() and fd.lastModified() == fs.lastModified() then return end
if fd.exists() then
pcall(function() fd.setWritable(true) end)
fd.delete()
end
local ins = FileInputStream(fs)
local outs = FileOutputStream(fd)
local buf = luajava.newArray(luajava.bindClass("java.lang.Byte").TYPE, 65536)
local n = ins.read(buf)
while n ~= -1 do
outs.write(buf, 0, n)
n = ins.read(buf)
end
outs.close()
ins.close()
fd.setLastModified(fs.lastModified())
fd.setReadOnly()
end
