_G.nadiKonversiFileAkhir = function(masukPath, kunci, ext, cSample, cChannel, cBitrate, cb)
local fMasuk = File(masukPath)
local induk = tostring(fMasuk.getParent())
local base = (tostring(fMasuk.getName()):gsub("%.[^%.]+$", ""))
local sementara = induk .. "/" .. base .. "_konv" .. ext
if File(sementara).exists() then File(sementara).delete() end
local progStatusFile = service.getExternalFilesDir(nil).getAbsolutePath() .. "/_editor_status.txt"
_G.eksekusiKonversiAudio({masukPath}, {sementara}, kunci, cSample, cChannel, cBitrate, progStatusFile,
function()
fMasuk.delete()
local target = induk .. "/" .. base .. ext
local n = 2
while File(target).exists() do
target = induk .. "/" .. base .. " (" .. n .. ")" .. ext
n = n + 1
end
if File(sementara).renameTo(File(target)) then
cb(target)
else
cb(sementara)
end
end,
function(err)
if File(sementara).exists() then File(sementara).delete() end
cb(nil, err)
end)
end
_G.bagikanBanyakFile = function(daftar)
if not daftar or #daftar == 0 then return end
if #daftar == 1 then
pcall(function() service.shareFile(daftar[1]) end)
return
end
local audioExt = {mp3 = true, m4a = true, wav = true, aac = true, ogg = true, opus = true, flac = true, amr = true}
local videoExt = {mp4 = true, mkv = true, ["3gp"] = true, webm = true, mov = true}
local adaAudio, adaVideo, adaLain = false, false, false
for _, p in ipairs(daftar) do
local e = tostring(p):match("%.([%w]+)$")
e = e and e:lower() or ""
if audioExt[e] then adaAudio = true elseif videoExt[e] then adaVideo = true else adaLain = true end
end
local mime = "*/*"
if adaAudio and not adaVideo and not adaLain then mime = "audio/*"
elseif adaVideo and not adaAudio and not adaLain then mime = "video/*" end
local uris = ArrayList()
local selesai = false
local function kirim()
if selesai then return end
selesai = true
if uris.size() == 0 then
bicaraLayanan(TEKS.gagal_menyiapkan_file_untuk_dibagikan)
return
end
local ok, err = pcall(function()
local it = Intent(Intent.ACTION_SEND_MULTIPLE)
it.setType(mime)
it.putParcelableArrayListExtra(Intent.EXTRA_STREAM, uris)
it.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
local pilih = Intent.createChooser(it, TEKS.bagikan .. uris.size() .. " file")
pilih.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
service.startActivity(pilih)
end)
if not ok then bicaraLayanan(TEKS.gagal_membuka_menu_bagikan .. tostring(err)) end
end
local urutan = {}
local hasil = {}
local jumlah = #daftar
local diterima = 0
local ok = pcall(function()
local MSC = luajava.bindClass("android.media.MediaScannerConnection")
local arr = luajava.newArray(luajava.bindClass("java.lang.String"), jumlah)
for i, p in ipairs(daftar) do arr[i - 1] = tostring(p); urutan[tostring(p)] = i end
local listener = luajava.createProxy("android.media.MediaScannerConnection$OnScanCompletedListener", {
onScanCompleted = function(pth, uri)
Handler(Looper.getMainLooper()).post(Runnable{run = function()
if selesai then return end
diterima = diterima + 1
local idx = urutan[tostring(pth)]
if idx then hasil[idx] = uri or false end
if diterima >= jumlah then
for i = 1, jumlah do
local u = hasil[i]
if not u then
pcall(function() u = Uri.fromFile(File(daftar[i])) end)
end
if u then uris.add(u) end
end
kirim()
end
end})
end
})
MSC.scanFile(service, arr, nil, listener)
end)
if not ok then
for _, p in ipairs(daftar) do pcall(function() uris.add(Uri.fromFile(File(p))) end) end
kirim()
return
end
Handler(Looper.getMainLooper()).postDelayed(Runnable{run = function()
if selesai then return end
for i = 1, jumlah do
local u = hasil[i]
if not u then pcall(function() u = Uri.fromFile(File(daftar[i])) end) end
if u then uris.add(u) end
end
kirim()
end}, 6000)
end
