local _C = {}
local function muatJson(k, def)
if _C[k] then
return _C[k]
end
local bw = _G.nadiPresetBawaan[k]
local r = prefs.getString(k, "")
local final = def
if r ~= "" then
local o, res = pcall(cjson.decode, r)
if o and type(res) == "table" then final = res end
end
if bw then
local gabung = {}
for _, it in ipairs(bw) do
local salin = {}
for kk, vv in pairs(it) do salin[kk] = vv end
salin.bawaan = true
gabung[#gabung + 1] = salin
end
for _, it in ipairs(final) do
if type(it) == "table" and not it.bawaan then gabung[#gabung + 1] = it end
end
final = gabung
end
_C[k] = final
return final
end
local function simpanJson(k, data)
if _G.nadiPresetBawaan[k] then
local sisa = {}
for _, it in ipairs(data) do
if not (type(it) == "table" and it.bawaan) then sisa[#sisa + 1] = it end
end
prefs.edit().putString(k, cjson.encode(sisa)).apply()
_C[k] = nil
return
end
_C[k] = data
prefs.edit().putString(k, cjson.encode(data)).apply()
end
_G.nadiBersihCacheJson = function()
for k in pairs(_C) do _C[k] = nil end
end
