end
_G.nadiBacaProgresUmum = function()
local pct, label = nil, nil
pcall(function()
local Sys = luajava.bindClass("java.lang.System")
local fPath = Sys.getProperty("nadi.prog.file")
if not fPath then return end
local f = luajava.bindClass("java.io.File")(fPath)
if not f.exists() then return end
if Sys.currentTimeMillis() - f.lastModified() > 6000 then return end
local br = luajava.bindClass("java.io.BufferedReader")(luajava.bindClass("java.io.InputStreamReader")(luajava.bindClass("java.io.FileInputStream")(f)))
local isi = br.readLine()
br.close()
if isi then
local a, b = tostring(isi):match("^(%d+)|?(.*)$")
if a then pct = tonumber(a); label = b end
end
end)
return pct, label
end
