local function formatWaktu(ms)
local totalDetik = math.floor(ms / 1000)
local jam = math.floor(totalDetik / 3600)
local sisaDetik = totalDetik % 3600
local menit = math.floor(sisaDetik / 60)
local detik = sisaDetik % 60
if jam > 0 then
return string.format("%02d:%02d:%02d", jam, menit, detik)
else
return string.format("%02d:%02d", menit, detik)
end
end
local function formatWaktuPresisi(ms)
if not ms or ms < 0 then ms = 0 end
ms = math.floor(ms)
local sisaMs = ms % 1000
local totalDetik = math.floor(ms / 1000)
local jam = math.floor(totalDetik / 3600)
local sisaDetik = totalDetik % 3600
local menit = math.floor(sisaDetik / 60)
local detik = sisaDetik % 60
local dasar = (jam > 0) and string.format("%02d:%02d:%02d", jam, menit, detik) or string.format("%02d:%02d", menit, detik)
if sisaMs > 0 then
return string.format("%s.%03d", dasar, sisaMs)
end
return dasar
end
local function formatLisanPresisi(ms)
if not ms or ms < 0 then ms = 0 end
ms = math.floor(ms)
local sisaMs = ms % 1000
local totalDetik = math.floor(ms / 1000)
local jam = math.floor(totalDetik / 3600)
local sisaDetik = totalDetik % 3600
local menit = math.floor(sisaDetik / 60)
local detik = sisaDetik % 60
local bagian = {}
if jam > 0 then table.insert(bagian, jam .. TEKS.jam) end
if menit > 0 then table.insert(bagian, menit .. TEKS.menit) end
if detik > 0 or (#bagian == 0 and sisaMs == 0) then table.insert(bagian, detik .. TEKS.detik) end
if sisaMs > 0 then table.insert(bagian, sisaMs .. TEKS.milidetik) end
return table.concat(bagian, " ")
end
local function formatUkuran(bytes)
if bytes < 1048576 then
local val = bytes / 1024
if val == math.floor(val) then
return string.format(TEKS.kb, val)
else
return string.format(TEKS.kb_2, val)
end
elseif bytes < 1073741824 then
local val = bytes / 1048576
if val == math.floor(val) then
return string.format(TEKS.mb, val)
else
return string.format(TEKS.mb_2, val)
end
else
local val = bytes / 1073741824
if val == math.floor(val) then
return string.format(TEKS.gb, val)
else
return string.format(TEKS.gb_2, val)
end
end
end
