end
local function buatDialogKonfirmasi(judul, pesan, teksYa, teksTidak, aksiYa, aksiTidak)
local b = AlertDialog.Builder(service)
b.setTitle(judul)
if pesan ~= "" then
b.setMessage(pesan)
end
b.setPositiveButton(teksYa, aksiYa)
if teksTidak ~= "" then
b.setNegativeButton(teksTidak, aksiTidak or function(d) d.dismiss() end)
end
local d = b.create()
