d.show()
return d
end
local function buatDialogInput(judul, teksAwal, teksSimpan, teksBatal, batalBisa, aksiSimpan)
if judul and string.match(judul, "Nama File") then
local waktu = os.date("_%Y%m%d_%H%M%S")
teksAwal = teksAwal .. waktu
end
local input = EditText(service)
input.setText(teksAwal)
local b = AlertDialog.Builder(service)
b.setTitle(judul)
b.setView(input)
b.setCancelable(batalBisa)
b.setPositiveButton(teksSimpan, function(d)
local hasilInput = input.getText().toString()
if hasilInput == "" and judul and string.match(judul, "Nama File") then
hasilInput = teksAwal
end
aksiSimpan(d, hasilInput)
end)
if teksBatal ~= "" then
b.setNegativeButton(teksBatal, function(d) d.dismiss() end)
end
local d = b.create()
d.getWindow().setType(WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY)
d.show()
return d
end
