onItemSelected = function(parent, view, pos, id)
_G.nadiSegarkanSpinner(sp)
if aksi then aksi(parent, view, pos, id) end
end,
onNothingSelected = function() end
}))
end
local function pasangSeek(sb, aksi)
sb.setOnSeekBarChangeListener(SeekBar.OnSeekBarChangeListener{
onProgressChanged = aksi,
onStartTrackingTouch = function() end,
onStopTrackingTouch = function() end
})
end
local function pasangKlikItem(lv, aksi)
lv.setOnItemClickListener(AdapterView.OnItemClickListener{
onItemClick = aksi
})
end
