local wadah = LinearLayout(service)
wadah.setOrientation(LinearLayout.HORIZONTAL)
wadah.setBackgroundColor(Color.parseColor("#E6000000"))
wadah.setGravity(Gravity.CENTER_VERTICAL)
local lp = luajava.bindClass("android.view.WindowManager$LayoutParams")(-2, -2, 2032, 808, -3)
lp.gravity = Gravity.TOP | Gravity.LEFT
lp.x = 0
lp.y = 0
pcall(function() lp.layoutInDisplayCutoutMode = 1 end)
local tinggiBilah = 0
pcall(function()
local res = service.getResources()
local idBar = res.getIdentifier("status_bar_height", "dimen", "android")
if idBar > 0 then tinggiBilah = res.getDimensionPixelSize(idBar) end
end)
local dmT = service.getResources().getDisplayMetrics()
local dT = dmT.density
if tinggiBilah <= 0 then tinggiBilah = math.floor(24 * dT) end
local pctTinggi = math.max(80, math.min(200, prefs.getInt("overlay_tinggi", 100)))
local tinggiPx = math.floor(tinggiBilah * pctTinggi / 100)
tinggiPx = math.max(math.floor(20 * dT), math.min(tinggiPx, math.floor(64 * dT)))
lp.height = tinggiPx
local pctTeks = math.max(80, math.min(160, prefs.getInt("overlay_teks", 100)))
local ukuranTeks = 10 * pctTeks / 100
ukuranTeks = math.min(ukuranTeks, math.max(10, (tinggiPx / dT) * 0.45))
ukuranTeks = math.max(8, ukuranTeks)
pcall(function()
local dm = service.getResources().getDisplayMetrics()
local W = dm.widthPixels
local d = dm.density
local lebarMaks = math.floor(190 * d)
local lebarSeparuh = math.floor(W * 0.5)
local posisi = prefs.getInt("posisi_overlay", 0)
local pctLebar = math.max(60, math.min(140, prefs.getInt("overlay_lebar", 100)))
local xKiri = math.min(math.floor(W * 0.28), math.floor(120 * d))
local lebar
if posisi == 0 then
lebar = math.min(lebarMaks, math.floor(W * 0.75) - xKiri)
lebar = math.max(lebar, math.min(math.floor(120 * d), W - xKiri))
else
lebar = math.min(lebarMaks, lebarSeparuh)
end
lebar = math.floor(lebar * pctLebar / 100)
lebar = math.max(math.min(math.floor(110 * d), W), math.min(lebar, math.floor(W * 0.95)))
local x
if posisi == 3 then x = 0
elseif posisi == 2 then x = W - lebar
elseif posisi == 1 then x = math.floor((W - lebar) / 2)
else
x = xKiri
lebar = math.min(lebar, W - x)
end
lp.width = lebar
lp.x = x
end)
