local function formatDurasiPendek(totalDetik)
local j = math.floor(totalDetik / 3600)
local m = math.floor((totalDetik % 3600) / 60)
local d = totalDetik % 60
if j > 0 then return string.format("%d:%02d:%02d", j, m, d) end
return string.format("%d:%02d", m, d)
end
