local flagFilePath = service.getExternalFilesDir(nil).getAbsolutePath() .. "/is_recording.flag"
local flagFile = File(flagFilePath)
local pauseFilePath = service.getExternalFilesDir(nil).getAbsolutePath() .. "/is_paused.flag"
local pauseFile = File(pauseFilePath)
_G.eksekusiJeda = function()
if prefs.getString("status", "mati") ~= "sedang berjalan" then return false end
pcall(function() pauseFile.createNewFile() end)
if _G.nadiRecorder then pcall(function() _G.nadiRecorder.pause() end) end
local ac = prefs.getLong("akumulasi", 0) + (System.currentTimeMillis() - prefs.getLong("waktu_mulai", 0))
prefs.edit().putString("status", "terjeda").putLong("akumulasi", ac).apply()
getar(50)
return true
end
_G.eksekusiLanjutkan = function()
if prefs.getString("status", "mati") ~= "terjeda" then return false end
pcall(function() if pauseFile.exists() then pauseFile.delete() end end)
if _G.nadiRecorder then pcall(function() _G.nadiRecorder.resume() end) end
prefs.edit().putString("status", "sedang berjalan").putLong("waktu_mulai", System.currentTimeMillis()).apply()
getar(200)
return true
end
_G.hentikanSensorGoyang = function()
if _G.nadiSensorGoyang then
pcall(function()
service.getSystemService(Context.SENSOR_SERVICE).unregisterListener(_G.nadiSensorGoyang)
end)
_G.nadiSensorGoyang = nil
end
end
_G.mulaiSensorGoyang = function()
_G.hentikanSensorGoyang()
if prefs.getInt("aksi_goyang", 0) == 0 then return end
pcall(function()
local SM = luajava.bindClass("android.hardware.SensorManager")
local SN = luajava.bindClass("android.hardware.Sensor")
local sm = service.getSystemService(Context.SENSOR_SERVICE)
local akselerometer = sm.getDefaultSensor(SN.TYPE_ACCELEROMETER)
if not akselerometer then return end
local terakhir = 0
_G.nadiSensorGoyang = luajava.createProxy("android.hardware.SensorEventListener", {
onSensorChanged = function(event)
local aksi = prefs.getInt("aksi_goyang", 0)
if aksi == 0 then return end
local gr = SM.GRAVITY_EARTH
local x, y, z = event.values[0], event.values[1], event.values[2]
local gForce = math.sqrt(x * x + y * y + z * z) / gr
local gerak = (gForce - 1) * gr
local ambang = math.max(5, prefs.getInt("sens_goyang", 30))
if gerak > ambang then
local now = System.currentTimeMillis()
if now - terakhir < 2000 then return end
terakhir = now
local stat = prefs.getString("status", "mati")
if aksi == 1 then
if stat == "sedang berjalan" then
_G.eksekusiJeda()
elseif stat == "terjeda" then
_G.eksekusiLanjutkan()
end
elseif aksi == 2 then
if (stat == "sedang berjalan" or stat == "terjeda") and _G.eksekusiHentikanRekaman then
_G.eksekusiHentikanRekaman(masterDialog)
end
end
end
end,
onAccuracyChanged = function(sensor, accuracy) end
})
sm.registerListener(_G.nadiSensorGoyang, akselerometer, SM.SENSOR_DELAY_UI)
end)
end
_G.isRealTimeActive = false
_G.realTimeFinished = false
local function jalankanAudioRealTime(m, fIdx, tWav, pMic, pInt, sr, ch, br, vMic, vInt)
_G.isRealTimeActive = true
_G.realTimeFinished = false
task(function(outAudio, flagPath)
require "import"
import "java.io.File"
import "java.lang.Thread"
while File(flagPath).exists() do
Thread.sleep(100)
end
Thread.sleep(1000)
File(outAudio .. ".done").createNewFile()
_G.realTimeFinished = true
end, tWav, flagFilePath, function() end)
end
local function aktifkanForegroundNadi()
pcall(function()
local Build = luajava.bindClass("android.os.Build")
local Notification = luajava.bindClass("android.app.Notification")
local NotificationManager = luajava.bindClass("android.app.NotificationManager")
local channelId = "jsr_audio_record"
local manager = service.getSystemService(Context.NOTIFICATION_SERVICE)
if Build.VERSION.SDK_INT >= 26 then
local NotificationChannel = luajava.bindClass("android.app.NotificationChannel")
local channel = NotificationChannel(channelId, TEKS.perekam_jsr, NotificationManager.IMPORTANCE_LOW)
manager.createNotificationChannel(channel)
end
local builder = (Build.VERSION.SDK_INT >= 26) and Notification.Builder(service, channelId) or Notification.Builder(service)
builder.setContentTitle(TEKS.perekam_nadi_aktif)
builder.setContentText(TEKS.menangkap_media_layar_audio)
builder.setSmallIcon(android.R.drawable.ic_dialog_info)
builder.setOngoing(true)
local notif = builder.build()
if not pcall(function() service.startForeground(888, notif, 32) end) then
pcall(function() service.startForeground(888, notif) end)
end
end)
end
