local function writeWavHeader(out, totalAudio, totalData, sRate, chCount, bRate)
local buffer = ByteBuffer.allocate(44).order(ByteOrder.LITTLE_ENDIAN)
buffer.put(String("RIFF").getBytes()); buffer.putInt(totalData)
buffer.put(String("WAVE").getBytes()); buffer.put(String("fmt ").getBytes())
buffer.putInt(16); buffer.putShort(1); buffer.putShort(chCount)
buffer.putInt(sRate); buffer.putInt(bRate); buffer.putShort(chCount * 2)
buffer.putShort(16); buffer.put(String("data").getBytes()); buffer.putInt(totalAudio)
out.write(buffer.array())
end
