local function jalankanAkhir()
local aInt, aMic
if iInt and aRecord then aInt = {rec = aRecord, os = osInt, buf = dataInt, total = 0, pertama = true, kosong = nil, tPath = oPath} end
if iMic and micRecord then aMic = {rec = micRecord, os = osMic, buf = dataMic, total = 0, pertama = true, kosong = nil, tPath = mPath} end
local arus = {}
if aInt then arus[#arus + 1] = aInt end
if aMic then arus[#arus + 1] = aMic end
local function isiNol(a, byt)
byt = byt - (byt % frameSize)
while byt > 0 do
local t = math.min(byt, readChunkSize)
a.os.write(zeroPadBuf, 0, t)
a.total = a.total + t
byt = byt - t
end
end
while File(flagP).exists() do
local sedangJeda = File(pauseP).exists()
local adaData = false
for _, a in ipairs(arus) do
local guard = 0
while guard < 16 do
guard = guard + 1
local r = tonumber(a.rec.read(a.buf, 0, readChunkSize, NON_BLOCKING)) or 0
local now = SystemClock.elapsedRealtime()
if r > 0 then
adaData = true
if not sedangJeda then
if a.pertama then
a.pertama = false
pcall(function()
local ft = FileOutputStream(File(a.tPath .. ".time"))
ft.write(String(tostring(System.currentTimeMillis())).getBytes())
ft.close()
end)
elseif a.kosong and (now - a.kosong) >= 500 then
isiNol(a, math.floor((now - a.kosong) * byteRate / 1000))
end
a.kosong = nil
a.os.write(a.buf, 0, r)
a.total = a.total + r
else
a.kosong = nil
end
if r < readChunkSize then break end
else
if sedangJeda or a.pertama then a.kosong = nil
elseif not a.kosong then a.kosong = now end
break
end
end
end
if not adaData then pcall(function() SystemClock.sleep(3) end) end
end
if aInt and aMic then
local sel = aInt.total - aMic.total
if sel > 0 then isiNol(aMic, sel) elseif sel < 0 then isiNol(aInt, -sel) end
end
totalIntLen = aInt and aInt.total or 0
totalMicLen = aMic and aMic.total or 0
end
