while File(flagP).exists() do
local sedangJeda = File(pauseP).exists()
local adaData = false
if iInt and aRecord then
local rInt = tonumber(aRecord.read(dataInt, 0, readChunkSize, NON_BLOCKING)) or 0
if rInt > 0 then
adaData = true
if not sedangJeda then
isFirstInt = false
osInt.write(dataInt, 0, rInt)
totalIntLen = totalIntLen + rInt
end
end
end
if iMic and micRecord then
local rMic = tonumber(micRecord.read(dataMic, 0, readChunkSize, NON_BLOCKING)) or 0
if rMic > 0 then
adaData = true
if not sedangJeda then
isFirstMic = false
