totalMicLen = totalMicLen + rMic
end
end
end
if iInt and iMic and not sedangJeda then
local selisih = totalIntLen - totalMicLen
if selisih > batasSelisihByte then
local kurang = selisih - (selisih % frameSize)
while kurang > 0 do
local tulis = math.min(kurang, readChunkSize)
osMic.write(zeroPadBuf, 0, tulis)
totalMicLen = totalMicLen + tulis
kurang = kurang - tulis
end
elseif (-selisih) > batasSelisihByte then
local kurang = (-selisih) - ((-selisih) % frameSize)
while kurang > 0 do
