local tampilkanDialogGeser
do
local function bacaAngkaFile(path)
local hasil = nil
pcall(function()
local br = luajava.newInstance("java.io.BufferedReader", luajava.newInstance("java.io.FileReader", path))
local baris = br.readLine()
br.close()
if baris then hasil = tonumber(string.match(tostring(baris), "%-?%d+")) end
end)
return hasil
end
local function tulisAngkaFile(path, angka)
pcall(function()
local fw = luajava.newInstance("java.io.FileWriter", path)
fw.write(luajava.newInstance("java.lang.String", string.format("%d", math.floor(angka))))
fw.close()
end)
end
local function salinCuplikan(src, dst, offsetByte, panjangByte)
local fis = luajava.newInstance("java.io.FileInputStream", src)
local fos = luajava.newInstance("java.io.FileOutputStream", dst)
local inCh = fis.getChannel()
local outCh = fos.getChannel()
inCh.transferTo(0, 44, outCh)
local pos = 44 + offsetByte
local sisa = panjangByte
while sisa > 0 do
local n = inCh.transferTo(pos, sisa, outCh)
if n <= 0 then break end
pos = pos + n
sisa = sisa - n
end
outCh.close(); inCh.close(); fos.close(); fis.close()
end
local function muatKelasMuxer(dirLokal, odexDir)
local classLoader = luajava.bindClass("dalvik.system.DexClassLoader")(_G.jalurDexNadi, odexDir, nil, service.getClassLoader())
return classLoader.loadClass("FastMuxer")
end
local function panggilProsesAudio(kelas, tMic, tInt, keluar, fmt, sR, ch, bR, volM, volI)
local tipe = luajava.newArray(luajava.bindClass("java.lang.Class"), 9)
tipe[0] = luajava.bindClass("java.lang.String")
tipe[1] = luajava.bindClass("java.lang.String")
tipe[2] = luajava.bindClass("java.lang.String")
tipe[3] = luajava.bindClass("java.lang.Integer").TYPE
tipe[4] = luajava.bindClass("java.lang.Integer").TYPE
tipe[5] = luajava.bindClass("java.lang.Integer").TYPE
tipe[6] = luajava.bindClass("java.lang.Integer").TYPE
tipe[7] = luajava.bindClass("java.lang.Float").TYPE
tipe[8] = luajava.bindClass("java.lang.Float").TYPE
local metode = kelas.getDeclaredMethod("prosesAudio", tipe)
local args = luajava.newArray(luajava.bindClass("java.lang.Object"), 9)
args[0] = tMic
args[1] = tInt
args[2] = keluar
args[3] = luajava.newInstance("java.lang.Integer", string.format("%d", tonumber(fmt) or 1))
args[4] = luajava.newInstance("java.lang.Integer", string.format("%d", tonumber(sR) or 44100))
args[5] = luajava.newInstance("java.lang.Integer", string.format("%d", tonumber(ch) or 1))
args[6] = luajava.newInstance("java.lang.Integer", string.format("%d", tonumber(bR) or 128000))
args[7] = luajava.newInstance("java.lang.Float", tostring(tonumber(volM) or 1.0))
args[8] = luajava.newInstance("java.lang.Float", tostring(tonumber(volI) or 1.0))
return metode.invoke(nil, args)
end
