local function bangunCfgGerak(segmenList)
local barisCfg = {}
for _, seg in ipairs(segmenList) do
local fx = seg.efek or {}
local sMs = tostring(tonumber(seg.awalMs) or 0):gsub(",", ".")
local eMs = tostring(tonumber(seg.akhirMs) or 0):gsub(",", ".")
local g = fx.gate
local strGate = g and ("1," .. tostring(g.thresh or 20):gsub(",", ".") .. "," .. tostring(g.attack or 5):gsub(",", ".") .. "," .. tostring(g.release or 150):gsub(",", ".")) or "0,0,5,150"
local p = fx.pitch
local strPitch = (p and tonumber(p.semitone) and tonumber(p.semitone) ~= 0) and ("1," .. tostring(p.semitone):gsub(",", ".")) or "0,0"
if p and (p.val ~= nil or p.lanjut or p.glOn) then
local function fPl(x) return (tostring(x):gsub(",", ".")) end
local vPl = p.val
if vPl == nil then vPl = tonumber(p.semitone) or 0 end
if vPl ~= 0 or p.glOn then
strPitch = "1," .. fPl(vPl) .. "," .. (p.lanjut and "1" or "0") .. "," .. (p.glOn and "1" or "0") .. "," .. fPl(p.g0 or 0) .. "," .. fPl(p.g1 or 0) .. "," .. fPl(p.gd or 0)
else
strPitch = "0,0"
end
end
local r = fx.reverb
local strRvb = r and ("1," .. tostring((tonumber(r.room) or 50)/100.0):gsub(",", ".") .. "," .. tostring((tonumber(r.damp) or 50)/100.0):gsub(",", ".") .. "," .. tostring((tonumber(r.dry) or 70)/100.0):gsub(",", ".") .. "," .. tostring((tonumber(r.wet) or 30)/100.0):gsub(",", ".") .. "," .. tostring((tonumber(r.stereo) or 0)/100.0):gsub(",", ".")) or "0,0.5,0.5,0.7,0.3"
local e = fx.echo
local strEco = e and ("1," .. tostring(e.delay or 300):gsub(",", ".") .. "," .. tostring((tonumber(e.fb) or 30)/100.0):gsub(",", ".") .. "," .. tostring((tonumber(e.damp) or 50)/100.0):gsub(",", ".") .. "," .. tostring((tonumber(e.dry) or 100)/100.0):gsub(",", ".") .. "," .. tostring((tonumber(e.wet) or 30)/100.0):gsub(",", ".") .. "," .. tostring((tonumber(e.stereo) or 0)/100.0):gsub(",", ".")) or "0,300,0.3,0.5,1.0,0.3"
local strTone = "0,50,50,50,50,50,50,50"
if fx.bt then
strTone = "1," .. tostring(fx.bt.bass or 50) .. "," .. tostring(fx.bt.treble or 50) .. ",50,50,50,50,50"
elseif fx.eq then
strTone = "1,50,50," .. tostring(fx.eq.b1 or 50) .. "," .. tostring(fx.eq.b2 or 50) .. "," .. tostring(fx.eq.b3 or 50) .. "," .. tostring(fx.eq.b4 or 50) .. "," .. tostring(fx.eq.b5 or 50)
end
local at = fx.autotune
local strAt = at and ("1," .. string.format("%d", math.floor(tonumber(at.key) or 0)) .. "," .. string.format("%d", math.floor(tonumber(at.scale) or 0)) .. "," .. tostring(at.speed or 80):gsub(",", ".")) or "0,0,0,80"
local sdx = fx.suaradua
local strSD = "0"
if sdx then
local function fSd(x) return (tostring(x):gsub(",", ".")) end
strSD = table.concat({"1", fSd(sdx.s2 or 4), fSd((sdx.vol2 or 70) / 100), fSd(sdx.dly2 or 12), fSd((sdx.pan2 or 30) / 100),
(sdx.on3 and "1" or "0"), fSd(sdx.s3 or -5), fSd((sdx.vol3 or 50) / 100), fSd(sdx.dly3 or 22), fSd((sdx.pan3 or -30) / 100),
fSd((sdx.dry or 100) / 100), fSd(sdx.fo or 0), fSd((sdx.nat or 50) / 100)}, ",")
end
local snx = fx.sensor
local strSN = "0"
if snx then
local function fSn(x) return (tostring(x):gsub(",", ".")) end
strSN = table.concat({"1", string.format("%d", math.floor(tonumber(snx.kind) or 1)), fSn(snx.freq or 1000), fSn((snx.vol or 60) / 100), fSn((snx.mix or 0) / 100), fSn(snx.fade or 10)}, ",")
end
table.insert(barisCfg, sMs .. "|" .. eMs .. "|" .. strGate .. "|" .. strPitch .. "|" .. strRvb .. "|" .. strEco .. "|" .. strTone .. "|" .. strAt .. "|" .. strSD .. "|" .. strSN)
end
return table.concat(barisCfg, "\n")
end
