local function mulaiProsesEditor(jenis, finalPath)
prefs.edit()
.putString("status", "memproses")
.putString("jenis_proses", jenis)
.putString("final_out_path", finalPath)
.apply()
if prefs.getBoolean("sembunyi_panel_proses", false) then
masterDialog = nil
tampilkanTombolMengambang()
else
renderProsesLatarBelakang()
end
end
local function selesaiProsesEditor(fileStatus, pesan)
local tujuan = _G.nadiFormatTujuan
_G.nadiFormatTujuan = nil
local function akhiri(pesanAkhir)
hapusTombolMengambang()
prefs.edit().putString("status", "mati").apply()
hapusFile(fileStatus)
bicaraLayanan(pesanAkhir)
if masterDialog and masterDialog.isShowing() then
pcall(function() masterDialog.dismiss() end)
renderMenuEditor()
end
end
local pathAsli = prefs.getString("final_out_path", "")
if tujuan and pathAsli ~= "" and File(pathAsli).exists() then
_G.nadiKonversiFileAkhir(pathAsli, tujuan[1], tujuan[3], 0, 0, tujuan[4] or 0, function(pathBaru)
if pathBaru then
akhiri(pesan)
else
akhiri(tostring(pesan) .. TEKS.namun_konversi_ke_format .. tujuan[2] .. TEKS.gagal_hasil_tetap_tersimpan_sebagai_m4a)
end
end)
else
akhiri(pesan)
end
end
local function gagalProsesEditor(fileStatus, pesan, err)
_G.nadiFormatTujuan = nil
hapusTombolMengambang()
prefs.edit().putString("status", "mati").apply()
hapusFile(fileStatus)
if masterDialog and masterDialog.isShowing() then
pcall(function() masterDialog.dismiss() end)
end
bicaraLayanan(pesan)
local errLay = buatWadah(LinearLayout.VERTICAL)
