errEt.setText(TEKS.error_detail .. tostring(err))
errEt.setMaxLines(10)
errLay.addView(errEt)
errLay.addView(buatTombol(TEKS.tutup, function() renderMenuEditor() end))
buatDialogKustom(TEKS.proses_gagal, errLay)
end
local function buatDialogModularInti(judul, tampilanView, aksiKembali, aksiTutup, perluKonfirmasi)
local b = AlertDialog.Builder(service)
if judul and judul ~= "" then b.setTitle(judul) end
b.setView(tampilanView)
local d = b.create()
d.getWindow().setType(WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY)
d.setOnKeyListener(DialogInterface.OnKeyListener{
onKey = function(dialog, keyCode, event)
if event.getAction() == KeyEvent.ACTION_UP and keyCode == KeyEvent.KEYCODE_BACK then
if perluKonfirmasi then
konfirmasiKeluar(function()
if aksiKembali then aksiKembali(dialog) else dialog.dismiss() end
end)
return true
else
if aksiKembali then return aksiKembali(dialog) else dialog.dismiss(); return true end
end
end
return false
end
})
d.setOnDismissListener(DialogInterface.OnDismissListener{
onDismiss = function(dialog)
if aksiTutup then aksiTutup(dialog) end
end
})
return d
end
local function buatDialogModular(judul, tampilanView, aksiKembali, aksiTutup)
return buatDialogModularInti(judul, tampilanView, aksiKembali, aksiTutup, false)
end
local function buatDialogEditor(judul, tampilanView, aksiKembali, aksiTutup)
return buatDialogModularInti(judul, tampilanView, aksiKembali, aksiTutup, true)
end
_G.vnPratinjau = function(wavPath, aksiKirim, aksiUlang, aksiBatal, kaliBuka)
local pl = MediaPlayer()
local hh = Handler(Looper.getMainLooper())
local aktif = true
local diputuskan = false
local diseret = false
local dur = 0
local okSiap = pcall(function()
local fis = luajava.newInstance("java.io.FileInputStream", luajava.bindClass("java.io.File")(wavPath))
pl.setDataSource(fis.getFD())
pl.prepare()
fis.close()
end)
if not okSiap then
pcall(function() pl.release() end)
bicaraLayanan(TEKS.gagal_memutar_pratinjau)
aksiKirim()
return
end
pcall(function() dur = pl.getDuration() or 0 end)
if dur <= 0 then dur = 1 end
local lay = buatWadah(LinearLayout.VERTICAL, 20, 20, 20, 20)
local tvPos = buatTeks("", 15, 0, 0, 0, 10)
local sb = SeekBar(service)
sb.setMax(dur)
local btnPutar = buatTombol(TEKS.jeda)
local function fmt(ms)
local d = math.floor(ms / 1000)
return string.format("%d:%02d", math.floor(d / 60), d % 60)
end
local function tampil(ms)
if ms < 0 then ms = 0 elseif ms > dur then ms = dur end
sb.setProgress(ms)
tvPos.setText(fmt(ms) .. " / " .. fmt(dur))
end
local function bersih()
if not aktif then return end
aktif = false
pcall(function() if pl.isPlaying() then pl.stop() end end)
pcall(function() pl.release() end)
end
local updRun
updRun = Runnable({
run = function()
if aktif then
local main = false
pcall(function() main = pl.isPlaying() end)
if main and not diseret then tampil(pl.getCurrentPosition()) end
hh.postDelayed(updRun, 150)
end
end
})
pl.setOnCompletionListener(MediaPlayer.OnCompletionListener{
onCompletion = function(mp)
btnPutar.setText(TEKS.putar)
tampil(dur)
end
})
sb.setOnSeekBarChangeListener(SeekBar.OnSeekBarChangeListener{
onProgressChanged = function(sbx, progress, fromUser)
if fromUser and aktif then tampil(progress) end
end,
onStartTrackingTouch = function() diseret = true end,
onStopTrackingTouch = function()
diseret = false
if aktif then pcall(function() pl.seekTo(sb.getProgress()) end) end
end
})
btnPutar.setOnClickListener(function()
if not aktif then return end
local main = false
pcall(function() main = pl.isPlaying() end)
if main then
pcall(function() pl.pause() end)
btnPutar.setText(TEKS.putar)
else
local pos = sb.getProgress()
pcall(function()
if pos >= dur - 50 then pl.seekTo(0) end
pl.start()
end)
btnPutar.setText(TEKS.jeda)
end
end)
local dlg
local function putus(aksi)
if diputuskan then return end
diputuskan = true
bersih()
dlg.dismiss()
aksi()
end
lay.addView(buatTeks(TEKS.dengarkan_dulu_hasilnya_lalu_kirim, 13, 0, 0, 0, 10, nil, "#888888"))
lay.addView(tvPos)
lay.addView(sb)
lay.addView(btnPutar)
local btnKirimVn = buatTombol(TEKS.kirim_voice_note, function() putus(aksiKirim) end)
btnKirimVn.setBackgroundColor(Color.parseColor("#4CAF50"))
btnKirimVn.setTextColor(Color.WHITE)
lay.addView(btnKirimVn)
lay.addView(buatTombol(TEKS.rekam_ulang_voice_note, function()
buatDialogKonfirmasi(TEKS.buang_rekaman_ini, TEKS.rekaman_akan_dihapus_rekam_ulang, TEKS.ya_rekam_ulang_vn, TEKS.kembali, function(dk)
dk.dismiss()
putus(aksiUlang)
end)
end))
lay.addView(buatTombol(TEKS.batal, function()
buatDialogKonfirmasi(TEKS.batalkan_voice_note_tanya, TEKS.rekaman_akan_dihapus_tidak_ada_dikirim, TEKS.ya_batalkan, TEKS.kembali, function(dk)
dk.dismiss()
putus(aksiBatal)
end)
end))
tampil(0)
dlg = buatDialogKustom(TEKS.pratinjau_voice_note, buatScroll(lay))
pcall(function()
dlg.setOnDismissListener(DialogInterface.OnDismissListener{
onDismiss = function()
if not diputuskan then
diputuskan = true
bersih()
local n = (kaliBuka or 0) + 1
if n <= 5 then
hh.postDelayed(Runnable({run = function() _G.vnPratinjau(wavPath, aksiKirim, aksiUlang, aksiBatal, n) end}), 150)
end
end
end
})
end)
pcall(function() pl.start() end)
hh.post(updRun)
end
