local MODE_VN = {"rekam", "awal", "akhir", "semua", "awalakhir", "tts_awal", "tts_akhir", "tts_semua", "tts_awalakhir"}

-- Teks yang diketik hanya disimpan di memori selama layar dipakai. Tidak ditulis ke penyimpanan, jadi hilang
-- saat layar ditutup, setelah proses selesai, atau saat aplikasi dimulai ulang.
local teksMem = {}
function M.hapusTeks()
teksMem = {}
sv("st_teks", "")
for _, m in ipairs(MODE_VN) do sv("vn_teks_" .. m, "") end
sv("vn_teks_awalakhir_awal", ""); sv("vn_teks_awalakhir_akhir", "")
sv("vn_teks_tts_awalakhir_awal", ""); sv("vn_teks_tts_awalakhir_akhir", "")
end
M.hapusTeks()   -- buang teks lama yang sempat tersimpan oleh versi sebelumnya
local NAMA_VN = {
rekam = "Rekam suara sendiri",
awal = "Gemini di awal, lalu suaramu",
akhir = "Suaramu dulu, Gemini di akhir",
semua = "Semua suara Gemini (tanpa rekam)",
awalakhir = "Gemini di awal dan di akhir (suaramu di tengah)",
tts_awal = "TTS offline di awal, lalu suaramu",
tts_akhir = "Suaramu dulu, TTS offline di akhir",
tts_semua = "Semua suara TTS offline (tanpa rekam)",
tts_awalakhir = "TTS offline di awal dan di akhir (suaramu di tengah)",
}

-- Kunci teks di memori. Mode awal+akhir punya dua teks: satu untuk bagian awal, satu untuk bagian akhir.
local function kunciTeksVn(mode, bagian)
if mode == "awalakhir" or mode == "tts_awalakhir" then return "vn_" .. mode .. "_" .. (bagian == "akhir" and "akhir" or "awal") end
return "vn_" .. mode
end

-- Mode dengan awalan tts_ memakai mesin TTS bawaan perangkat (offline, tanpa kunci API, tanpa cadangan).
function M.adalahTts(m) return tostring(m):sub(1, 4) == "tts_" end
function M.dasarMode(m) return (tostring(m):gsub("^tts_", "")) end
function M.modeLengkap()
local m = gt("vn_mode", "rekam")
if not NAMA_VN[m] then m = "rekam" end
return m
end

-- ---------------------------------------------------------------- data dasar
function M.kunciList()
local t = {}
for l in gt("kunci", ""):gmatch("[^\r\n]+") do
local k = l:gsub("^%s+", ""):gsub("%s+$", "")
if k ~= "" then t[#t + 1] = k end
end
return t
end

local function modelDikenal()
local out, seen = {}, {}
local function tambah(id)
id = (tostring(id):gsub("%s", ""))
if id ~= "" and not seen[id] then seen[id] = true; out[#out + 1] = id end
end
for _, m in ipairs(MODEL_BAWAAN) do tambah(m[1]) end
for l in gt("model_segar", ""):gmatch("[^\r\n]+") do tambah(l) end
for l in gt("model_lain", ""):gmatch("[^\r\n]+") do tambah(l) end
return out
end

local function namaModel(id)
for _, m in ipairs(MODEL_BAWAAN) do if m[1] == id then return m[2] end end
return id
end

-- Daftar model hasil "Perbarui daftar model dari Google" (model_segar) dianggap daftar resmi untuk kunci utama.
-- Selama belum pernah diperbarui (n = 0), semua model bawaan dianggap tersedia.
local function modelTersediaSet()
local set, n = {}, 0
for l in gt("model_segar", ""):gmatch("[^\r\n]+") do
local id = (l:gsub("%s", ""))
if id ~= "" and not set[id] then set[id] = true; n = n + 1 end
end
return set, n
end

local function labelModel(id)
local lb = namaModel(id)
local set, n = modelTersediaSet()
if n > 0 and not set[id] then lb = lb .. " [tidak ada di daftar Google]" end
return lb
end

function M.modelEfektif()
local utama = gt("model_utama", MODEL_BAWAAN[1][1])
local daftar = {utama}
if gtb("auto_ganti", true) then
local pilih = gt("model_cadangan", "*")
local set = {}
if pilih ~= "*" then for l in pilih:gmatch("[^\r\n]+") do set[l] = true end end
local tersedia, nTersedia = modelTersediaSet()
for _, id in ipairs(modelDikenal()) do
if id ~= utama and (pilih == "*" or set[id]) and (nTersedia == 0 or tersedia[id]) then daftar[#daftar + 1] = id end
end
end
return daftar
end

-- Daftar model, suara tambahan, dan suara buatan sendiri adalah milik proyek Google tempat kunci utama (baris pertama) dibuat.
-- Kalau kunci utama berganti, data itu dibersihkan supaya tidak menampilkan data proyek lain. Semuanya bisa diambil ulang
-- dengan tombol perbarui. Suara tanpa simpan (voicekey) sengaja tidak disentuh karena tidak bisa diambil ulang dari Google.
local function sidikKunci(k)
local x = tostring(k or "")
if x == "" then return "none" end
local h = 0
for i = 1, #x do h = (h * 31 + x:byte(i)) % 2147483647 end
return tostring(h)
end

function M.cekKunciBerganti()
local sidik = sidikKunci(M.kunciList()[1] or "")
local lama = gt("kunci_sidik", "")
if lama == sidik then return false end
sv("kunci_sidik", sidik)
if lama == "" then return false end
for _, kk in ipairs({"model_segar", "model_teks_segar", "suara_segar", "suara_saya"}) do sv(kk, "") end
for _, kk in ipairs({"suara1", "suara2"}) do
if gt(kk, ""):match("^voice_") then sv(kk, kk == "suara1" and "Kore" or "Puck") end
end
local ada = false
local utama = gt("model_utama", MODEL_BAWAAN[1][1])
for _, m in ipairs(modelDikenal()) do if m == utama then ada = true end end
if not ada then sv("model_utama", MODEL_BAWAAN[1][1]) end
return true
end

-- ---------------------------------------------------------------- suara buatan sendiri (data)
-- suara_saya : satu suara per baris, dipisah tab: id, nama, bahasa, jenis (rancangan atau tiruan), model
-- suara_kunci: suara tiruan tanpa simpan (voicekey), dipisah tab: kunci, nama, waktu dibuat (ms). Berlaku 7 hari.
local TTL_KUNCI = 7 * 24 * 3600 * 1000

local function suaraSayaList()
local out = {}
for l in gt("suara_saya", ""):gmatch("[^\n]+") do
local f = {}
for x in (l .. "\t"):gmatch("(.-)\t") do f[#f + 1] = x end
if (f[1] or "") ~= "" then
out[#out + 1] = {id = f[1], nama = (f[2] and f[2] ~= "") and f[2] or f[1], bahasa = f[3] or "", jenis = f[4] or "", model = f[5] or "", kunci = false}
end
end
local sekarang = os.time() * 1000
for l in gt("suara_kunci", ""):gmatch("[^\n]+") do
local f = {}
for x in (l .. "\t"):gmatch("(.-)\t") do f[#f + 1] = x end
local t = tonumber(f[3]) or 0
if (f[1] or "") ~= "" and sekarang - t < TTL_KUNCI then
out[#out + 1] = {id = f[1], nama = (f[2] and f[2] ~= "") and f[2] or "Suara tiruan", bahasa = "", jenis = "tiruan tanpa simpan", model = "", kunci = true,
sisaHari = math.max(1, math.ceil((TTL_KUNCI - (sekarang - t)) / 86400000))}
end
end
return out
end

local function labelSuaraSaya(v)
if v.kunci then return "[Suara saya, tanpa simpan] " .. v.nama .. " - sisa " .. v.sisaHari .. " hari" end
local lb = "[Suara saya] " .. v.nama .. " - " .. v.jenis
if v.bahasa ~= "" then lb = lb .. " - " .. v.bahasa end
return lb
end

local function tambahSuaraSaya(id, nama, bahasa, jenis, model)
nama = tostring(nama or ""):gsub("[\t\n]", " ")
local baris = {}
for l in gt("suara_saya", ""):gmatch("[^\n]+") do
if l:match("^([^\t]*)") ~= id then baris[#baris + 1] = l end
end
baris[#baris + 1] = id .. "\t" .. nama .. "\t" .. (bahasa or "") .. "\t" .. (jenis or "") .. "\t" .. (model or "")
sv("suara_saya", table.concat(baris, "\n"))
end

local function tambahSuaraKunci(kunci, nama)
nama = tostring(nama or ""):gsub("[\t\n]", " ")
local baris = {}
for l in gt("suara_kunci", ""):gmatch("[^\n]+") do baris[#baris + 1] = l end
baris[#baris + 1] = kunci .. "\t" .. nama .. "\t" .. string.format("%d", os.time() * 1000)
sv("suara_kunci", table.concat(baris, "\n"))
end

local function hapusSuaraLokal(id)
for _, kk in ipairs({"suara_saya", "suara_kunci", "suara_segar"}) do
local baris = {}
for l in gt(kk, ""):gmatch("[^\n]+") do
if l:match("^([^\t]*)") ~= id then baris[#baris + 1] = l end
end
sv(kk, table.concat(baris, "\n"))
end
if gt("suara1", "Kore") == id then sv("suara1", "Kore") end
if gt("suara2", "Puck") == id then sv("suara2", "Puck") end
end

local function semuaSuara()
local out, seen = {}, {}
for _, v in ipairs(suaraSayaList()) do
if not seen[v.id] then
seen[v.id] = true
out[#out + 1] = {id = v.id, label = labelSuaraSaya(v)}
end
end
for _, v in ipairs(SUARA_BAWAAN) do
out[#out + 1] = {id = v[1], label = v[1] .. " - " .. v[2]}
seen[v[1]] = true
end
for l in gt("suara_segar", ""):gmatch("[^\n]+") do
local f = {}
for x in (l .. "\t"):gmatch("(.-)\t") do f[#f + 1] = x end
local id = f[1] or ""
if id ~= "" and not seen[id] then
seen[id] = true
local ket = {}
local GND = {female = "perempuan", male = "laki-laki", neutral = "netral"}
for _, i in ipairs({2, 3, 4, 6, 7, 8, 5}) do
local val = f[i]
if val and val ~= "" then
if i == 4 then val = GND[val:lower()] or val end
ket[#ket + 1] = val
end
end
local lb = table.concat(ket, " - ")
if #lb > 90 then lb = lb:sub(1, 90) end
out[#out + 1] = {id = id, label = lb, bhs = (f[3] or ""):lower(), gnd = (f[4] or ""):lower(), jns = (f[6] or ""):lower(), ptc = (f[8] or ""):lower(), meta = true}
end
end
return out
end

local function namaSuara(id)
for _, v in ipairs(semuaSuara()) do if v.id == id then return v.label end end
return id
end

-- ---------------------------------------------------------------- Java
local function bacaProgres()
local ok, p, i = pcall(function()
local f = File(progPath())
if not f.exists() then return 0, "" end
local br = BufferedReader(InputStreamReader(FileInputStream(f), "UTF-8"))
local baris = br.readLine()
br.close()
local a, b = tostring(baris or ""):match("^(%d+)|(.*)$")
return tonumber(a) or 0, b or ""
end)
if ok then return p, i end
return 0, ""
end

-- ---------------------------------------------------------------- teks
-- Mode dua suara: baris yang diawali "1:" atau "2:" memulai giliran bicara baru.
function M.pecahGiliran(teks, dua)
teks = tostring(teks or "")
if not dua then return {{s = 1, t = teks}} end
local g = {}
for baris in (teks .. "\n"):gmatch("(.-)\r?\n") do
local s, isi = baris:match("^%s*([12])%s*[:：]%s*(.*)$")
if s then
g[#g + 1] = {s = tonumber(s), t = isi}
elseif not kosong(baris) then
if #g == 0 then g[1] = {s = 1, t = baris}
else g[#g].t = g[#g].t .. " " .. baris end
end
end
local bersih = {}
for _, x in ipairs(g) do if not kosong(x.t) then bersih[#bersih + 1] = x end end
return bersih
end

-- Teks yang cocok ditampilkan di layar video (tanpa tag dan penanda suara).
function M.teksTampil(teks)
local t = tostring(teks or "")
t = t:gsub("<[%a%-%s]+>", ""):gsub("|[^|\n]*|", ""):gsub("\n%s*[12]%s*[:：]%s*", "\n"):gsub("^%s*[12]%s*[:：]%s*", "")
t = t:gsub("[ \t]+", " "):gsub("^%s+", ""):gsub("%s+$", "")
return t
end

local function susunJson(teks, outWav, dua)
local g = M.pecahGiliran(teks, dua)
local req = {
kunci = M.kunciList(),
model = M.modelEfektif(),
dua = dua and true or false,
giliran = g,
suara1 = gt("suara1", "Kore"),
suara2 = gt("suara2", "Puck"),
gaya1 = gt("gaya1", ""),
gaya2 = gt("gaya2", ""),
out = outWav,
cache = dirCache(),
pakaiCache = gtb("pakai_cache", true),
maks = tonumber(gt("maks", "1200")) or 1200,
prog = progPath(),
}
return cjson.encode(req), #g
end

local function namaModelDipakai(daftar)
local t = {}
for m in tostring(daftar or ""):gmatch("[^,]+") do t[#t + 1] = namaModel(m) end
return table.concat(t, ", ")
end

-- Membuat suara Gemini (asinkron, ada dialog tunggu dengan persen). cb(ok, pesan)
function M.buat(teks, outWav, dua, cb)
if #M.kunciList() == 0 then
local p = "Belum ada kunci API Gemini. Isi dulu di Pengaturan Gemini TTS."
bicaraLayanan(p)
cb(false, p)
return
end
if kosong(M.teksTampil(teks)) then
local p = "Teksnya masih kosong."
bicaraLayanan(p)
cb(false, p)
return
end
local json, jml = susunJson(teks, outWav, dua)
if jml == 0 then
local p = "Teksnya masih kosong. Di mode dua suara, awali tiap baris dengan 1: atau 2:"
bicaraLayanan(p)
cb(false, p)
return
end
pcall(function() File(progPath()).delete() end)
local pd = buatDialogTunggu("Membuat suara Gemini...")
local selesai = false
local poll
poll = Runnable({run = function()
if selesai then return end
local p, info = bacaProgres()
pcall(function() pd.setMessage("Membuat suara Gemini... " .. p .. "%\n" .. info) end)
hnd.postDelayed(poll, 600)
end})
hnd.postDelayed(poll, 600)
_G.rapikanAsync("gm_buat", json, "", "", "", function(r)
selesai = true
pcall(function() pd.dismiss() end)
r = tostring(r or "")
if r:match("^SUKSES") then
local f = {}
for x in (r .. "|"):gmatch("(.-)|") do f[#f + 1] = x end
local pakai = namaModelDipakai(f[2])
local dariCache = tonumber(f[3]) or 0
local total = tonumber(f[4]) or 0
local pesan
if pakai == "" then
pesan = "Suara diambil dari cadangan, jatah Google tidak terpakai."
else
pesan = "Suara Gemini siap. Memakai model " .. pakai .. "."
if dariCache > 0 then pesan = pesan .. " " .. dariCache .. " dari " .. total .. " bagian dari cadangan." end
end
bicaraLayanan(pesan)
cb(true, pesan)
else
local a = r:gsub("^GAGAL:%s*", "")
bicaraLayanan("Gemini gagal. " .. a)
cb(false, a)
end
end)
end

-- Pemutar contoh
local mpAktif = nil
function M.hentikan()
if mpAktif then pcall(function() mpAktif.stop() end); pcall(function() mpAktif.release() end); mpAktif = nil end
end
function M.putar(path)
M.hentikan()
pcall(function()
mpAktif = MediaPlayer()
mpAktif.setDataSource(path)
mpAktif.prepare()
mpAktif.start()
end)
end

function M.dengar(teks, dua)
local tmp = dirExt() .. "/_gm_pratinjau.wav"
M.buat(teks, tmp, dua, function(ok)
if ok then M.putar(tmp) end
end)
end

