-- Menebak bahasa naskah hanya untuk menyaring daftar suara. Gemini TTS sendiri mengenali bahasa naskah secara otomatis.
local KATA_BAHASA = {
{"id", "id-ID", "Indonesia", {"yang", "dan", "dengan", "untuk", "dari", "ini", "itu", "tidak", "saya", "kamu", "adalah", "akan", "bisa", "sudah", "pada"}},
{"ms", "ms-MY", "Melayu", {"daripada", "anda", "ialah", "boleh", "telah", "yang", "dan", "dengan", "untuk", "ini", "itu", "saya"}},
{"en", "en-US", "Inggris", {"the", "and", "with", "for", "from", "this", "that", "not", "you", "is", "are", "will", "can", "have"}},
{"es", "es-ES", "Spanyol", {"el", "la", "los", "las", "que", "para", "con", "una", "uno", "del", "por", "como", "esta"}},
{"fr", "fr-FR", "Prancis", {"le", "la", "les", "des", "une", "avec", "pour", "dans", "est", "sont", "que", "pas", "vous"}},
{"de", "de-DE", "Jerman", {"der", "die", "das", "und", "mit", "für", "ist", "sind", "nicht", "eine", "ein", "ich"}},
{"pt", "pt-BR", "Portugis", {"os", "as", "que", "para", "com", "uma", "não", "você", "está"}},
}

function M.deteksiBahasa(teks)
local t = " " .. (tostring(teks or ""):lower():gsub("%p", " ")) .. " "
t = t:gsub("%s+", " ")
if #t < 6 then return "", "Otomatis" end
local terbaik, skorTerbaik, namaTerbaik = "", 0, "Otomatis"
for _, b in ipairs(KATA_BAHASA) do
local n = 0
for _, w in ipairs(b[4]) do
if t:find(" " .. w .. " ", 1, true) then n = n + 1 end
end
if n > skorTerbaik then terbaik, skorTerbaik, namaTerbaik = b[2], n, b[3] end
end
if skorTerbaik >= 2 then return terbaik, namaTerbaik end
return "", "Otomatis"
end

function M.teksTerakhir()
local t = teksMem.status or ""
if not kosong(t) then return t end
for _, k in ipairs({"vn_semua", "vn_awal", "vn_akhir", "vn_awalakhir_awal", "vn_awalakhir_akhir"}) do
local v = teksMem[k] or ""
if not kosong(v) then return v end
end
return ""
end

