local FILTER_G = {"", "female", "male", "neutral"}
local FILTER_N = {"", "low", "medium", "high"}
local FILTER_J = {"", "prebuilt", "prompted", "replicated"}
local function buatFilter(labels, kunciPref)
local sp = Spinner(service)
sp.setAdapter(ArrayAdapter(service, android.R.layout.simple_spinner_dropdown_item, labels))
sp.setSelection(tonumber(gt(kunciPref, "0")) or 0)
lay.addView(sp)
return sp
end
local spG = buatFilter({"Semua jenis kelamin", "Perempuan", "Laki-laki", "Netral"}, "filter_g")
local spN = buatFilter({"Semua nada (pitch)", "Rendah", "Sedang", "Tinggi"}, "filter_n")
local spJ = buatFilter({"Semua sumber suara", "Studio bawaan (prebuilt)", "Rancangan (prompted)", "Tiruan (replicated)"}, "filter_j")
local function bangunEkstra()
local t = {}
local g = FILTER_G[spG.getSelectedItemPosition() + 1] or ""
local n = FILTER_N[spN.getSelectedItemPosition() + 1] or ""
local j = FILTER_J[spJ.getSelectedItemPosition() + 1] or ""
if g ~= "" then t[#t + 1] = "gender=" .. g end
if n ~= "" then t[#t + 1] = "pitch=" .. n end
if j ~= "" then t[#t + 1] = "type=" .. j end
return table.concat(t, "&")
end
