lv.setLayoutParams(LinearLayout.LayoutParams(-1, 520))
local tampil = {}
local d
local function segarkan()
local q = etCari.getText().toString():lower()
-- Saringan bahasa/jenis kelamin/nada/sumber dikerjakan di sini (di HP), bukan di Google,
-- supaya satu kali ambil mendapat SEMUA suara dan saringan bisa diganti tanpa unduh ulang.
local fb = etBhs.getText().toString():lower():gsub("%s", "")
local fg = FILTER_G[spG.getSelectedItemPosition() + 1] or ""
local fn = FILTER_N[spN.getSelectedItemPosition() + 1] or ""
local fj = FILTER_J[spJ.getSelectedItemPosition() + 1] or ""
local aktif = (fb ~= "" or fg ~= "" or fn ~= "" or fj ~= "")
local arr = ArrayList()
tampil = {}
for _, v in ipairs(semuaSuara()) do
local lolos = true
if aktif then
if not v.meta then lolos = false
else
if fb ~= "" and v.bhs:sub(1, #fb) ~= fb then lolos = false end
if fg ~= "" and v.gnd ~= fg then lolos = false end
if fn ~= "" and v.ptc ~= fn then lolos = false end
if fj ~= "" and v.jns ~= fj then lolos = false end
end
end
if lolos and (q == "" or v.label:lower():find(q, 1, true) or v.id:lower():find(q, 1, true)) then
arr.add(v.label)
tampil[#tampil + 1] = v
end
end
lv.setAdapter(ArrayAdapter(service, android.R.layout.simple_list_item_1, arr))
end
etCari.addTextChangedListener(luajava.createProxy("android.text.TextWatcher", {
beforeTextChanged = function() end,
onTextChanged = function() end,
afterTextChanged = function() segarkan() end
}))
etBhs.addTextChangedListener(luajava.createProxy("android.text.TextWatcher", {
beforeTextChanged = function() end,
onTextChanged = function() end,
afterTextChanged = function() sv("saring_bhs", etBhs.getText().toString()); segarkan() end
}))
lay.addView(buatTombol("Segarkan daftar suara dari Google", function()
local kunci = table.concat(M.kunciList(), "\n")
if kunci == "" then bicaraLayanan("Isi dulu kunci API di Pengaturan Gemini TTS."); return end
sv("saring_bhs", etBhs.getText().toString())
sv("filter_g", spG.getSelectedItemPosition())
sv("filter_n", spN.getSelectedItemPosition())
sv("filter_j", spJ.getSelectedItemPosition())
tvInfo.setText("Mengambil SEMUA suara dari Google, mohon tunggu...")
-- Tanpa saringan ke Google: ambil seluruh katalog (ribuan suara), saringan dipasang di HP.
_G.rapikanAsync("gm_suara", kunci, "", "", "", function(r)
r = tostring(r or "")
