sv("suara1", lama)
end))
l2.addView(buatTombol("Batal", function() dm.dismiss() end))
dm = buatDialogKustom("Suara", l2)
end)
end

-- ---------------------------------------------------------------- suara buatan sendiri (dialog)
-- Menjalankan perintah Java yang lama dengan dialog tunggu dan persen. cb(hasil)
local function jalankanDenganProgres(judul, cmd, req, cb)
req.prog = progPath()
pcall(function() File(progPath()).delete() end)
local pd = buatDialogTunggu(judul)
local selesai = false
local poll
poll = Runnable({run = function()
if selesai then return end
local p, info = bacaProgres()
pcall(function() pd.setMessage(judul .. " " .. p .. "%\n" .. info) end)
hnd.postDelayed(poll, 600)
end})
hnd.postDelayed(poll, 600)
_G.rapikanAsync(cmd, cjson.encode(req), "", "", "", function(r)
selesai = true
pcall(function() pd.dismiss() end)
cb(tostring(r or ""))
end)
end

local function modelSuaraBuat()
return gt("model_utama", MODEL_BAWAAN[1][1])
end

-- Rancang suara dari deskripsi (Voice design)
function M.dialogRancang(onSelesai)
local lay = buatWadah(LinearLayout.VERTICAL, 25, 25, 25, 25)
lay.addView(buatTeks("Ceritakan suara yang kamu mau dalam satu atau dua kalimat: umur, nada, dan aksen. Ciri tetap seperti ini ditentukan di sini. Emosi per kalimat diatur lewat gaya bicara. Contoh: Perempuan sekitar 30 tahun, ramah dan tenang, logat Jawa halus.", 13, 0, 0, 0, 8, nil, "#888888"))
local etNama = EditText(service)
etNama.setHint("Nama suara, misalnya Narator Tenang")
lay.addView(etNama)
local etDesk = EditText(service)
etDesk.setHint("Deskripsi suara")
etDesk.setMinLines(3)
etDesk.setGravity(Gravity.TOP)
lay.addView(etDesk)
local gLabel = {"Jenis kelamin: tidak ditentukan", "Jenis kelamin: laki-laki", "Jenis kelamin: perempuan"}
local gNilai = {"", "male", "female"}
local spG = Spinner(service)
spG.setAdapter(ArrayAdapter(service, android.R.layout.simple_spinner_dropdown_item, gLabel))
lay.addView(spG)
local etBhs = EditText(service)
etBhs.setHint("Kode bahasa, misalnya id-ID (boleh kosong)")
etBhs.setText(gt("suara_bahasa", "id-ID"))
lay.addView(etBhs)
local tvHasil = buatTeks("", 12, 0, 4, 0, 4, nil, "#E91E63")
lay.addView(tvHasil)
local d
lay.addView(buatTombol("Buat suara", function()
if #M.kunciList() == 0 then bicaraLayanan("Isi dulu kunci API di Pengaturan Gemini TTS."); return end
local desk = etDesk.getText().toString()
local ringkas = desk:gsub("%s", "")
if #ringkas < 10 then bicaraLayanan("Deskripsinya masih terlalu pendek."); tvHasil.setText("Deskripsinya masih terlalu pendek."); return end
local nama = etNama.getText().toString()
if kosong(nama) then nama = "Suara rancangan" end
local bhs = etBhs.getText().toString():gsub("%s", "")
sv("suara_bahasa", bhs)
local contoh = dirExt() .. "/_gm_contoh_rancang.wav"
pcall(function() File(contoh).delete() end)
local model = modelSuaraBuat()
local req = {kunci = M.kunciList(), model = model, nama = nama, gender = gNilai[spG.getSelectedItemPosition() + 1] or "",
bahasa = bhs, deskripsi = desk, out = contoh}
jalankanDenganProgres("Merancang suara...", "gm_desain", req, function(r)
if r:match("^SUKSES") then
local f = {}
for x in (r .. "|"):gmatch("(.-)|") do f[#f + 1] = x end
tambahSuaraSaya(f[2] or "", f[3] or nama, bhs, "rancangan", model)
pcall(function() d.dismiss() end)
local pesan = "Suara " .. (f[3] or nama) .. " siap dan tersimpan di proyek Google kamu."
if File(contoh).exists() then pesan = pesan .. " Contoh suaranya diputar." end
bicaraLayanan(pesan)
if File(contoh).exists() then M.putar(contoh) end
if onSelesai then pcall(onSelesai) end
else
local a = r:gsub("^GAGAL:%s*", "")
tvHasil.setText("Gagal. " .. a)
bicaraLayanan("Gagal merancang suara. " .. a)
end
end)
end))
lay.addView(buatTombol("Batal", function()
d.dismiss()
if onSelesai then pcall(onSelesai) end
end))
d = buatDialogKustom("Rancang suara dari deskripsi", buatScroll(lay))
end

