-- ---------------------------------------------------------------- model transkripsi dan saran prompt
-- Terpisah dari model TTS: hanya Flash dan Flash-Lite (bisa menerima audio dan menjawab teks).
local MODEL_TEKS_BAWAAN = {"gemini-3.5-flash", "gemini-2.5-flash", "gemini-2.5-flash-lite", "gemini-2.0-flash"}

function M.modelTeksDikenal()
local out, seen = {}, {}
local function tambah(id)
id = (tostring(id):gsub("%s", ""))
if id ~= "" and not seen[id] then seen[id] = true; out[#out + 1] = id end
end
local ada = false
for l in gt("model_teks_segar", ""):gmatch("[^\r\n]+") do tambah(l); ada = true end
if not ada then for _, m in ipairs(MODEL_TEKS_BAWAAN) do tambah(m) end end
return out
end

function M.modelTeksTerpilih()
local t = (gt("model_transkrip", ""):gsub("%s", ""))
if t ~= "" then return t end
return M.modelTeksDikenal()[1] or MODEL_TEKS_BAWAAN[1]
end

-- Model pilihanmu dicoba dulu, lalu sisanya. Per model, semua kunci dicoba dulu sebelum pindah model.
function M.urutanModelTeks()
local pilih = M.modelTeksTerpilih()
local out, seen = {pilih}, {[pilih] = true}
for _, id in ipairs(M.modelTeksDikenal()) do
if not seen[id] and #out < 8 then seen[id] = true; out[#out + 1] = id end
end
return out
end

