-- Hasil gm_transkrip / gm_saran: {transkrip, gaya, teks, model}
local function terimaSaran(isi)
local ok, d = pcall(function() return require("cjson").decode(isi or "") end)
if not ok or type(d) ~= "table" then return nil end
local gaya = tostring(d.gaya or "")
local teks = tostring(d.teks or "")
if gaya ~= "" or teks ~= "" then
etGaya.setText(gaya)
etSaran.setText(teks)
tvInfoSaran.setText("Dibuat oleh model " .. tostring(d.model or "") .. ". Periksa dulu, lalu pakai kalau cocok.")
panelSaran.setVisibility(View.VISIBLE)
end
return d
end
local LABEL_SUARA = "Isi dengan Suara (ketuk untuk mulai bicara)"
local function selesaiDikte(pesan)
rec.aktif = false; rec.sibuk = false; rec.henti = false
if pesan then bicaraLayanan(pesan) end
labelSuara(LABEL_SUARA)
end
local function mulaiDikte()
if #M.kunciList() == 0 then
bicaraLayanan("Kunci API Gemini belum diisi. Isi dulu di Pengaturan Gemini TTS.")
return
end
local ARC = luajava.bindClass("android.media.AudioRecord")
local SR = 16000
local minBuf = ARC.getMinBufferSize(SR, AudioFormat.CHANNEL_IN_MONO, AudioFormat.ENCODING_PCM_16BIT)
if not minBuf or minBuf < 4096 then minBuf = 16384 end
local ar
local okAr = pcall(function()
ar = ARC(MediaRecorder.AudioSource.MIC, SR, AudioFormat.CHANNEL_IN_MONO, AudioFormat.ENCODING_PCM_16BIT, minBuf * 4)
end)
if (not okAr) or (not ar) or ar.getState() ~= ARC.STATE_INITIALIZED then
pcall(function() if ar then ar.release() end end)
bicaraLayanan("Mikrofon tidak bisa dipakai sekarang. Pastikan tidak sedang dipakai fitur lain.")
return
end
local rawSuara = dirExt() .. "/_gm_dikte.raw"
local wavSuara = dirExt() .. "/_gm_dikte.wav"
rec.aktif = true; rec.henti = false; rec.batal = false
ar.startRecording()
labelSuara("Merekam... ketuk lagi untuk berhenti dan jadikan teks")
bicaraLayanan("Mulai merekam. Ketuk lagi untuk berhenti.")
Thread(Runnable{run = function()
local ok, err = pcall(function()
local fos = luajava.newInstance("java.io.FileOutputStream", rawSuara)
local buf = byte[8192]
local total = 0
while (not rec.henti) and total < 13000000 do
local r = tonumber(ar.read(buf, 0, 8192)) or 0
if r > 0 then fos.write(buf, 0, r); total = total + r
elseif r < 0 then break end
end
pcall(function() ar.stop() end)
pcall(function() ar.release() end)
fos.close()
if rec.batal then
File(rawSuara).delete()
return
end
if total < 16000 then error("Rekaman terlalu pendek. Bicara lebih lama.") end
local BB = luajava.bindClass("java.nio.ByteBuffer")
local BO = luajava.bindClass("java.nio.ByteOrder")
local JS = luajava.bindClass("java.lang.String")
local h = BB.allocate(44).order(BO.LITTLE_ENDIAN)
h.put(JS("RIFF").getBytes()); h.putInt(total + 36)
h.put(JS("WAVE").getBytes()); h.put(JS("fmt ").getBytes())
h.putInt(16); h.putShort(1); h.putShort(1)
h.putInt(SR); h.putInt(SR * 2); h.putShort(2)
h.putShort(16); h.put(JS("data").getBytes()); h.putInt(total)
local wf = luajava.newInstance("java.io.FileOutputStream", wavSuara)
wf.write(h.array())
local fin = luajava.newInstance("java.io.FileInputStream", rawSuara)
local b2 = byte[65536]
while true do
local n = tonumber(fin.read(b2)) or -1
if n <= 0 then break end
wf.write(b2, 0, n)
end
fin.close(); wf.close()
File(rawSuara).delete()
end)
hnd.post(Runnable{run = function()
if rec.batal or rec.tutup then
pcall(function() File(wavSuara).delete() end)
rec.aktif = false; rec.sibuk = false
return
end
if not ok then
selesaiDikte("Gagal merekam. " .. tostring(err))
return
end
rec.aktif = false; rec.sibuk = true
labelSuara("Mengubah suara jadi teks...")
bicaraLayanan("Mengubah suara jadi teks")
local js = require("cjson").encode({wav = wavSuara, kunci = M.kunciList(), model = M.urutanModelTeks(), tag = tagList(), dua = cbDua.isChecked()})
_G.rapikanAsync("gm_transkrip", js, "", "", "", function(hasil)
pcall(function() File(wavSuara).delete() end)
if rec.tutup then rec.sibuk = false; return end
hasil = tostring(hasil)
local isi = hasil:match("^SUKSES\n(.*)$")
local d = isi and terimaSaran(isi) or nil
local teks = d and tostring(d.transkrip or "") or ""
if teks ~= "" then
local pos = et.getSelectionStart()
if pos < 0 then pos = et.getText().length() end
local sebelum = tostring(et.getText().toString())
local awal = ""
if pos > 0 and sebelum:sub(pos, pos):match("%S") then awal = " " end
et.getText().insert(pos, awal .. teks)
selesaiDikte("Teks dari suara sudah ditempel ke kotak teks." .. (panelSaran.getVisibility() == View.VISIBLE and " Saran prompt suara ada di bawah." or ""))
else
selesaiDikte((hasil:gsub("^GAGAL:%s*", "Gagal mengubah suara jadi teks. ")))
end
end)
end})
end})
end
btnSuara = buatTombol(LABEL_SUARA, function()
if rec.sibuk then bicaraLayanan("Sedang mengubah suara jadi teks, tunggu sebentar."); return end
if rec.aktif then
rec.henti = true
labelSuara("Menghentikan rekaman...")
return
end
mulaiDikte()
end)
lay.addView(btnSuara)

lay.addView(buatTombol("Buat saran prompt dari teks di atas", function()
local t = et.getText().toString()
if kosong(t) then bicaraLayanan("Kotak teks masih kosong."); return end
if #M.kunciList() == 0 then bicaraLayanan("Kunci API Gemini belum diisi. Isi dulu di Pengaturan Gemini TTS."); return end
if rec.saran then bicaraLayanan("Sedang membuat saran, tunggu sebentar."); return end
rec.saran = true
