local js = require("cjson").encode({teks = t, kunci = M.kunciList(), model = M.urutanModelTeks(), tag = tagList(), dua = cbDua.isChecked()})
_G.rapikanAsync("gm_saran", js, "", "", "", function(hasil)
rec.saran = false
