local b1 = buatTombol("+ Baris suara 1", function() et.append((et.getText().length() > 0 and "\n" or "") .. "1: ") end)
local b2 = buatTombol("+ Baris suara 2", function() et.append((et.getText().length() > 0 and "\n" or "") .. "2: ") end)
