-- ---------------------------------------------------------------- Pembuat Status (mode 4)
function M.statusTeks() return teksMem.status or "" end
function M.statusSimpanTeks(t) teksMem.status = t end
function M.statusDua() return gtb("dua", false) end
function M.statusBuat(teks, outWav, cb) M.buat(teks, outWav, M.statusDua(), cb) end

-- ---------------------------------------------------------------- Voice Note
-- vnMode() tetap mengembalikan mode dasar (rekam/awal/akhir/semua/awalakhir) supaya layar Voice Note tidak berubah.
function M.vnMode() return M.dasarMode(M.modeLengkap()) end
function M.vnTts() return M.adalahTts(M.modeLengkap()) end
function M.vnLabelSiapkan() return M.vnTts() and "Menyiapkan suara TTS..." or "Menyiapkan suara Gemini..." end
function M.vnTeks(mode, bagian)
mode = mode or M.modeLengkap()
return teksMem[kunciTeksVn(mode, bagian)] or ""
end
function M.labelRekam(def)
if M.vnMode() == "semua" then
local bagikan = false
pcall(function() bagikan = prefs.getString("vn_mode", "langsung") == "bagikan" end)
local nm = M.vnTts() and "TTS" or "Gemini"
return bagikan and ("Buat Voice Note " .. nm .. " lalu bagikan") or ("Buat Voice Note " .. nm .. " lalu kirim")
end
return def
end

local function vnGeminiWav(bagian)
local dasar = M.adalahTts(M.modeLengkap()) and "/_vn_tts" or "/_vn_gemini"
if bagian == "awal" or bagian == "akhir" then return dirExt() .. dasar .. "_" .. bagian .. ".wav" end
return dirExt() .. dasar .. ".wav"
end

-- Dialog teks untuk TTS offline: tanpa tag, tanpa dua suara, tanpa kunci API.
function M.dialogTeksTts(opsi)
local lay = buatWadah(LinearLayout.VERTICAL, 25, 25, 25, 25)
lay.addView(buatTeks("Ketik atau tempel teks yang mau dibacakan mesin TTS di perangkat. Dibuat offline, tanpa kunci API dan tanpa memakai jatah. Mesin, suara, kecepatan, dan nada diatur di Pengaturan Mesin TTS (sama dengan Pembuat Status).", 13, 0, 0, 0, 8, nil, "#888888"))
local et = EditText(service)
et.setHint("Tempel teks di sini")
et.setText(opsi.teks or "")
et.setMinLines(5)
lay.addView(et)
local T = _G.nadiTtsOffline
lay.addView(buatTombol("Dengarkan dulu", function()
local t = et.getText().toString()
if kosong(t) then bicaraLayanan("Kotak teks masih kosong."); return end
if T then T.dengar(t) end
end))
lay.addView(buatTombol("Hentikan suara", function() if T then T.henti() end end))
lay.addView(buatTombol("Pengaturan Mesin TTS", function() if T then T.pengaturan() end end))
local d
if opsi.onLanjut then
lay.addView(buatTombol(opsi.teksLanjut or "Simpan teks lalu lanjut", function()
if T then T.henti() end
if opsi.onSimpan then opsi.onSimpan(et.getText().toString()) end
d.dismiss()
pcall(opsi.onLanjut)
end))
end
lay.addView(buatTombol("Simpan teks", function()
if T then T.henti() end
if opsi.onSimpan then opsi.onSimpan(et.getText().toString()) end
d.dismiss()
end))
d = buatDialogKustom(opsi.judul or "Teks TTS", buatScroll(lay))
d.setOnDismissListener(DialogInterface.OnDismissListener{ onDismiss = function()
if T then pcall(T.henti); pcall(T.lepas) end
end })
end

function M.vnEditTeks(onMulai, bagian)
local mode = M.modeLengkap()
if mode == "rekam" then return end
bagian = bagian or "awal"
local kunci = kunciTeksVn(mode, bagian)
local tts = M.adalahTts(mode)
local dasar = M.dasarMode(mode)
local nm = tts and "Teks TTS" or "Teks Gemini"
local judul = nm .. ": " .. NAMA_VN[mode]
if dasar == "awalakhir" then judul = nm .. " di " .. (bagian == "akhir" and "akhir" or "awal") end
local opsi = {
judul = judul,
teks = teksMem[kunci] or "",
onSimpan = function(t) teksMem[kunci] = t; bicaraLayanan(nm .. " disimpan") end,
onLanjut = (dasar == "semua" and onMulai) and onMulai or nil,
teksLanjut = "Simpan teks lalu buat Voice Note"
}
if tts then M.dialogTeksTts(opsi) else M.dialogTeks(opsi) end
end

-- Memasang tombol Gemini ke layar Voice Note. onUbah dipanggil saat mode berganti.
-- Tombol dibuat di sini tetapi dipasang oleh pemanggil lewat pasangAtas (tombol mode) dan
-- pasangBawah (Pengaturan Gemini TTS dan tombol atur teks), supaya urutannya bisa diatur di layar.
function M.vnPasangUI(onUbah, onMulai)
local btnMode = buatTombol("")
local btnTeks = buatTombol("Atur teks Gemini")
local btnTeksAkhir = buatTombol("Atur teks Gemini di akhir")
local btnPengTts = buatTombol("Pengaturan Mesin TTS", function()
if _G.nadiTtsOffline then _G.nadiTtsOffline.pengaturan() end
end)
local function segarkan()
local m = M.modeLengkap()
local dasar = M.dasarMode(m)
local nm = M.adalahTts(m) and "TTS" or "Gemini"
btnMode.setText("Mode suara Voice Note: " .. NAMA_VN[m] .. " (ketuk untuk ganti)")
btnTeks.setVisibility(m == "rekam" and View.GONE or View.VISIBLE)
btnTeksAkhir.setVisibility(dasar == "awalakhir" and View.VISIBLE or View.GONE)
btnTeks.setText(dasar == "awalakhir" and ("Atur teks " .. nm .. " di awal") or ("Atur teks " .. nm))
btnTeksAkhir.setText("Atur teks " .. nm .. " di akhir")
btnPengTts.setVisibility(M.adalahTts(m) and View.VISIBLE or View.GONE)
end
btnMode.setOnClickListener(function()
local lb = {}
for i, m in ipairs(MODE_VN) do lb[i] = NAMA_VN[m] end
daftarDialog("Mode suara Voice Note", lb, function(i)
local m = MODE_VN[i]
sv("vn_mode", m)
segarkan()
if onUbah then onUbah() end
bicaraLayanan(NAMA_VN[m])
if M.dasarMode(m) == "awalakhir" then
if kosong(M.vnTeks(m, "awal")) then M.vnEditTeks(onMulai, "awal") end
elseif m ~= "rekam" and kosong(M.vnTeks(m)) then
M.vnEditTeks(onMulai)
end
end)
end)
btnTeks.setOnClickListener(function() M.vnEditTeks(onMulai, "awal") end)
btnTeksAkhir.setOnClickListener(function() M.vnEditTeks(onMulai, "akhir") end)
segarkan()
return {
pasangAtas = function(layout) layout.addView(btnMode) end,
pasangBawah = function(layout)
layout.addView(btnTeks)
layout.addView(btnTeksAkhir)
layout.addView(btnPengTts)
end,
}
end

-- Membuat satu suara Gemini ke file tertentu. Hasil tiap bagian disimpan sebagai cadangan oleh M.buat.
local function vnBuatBagian(teks, outWav, cb)
pcall(function() File(outWav).delete() end)
M.buat(teks, outWav, gtb("dua", false), function(ok) cb(ok) end)
end

-- Membuat satu suara dengan mesin TTS offline. Tidak ada cadangan: file sementara dihapus setelah disambung.
function M.vnBuatBagianTts(teks, outWav, cb)
pcall(function() File(outWav).delete() end)
local T = _G.nadiTtsOffline
if not T then
bicaraLayanan("Mesin TTS belum siap. Tutup lalu buka lagi aplikasi pembaca layar.")
cb(false)
return
end
local pd = buatDialogTunggu("Menyiapkan suara TTS...")
T.sintesis(teks, outWav, function(ok, alasan)
pcall(function() pd.dismiss() end)
if ok and (not File(outWav).exists() or tonumber(File(outWav).length()) <= 44) then ok = false; alasan = "Suara yang dihasilkan kosong." end
if not ok then
local a = tostring(alasan or "")
a = a:gsub("^ERROR:%s*", ""):gsub("^GAGAL:%s*", "")
if a == "" then a = "Periksa pengaturan mesin TTS Anda." end
pcall(function() File(outWav).delete() end)
bicaraLayanan("Gagal membuat suara TTS. " .. a)
cb(false)
return
end
cb(true)
end)
end

-- Dipanggil sebelum merekam (awal/akhir/awal+akhir) atau sebelum memproses (semua): membuat suara lebih dulu,
-- jadi kalau gagal (misalnya jatah habis) tidak ada rekaman yang terbuang. cb(ok)
function M.vnSiapkanSuara(cb)
local mode = M.modeLengkap()
if mode == "rekam" then cb(true); return end
local tts = M.adalahTts(mode)
local dasar = M.dasarMode(mode)
local nm = tts and "TTS" or "Gemini"
local buat = tts and M.vnBuatBagianTts or vnBuatBagian
if dasar == "awalakhir" then
local tAwal, tAkhir = M.vnTeks(mode, "awal"), M.vnTeks(mode, "akhir")
if kosong(tAwal) then
bicaraLayanan("Teks " .. nm .. " di awal masih kosong. Isi dulu.")
M.vnEditTeks(M.vnMulaiAksi, "awal")
cb(false)
return
end
if kosong(tAkhir) then
bicaraLayanan("Teks " .. nm .. " di akhir masih kosong. Isi dulu.")
M.vnEditTeks(M.vnMulaiAksi, "akhir")
cb(false)
return
end
buat(tAwal, vnGeminiWav("awal"), function(ok1)
if not ok1 then cb(false); return end
buat(tAkhir, vnGeminiWav("akhir"), function(ok2)
if not ok2 and tts then pcall(function() File(vnGeminiWav("awal")).delete() end) end
cb(ok2)
end)
end)
return
end
local teks = M.vnTeks(mode)
if kosong(teks) then
bicaraLayanan("Teks " .. nm .. " masih kosong. Isi dulu.")
M.vnEditTeks(M.vnMulaiAksi)
cb(false)
return
end
buat(teks, vnGeminiWav(), cb)
end

-- Menyambung suara Gemini ke rekaman mentah (dipanggil di thread latar, tanpa jaringan).
-- Hasilnya menimpa vnRaw supaya semua efek suara berlaku ke bagian Gemini juga.
function M.vnGabung(vnRaw, sr, ch)
local mode = M.vnMode()
if mode == "rekam" then return true end
local tts = M.vnTts()
local nm = tts and "TTS" or "Gemini"
local gw, gwAwal, gwAkhir = vnGeminiWav(), vnGeminiWav("awal"), vnGeminiWav("akhir")
local function bersihTts()
if tts then
pcall(function() File(gw).delete() end)
pcall(function() File(gwAwal).delete() end)
pcall(function() File(gwAkhir).delete() end)
end
end
local bag
if mode == "awalakhir" then
if not File(gwAwal).exists() or not File(gwAkhir).exists() then bersihTts(); return false, "Suara " .. nm .. " belum siap. Coba lagi." end
bag = {{t = "wav", p = gwAwal}, {t = "raw", p = vnRaw}, {t = "wav", p = gwAkhir}}
else
if not File(gw).exists() then bersihTts(); return false, "Suara " .. nm .. " belum siap. Coba lagi." end
if mode == "awal" then bag = {{t = "wav", p = gw}, {t = "raw", p = vnRaw}}
elseif mode == "akhir" then bag = {{t = "raw", p = vnRaw}, {t = "wav", p = gw}}
else bag = {{t = "wav", p = gw}} end
end
local gab = vnRaw .. ".gm"
pcall(function() File(gab).delete() end)
local r = tostring(_G.rapikanLive("gm_sambung", cjson.encode({out = gab, fmt = "raw", sr = sr, ch = ch, bagian = bag})))
if not r:match("^SUKSES") then bersihTts(); return false, (r:gsub("^GAGAL:%s*", "")) end
local awalMs = tonumber(r:match("^SUKSES|(%d+)")) or 0
pcall(function() File(vnRaw).delete() end)
if not File(gab).renameTo(File(vnRaw)) then bersihTts(); return false, "Tidak bisa menyimpan hasil sambungan" end
-- catatan gerakan efek dihitung dari mulai rekam, jadi digeser kalau Gemini ada di depan
pcall(function()
if (mode == "awal" or mode == "awalakhir") and awalMs > 0 and _G.nadiGerakanLog then
for _, e in ipairs(_G.nadiGerakanLog) do e.ms = (tonumber(e.ms) or 0) + awalMs end
elseif mode == "semua" then
_G.nadiGerakanLog = {}
end
end)
pcall(function() File(gw).delete() end)
pcall(function() File(gwAwal).delete() end)
pcall(function() File(gwAkhir).delete() end)
for _, m in ipairs(MODE_VN) do teksMem["vn_" .. m] = nil end
teksMem["vn_awalakhir_awal"] = nil
teksMem["vn_awalakhir_akhir"] = nil
teksMem["vn_tts_awalakhir_awal"] = nil
teksMem["vn_tts_awalakhir_akhir"] = nil
return true
end

M.daftarDialog = daftarDialog
return M
end)()

renderVoiceNote = function()
local layoutLokal = buatWadah(LinearLayout.VERTICAL, 30, 30, 30, 30)
local dialog
layoutLokal.addView(buatTeks(TEKS.voice_note_suara_sendiri, 18, 0, 0, 0, 10))
