layoutLokal.addView(buatTeks(teksPenjelasan, 14, 0, 0, 0, 16, nil, "#888888"))
local prevDir = service.getExternalFilesDir(nil).getAbsolutePath()
_G.bersihkanVnKadaluarsa(30)
local vnRaw = prevDir .. "/_vn_mic.raw"
local vnWav = prevDir .. "/_vn_out.wav"
local flagVn = prevDir .. "/_vn_rekam.flag"
