_G.nadiGemini.vnSegarkanLabel = function() if gmRef.seg then gmRef.seg() end end
gmUi.pasangBawah(layoutLokal)
local isRecording = false
local isProcessing = false
local menyiapkanVn = false
gmRef.seg = function()
if not isRecording and not isProcessing and not menyiapkanVn then
btnRekam.setText(_G.nadiGemini.labelRekam(TEKS.ketuk_untuk_mulai_rekam))
end
end
btnRekam.setOnClickListener(function()
if isProcessing or menyiapkanVn then return end
if (not isRecording) and _G.nadiGemini.vnMode() == "semua" then
menyiapkanVn = true
_G.nadiGemini.vnSiapkanSuara(function(okGm)
menyiapkanVn = false
