_G.rapikanJava = function(cmd, a, b, c, d)
if not _G.rapikanMetode then
local dPath = service.getDir("dex", 0).getAbsolutePath()
local cL = luajava.bindClass("dalvik.system.DexClassLoader")(_G.jalurDexNadi, dPath, nil, service.getClassLoader())
local kls = cL.loadClass("FastMuxer")
local tS = luajava.bindClass("java.lang.String")
local types = luajava.newArray(luajava.bindClass("java.lang.Class"), 5)
for i = 0, 4 do types[i] = tS end
_G.rapikanMetode = kls.getDeclaredMethod("rapikanPerintah", types)
end
local args = luajava.newArray(luajava.bindClass("java.lang.Object"), 5)
args[0] = cmd
args[1] = a or ""
args[2] = b or ""
args[3] = c or ""
args[4] = d or ""
return tostring(_G.rapikanMetode.invoke(nil, args))
end
_G.rapikanLive = function(cmd, a, b, c, d)
local ok, r = pcall(_G.rapikanJava, cmd, a, b, c, d)
if ok then return tostring(r) end
return "GAGAL: " .. tostring(r)
end
_G.rapikanAsync = function(cmd, a, b, c, d, cb)
local odexDir = service.getDir("dex", 0).getAbsolutePath()
local dexPath = _G.jalurDexNadi
task(function(pDex, oDir, pCmd, pA, pB, pC, pD)
require "import"
local ok, r = pcall(function()
local cL = luajava.bindClass("dalvik.system.DexClassLoader")(pDex, oDir, nil, service.getClassLoader())
local kls = cL.loadClass("FastMuxer")
local tS = luajava.bindClass("java.lang.String")
local types = luajava.newArray(luajava.bindClass("java.lang.Class"), 5)
for i = 0, 4 do types[i] = tS end
local met = kls.getDeclaredMethod("rapikanPerintah", types)
local args = luajava.newArray(luajava.bindClass("java.lang.Object"), 5)
args[0] = pCmd; args[1] = pA; args[2] = pB; args[3] = pC; args[4] = pD
return tostring(met.invoke(nil, args))
end)
if ok then return r end
return "GAGAL: " .. tostring(r)
end, dexPath, odexDir, cmd or "", a or "", b or "", c or "", d or "", function(r)
pcall(cb, tostring(r))
end)
end
_G.rapikanNamaNada = function(midi)
