local function hitungNada()
idxNada = {}
for i, s in ipairs(segs) do
if s.tipe == 1 then idxNada[#idxNada + 1] = i end
end
if cur > #idxNada then cur = #idxNada end
if cur < 1 then cur = 1 end
end
local function muatSeg()
segs = {}
local f = io.open(kerja .. "/nada.txt", "r")
if not f then return end
for l in f:lines() do
local t, a, b, m, c = l:match("^(%d+);(%d+);(%d+);([%-%d%.]+);([%-%d]+)$")
if t then
segs[#segs + 1] = {tipe = tonumber(t), awal = tonumber(a), akhir = tonumber(b), midi = tonumber(m), sen = tonumber(c)}
end
end
f:close()
hitungNada()
end
local function tulisSeg()
local sb = {}
for _, s in ipairs(segs) do
sb[#sb + 1] = string.format("%d;%d;%d;%.2f;%d", s.tipe, math.floor(s.awal), math.floor(s.akhir), s.midi, math.floor(s.sen))
end
local fw = luajava.newInstance("java.io.FileWriter", fileSeg)
fw.write(luajava.newInstance("java.lang.String", table.concat(sb, "\n") .. "\n"))
fw.close()
end
