local function ketSen(sen)
if sen == 0 then return "asli" end
if sen > 0 then return "naik " .. sen .. " sen" end
return "turun " .. (-sen) .. " sen"
end
local function deskripsi()
local s = segs[idxNada[cur]]
if not s then return TEKS.tidak_ada_nada end
local asli = _G.rapikanNamaNada(s.midi)
local teks = TEKS.nada .. cur .. " dari " .. #idxNada .. ". " .. asli
if s.sen ~= 0 then teks = teks .. " menjadi " .. _G.rapikanNamaNada(s.midi + s.sen / 100) .. ", " .. ketSen(s.sen) else teks = teks .. TEKS.asli end
return teks
end
