local audTrack = nil
local audKunci = nil
local audBytes = nil
local audLen = 0
local function lepasAud()
if audTrack then
local t = audTrack
audTrack = nil
pcall(function() t.stop() end)
pcall(function() t.release() end)
end
end
local function muatAud(s)
local kunci = math.floor(s.awal) .. ":" .. math.floor(s.akhir)
if audKunci == kunci and audBytes then return end
local ByteT = luajava.bindClass("java.lang.Byte").TYPE
local raf = luajava.newInstance("java.io.RandomAccessFile", File(kerja .. "/vokal.raw"), "r")
local total = raf.length()
total = total - (total % 2)
local a = math.floor(s.awal * 44100 / 1000) * 2
local b = math.floor(s.akhir * 44100 / 1000) * 2
if b > total then b = total end
local len = b - a
if len < 400 then raf.close(); error(TEKS.nada_terlalu_pendek) end
local arr = luajava.newArray(ByteT, len)
raf.seek(a)
raf.readFully(arr)
raf.close()
pcall(function()
local nF = math.min(132, math.floor(len / 4))
local function ke16(i) local lo, hi = arr[i], arr[i + 1]; if lo < 0 then lo = lo + 256 end; return hi * 256 + lo end
local function dari16(i, v)
v = math.floor(v + 0.5)
if v < 0 then v = v + 65536 end
local lo = v % 256
local hi = math.floor(v / 256)
if lo > 127 then lo = lo - 256 end
if hi > 127 then hi = hi - 256 end
arr[i] = lo; arr[i + 1] = hi
end
for k = 0, nF - 1 do
local w = (k + 0.5) / nF
local i0 = k * 2
local i1 = len - 2 - k * 2
dari16(i0, ke16(i0) * w)
dari16(i1, ke16(i1) * w)
end
end)
audBytes = arr
audLen = len
audKunci = kunci
end
local function mainkanAud(s)
muatAud(s)
lepasAud()
local tr = luajava.newInstance("android.media.AudioTrack", 3, 44100, 4, 2, audLen, 0)
tr.write(audBytes, 0, audLen)
tr.setPlaybackRate(math.floor(44100 * 2 ^ (s.sen / 1200) + 0.5))
tr.play()
audTrack = tr
end
local liveJalan = false
local liveNadaKotor = true
local liveTunggu = false
local liveTikAktif = false
local livePosMs = 0
local function liveStatus()
local r = _G.rapikanLive("live_status")
local st, pr, ps, jl, pesan = r:match("^([^|]*)|(%-?%d+)|(%-?%d+)|(%d)|(.*)$")
if not st then return {state = "galat", persen = 0, pos = 0, jalan = false, pesan = r} end
return {state = st, persen = tonumber(pr) or 0, pos = tonumber(ps) or 0, jalan = (jl == "1"), pesan = pesan}
end
local function liveSiapPakai()
if not liveCoba then return false end
return liveStatus().state == "siap"
end
