local function putarWav(jalur, mode)
hentikan()
local mp = MediaPlayer()
local ok = pcall(function()
local fis = luajava.newInstance("java.io.FileInputStream", File(jalur))
mp.setDataSource(fis.getFD())
mp.prepare()
fis.close()
end)
if not ok then
pcall(function() mp.release() end)
bicaraLayanan(TEKS.gagal_memutar_audio)
return
end
mp.setOnCompletionListener(MediaPlayer.OnCompletionListener{
