pcall(function() m.release() end)
pemutar = nil
modePutar = nil
segarkanTombolPutar()
end
})
pemutar = mp
modePutar = mode
mp.start()
segarkanTombolPutar()
end
local function antri(kerjaFn)
if sibuk then tertunda = kerjaFn; return end
local spek = kerjaFn()
if not spek then
if tertunda then
local t = tertunda
tertunda = nil
antri(t)
end
return
end
sibuk = true
_G.rapikanAsync(spek.cmd, spek.a, spek.b, spek.c, spek.d, function(r)
sibuk = false
if spek.selesai then pcall(spek.selesai, r) end
if tertunda then
local t = tertunda
tertunda = nil
antri(t)
end
end)
end
