local function ubahSen(delta, diam)
local s = segs[idxNada[cur]]
if not s then return end
local lama = s.sen
local baru = lama + delta
if baru > _G.RAPIKAN_SEN_MAKS then baru = _G.RAPIKAN_SEN_MAKS end
if baru < -_G.RAPIKAN_SEN_MAKS then baru = -_G.RAPIKAN_SEN_MAKS end
if baru == lama then
if not diam then bicaraLayanan(TEKS.sudah_di_batas); _G.nadiGetarGerak(60) end
return
end
s.sen = baru
liveGeserSen(s)
if jadwalRun then hnd.removeCallbacks(jadwalRun); jadwalRun = nil end
mainkanLangsung(diam)
if diam then perbaruiTeks(); return end
_G.nadiGetarGerak(20)
local namaBaru = _G.rapikanNamaNada(s.midi + baru / 100)
local namaLama = _G.rapikanNamaNada(s.midi + lama / 100)
if math.abs(delta) >= _G.RAPIKAN_SEN_SEDANG or namaBaru ~= namaLama then
bicaraLayanan(namaBaru .. ", " .. ketSen(baru))
else
bicaraLayanan(ketSen(baru))
end
perbaruiTeks()
end
