local function pasangSentuh(canvas)
local jari = {}
local sudahBeraksi = false
local maks = 0
local tAwal = 0
local tapTerakhir = 0
local posDua = nil
local MIN = 80
local DIAM = 35
local STEP = 26
local scrubAktif = false
local scrubId = nil
local scrubRefY = 0
local scrubTerap = 0
local scrubUnit = 0
local scrubStep = 26
local scrubTerjadi = false
pcall(function()
canvas.setOrientation(LinearLayout.VERTICAL)
canvas.setGravity(Gravity.CENTER)
end)
tvInfo = TextView(service)
tvInfo.setTextColor(Color.parseColor("#FFFFFF"))
tvInfo.setTextSize(22)
