canvas.addView(tvInfo, LinearLayout.LayoutParams(-1, -2))
local tvBantu = TextView(service)
tvBantu.setTextColor(Color.parseColor("#888888"))
tvBantu.setTextSize(13)
tvBantu.setGravity(Gravity.CENTER)
tvBantu.setPadding(30, 30, 30, 30)
tvBantu.setText(TEKS.geser_kanan_atau_kiri_nada_berikutnya)
canvas.addView(tvBantu, LinearLayout.LayoutParams(-1, -2))
perbaruiTeks()
local function scrubGerak(ev)
if _G.RAPIKAN_USAP_TETAP then return end
local pc = ev.getPointerCount()
if not scrubAktif then
if pc < 1 or pc > 3 then return end
local idB, magB, dxB, dyB = nil, 0, 0, 0
for id, j in pairs(jari) do
local dx, dy = j.x - j.x0, j.y - j.y0
local m = math.max(math.abs(dx), math.abs(dy))
if m > magB then magB = m; idB = id; dxB = dx; dyB = dy end
end
if not idB then return end
for id, j in pairs(jari) do
if id ~= idB and math.max(math.abs(j.x - j.x0), math.abs(j.y - j.y0)) >= DIAM then return end
end
if magB < 40 or math.abs(dyB) < math.abs(dxB) * 1.2 then return end
scrubAktif = true
scrubTerjadi = true
scrubId = idB
scrubRefY = jari[idB].y
scrubTerap = 0
if pc == 1 then scrubUnit = _G.RAPIKAN_SEN_HALUS; scrubStep = 26
elseif pc == 2 then scrubUnit = _G.RAPIKAN_SEN_SEDANG; scrubStep = 45
else scrubUnit = _G.RAPIKAN_SEN_NADA; scrubStep = 180 end
return
end
local j = jari[scrubId]
if not j then return end
local x = (scrubRefY - j.y) / scrubStep
local langkah = x >= 0 and math.floor(x) or math.ceil(x)
local selisih = langkah - scrubTerap
if selisih ~= 0 then
scrubTerap = langkah
ubahSen(selisih * scrubUnit, true)
jadwalUcap()
end
end
local function selesai(lama)
local beraksi = false
if scrubTerjadi then
scrubTerjadi = false
scrubAktif = false
return false
end
local daftar = {}
for _, j in pairs(jari) do
local dx, dy = j.x - j.x0, j.y - j.y0
daftar[#daftar + 1] = {dx = dx, dy = dy, mag = math.max(math.abs(dx), math.abs(dy))}
end
local jml = math.max(maks, #daftar)
if jml == 1 and daftar[1] then
local d = daftar[1]
if d.mag < MIN then
if lama < 400 then
local now = System.currentTimeMillis()
if tapTerakhir > 0 and now - tapTerakhir < 450 then
tapTerakhir = 0
keluarKanvas()
else
tapTerakhir = now
end
end
elseif lama < 2500 then
if math.abs(d.dx) >= math.abs(d.dy) then
pindah(d.dx > 0 and 1 or -1)
else
ubahSen(d.dy < 0 and _G.RAPIKAN_SEN_HALUS or -_G.RAPIKAN_SEN_HALUS)
end
end
elseif jml == 2 and #daftar == 2 then
table.sort(daftar, function(a, b) return a.mag > b.mag end)
local besar, kecil = daftar[1], daftar[2]
if besar.mag >= MIN and kecil.mag < DIAM and math.abs(besar.dy) > math.abs(besar.dx) and lama < 8000 then
ubahSen(besar.dy < 0 and _G.RAPIKAN_SEN_SEDANG or -_G.RAPIKAN_SEN_SEDANG)
beraksi = true
jadwalCekBunyi()
elseif besar.mag < DIAM and lama < 400 then
potong(posDua)
beraksi = true
end
elseif jml == 3 and #daftar == 3 then
table.sort(daftar, function(a, b) return a.mag > b.mag end)
local besar = daftar[1]
if besar.mag >= MIN and daftar[2].mag < DIAM and daftar[3].mag < DIAM and math.abs(besar.dy) > math.abs(besar.dx) and lama < 8000 then
ubahSen(besar.dy < 0 and _G.RAPIKAN_SEN_NADA or -_G.RAPIKAN_SEN_NADA)
beraksi = true
jadwalCekBunyi()
end
end
return beraksi
end
canvas.setOnTouchListener(luajava.createProxy("android.view.View$OnTouchListener", {
onTouch = function(v, ev)
local aksi = ev.getActionMasked()
local now = System.currentTimeMillis()
if aksi == 0 then
jari = {}
maks = 1
tAwal = now
posDua = nil
sudahBeraksi = false
scrubAktif = false
scrubTerjadi = false
local id = ev.getPointerId(0)
jari[id] = {x0 = ev.getX(0), y0 = ev.getY(0), x = ev.getX(0), y = ev.getY(0)}
elseif aksi == 5 then
local idx = ev.getActionIndex()
local id = ev.getPointerId(idx)
jari[id] = {x0 = ev.getX(idx), y0 = ev.getY(idx), x = ev.getX(idx), y = ev.getY(idx)}
local n = ev.getPointerCount()
if n > maks then maks = n end
sudahBeraksi = false   
if n == 2 then posDua = posisiSaatIni() end
elseif aksi == 2 then
for i = 0, ev.getPointerCount() - 1 do
local j = jari[ev.getPointerId(i)]
if j then j.x = ev.getX(i); j.y = ev.getY(i) end
end
pcall(scrubGerak, ev)
elseif aksi == 6 then
local idx = ev.getActionIndex()
local idAngkat = ev.getPointerId(idx)
local j = jari[idAngkat]
if j then j.x = ev.getX(idx); j.y = ev.getY(idx) end
if j and not sudahBeraksi and maks >= 2 and maks <= 3 then
local magAngkat = math.max(math.abs(j.x - j.x0), math.abs(j.y - j.y0))
local terbesar = true
for id2, j2 in pairs(jari) do
if id2 ~= idAngkat and math.max(math.abs(j2.x - j2.x0), math.abs(j2.y - j2.y0)) > magAngkat then terbesar = false end
end
if magAngkat >= MIN and terbesar then
local okS, hasil = pcall(selesai, now - tAwal)
if okS and hasil then sudahBeraksi = true; jari[idAngkat] = nil end
end
end
elseif aksi == 1 then
local idx = ev.getActionIndex()
local j = jari[ev.getPointerId(idx)]
if j then j.x = ev.getX(idx); j.y = ev.getY(idx) end
local lama = now - tAwal
if not sudahBeraksi then pcall(selesai, lama) end
sudahBeraksi = false
jari = {}
maks = 0
elseif aksi == 3 then
jari = {}
maks = 0
sudahBeraksi = false
scrubAktif = false
scrubTerjadi = false
end
return true
end
}))
end
