_G.bukaPickerUniversal = function(cfg)
local path = cfg.path or "storage/emulated/0"
local jenis = cfg.jenis or "audio"
local pesanTunggu = (jenis == "video") and TEKS.mencari_file_video or ((jenis == "gambar") and TEKS.mencari_file_foto_gambar or TEKS.mencari_file_audio)
local pd = buatDialogTunggu(pesanTunggu)
task(function(p, jns, ekstra)
require "import" local TEKS = {} pcall(function() local P = luajava.bindClass("java.lang.System").getProperties().get("nadi_teks") if P then TEKS = require("cjson").decode(tostring(P)) end end) setmetatable(TEKS, {__index = function() return "" end}) 
require "import"
import "java.io.File"
local cjson = require "cjson"
local folderInfo = {}
if p ~= "storage/emulated/0" then
table.insert(folderInfo, {nama = TEKS.naik_ke_folder_sebelumnya, isUp = true, isFile = false})
end
local f = File(p)
local files = f.listFiles()
local subFolders = {}
local mediaFiles = {}
local petaFormat = {
audio = {[".mp3"]=true, [".wav"]=true, [".m4a"]=true, [".ogg"]=true, [".flac"]=true, [".aac"]=true, [".opus"]=true, [".wma"]=true, [".amr"]=true},
video = {[".mp4"]=true, [".mkv"]=true, [".webm"]=true, [".3gp"]=true, [".mov"]=true},
gambar = {[".jpg"]=true, [".jpeg"]=true, [".png"]=true, [".webp"]=true, [".bmp"]=true}
}
local formatValid = petaFormat[jns] or petaFormat.audio
if ekstra and ekstra ~= "" then
local salinan = {}
for k, v in pairs(formatValid) do salinan[k] = v end
for e in ekstra:gmatch("[^,]+") do salinan[e:lower()] = true end
formatValid = salinan
end
if files then
for i = 0, #files - 1 do
local file = files[i]
if not file.isHidden() then
if file.isDirectory() then
table.insert(subFolders, file.getName())
elseif file.isFile() then
local nama = file.getName()
local ext = nama:match("^.+(%.%w+)$")
if ext and formatValid[ext:lower()] then
table.insert(mediaFiles, nama)
end
end
end
end
end
table.sort(subFolders, function(a, b) return a:lower() < b:lower() end)
table.sort(mediaFiles, function(a, b) return a:lower() < b:lower() end)
for _, v in ipairs(subFolders) do table.insert(folderInfo, {nama = v, isUp = false, isFile = false}) end
for _, v in ipairs(mediaFiles) do table.insert(folderInfo, {nama = v, isUp = false, isFile = true, fullPath = p .. "/" .. v}) end
return cjson.encode(folderInfo)
end, path, jenis, table.concat(cfg.formatTambahan or {}, ","), function(jsonResult)
pd.dismiss()
local ok, fInfo = pcall(cjson.decode, jsonResult)
if not ok or not fInfo then fInfo = {} end
local layoutLokal = buatWadah(LinearLayout.VERTICAL, 15, 15, 15, 15)
local dialog
layoutLokal.addView(buatTeks(cfg.judul .. TEKS.path .. path, 15, 0, 0, 0, 10))
if cfg.catatan and cfg.catatan ~= "" then
layoutLokal.addView(buatTeks(cfg.catatan, 12, 0, 0, 0, 10, nil, "#888888"))
end
local selectedFiles = cfg.selectedFiles or {}
local fileTerpilih = cfg.fileTerpilih
local function getCount()
local c = 0; for _ in pairs(selectedFiles) do c = c + 1 end; return c
end
local function getStatusText()
if cfg.isMulti then
return "Terpilih: " .. getCount() .. " " .. (cfg.satuan or jenis)
else
local nama = (fileTerpilih and fileTerpilih ~= "") and (fileTerpilih:match("^.+/(.+)$") or fileTerpilih) or TEKS.belum_ada
return (cfg.labelStatus or TEKS.terpilih) .. ": " .. nama
end
end
local tvStatus = buatTeks(getStatusText(), 14, 0, 0, 0, 10, nil, "#2196F3")
layoutLokal.addView(tvStatus)
local listView = ListView(service)
local jlData = ArrayList()
local function setTextItem(item)
if item.isUp then return item.nama end
if not item.isFile then return "[Folder] " .. item.nama end
if cfg.isMulti then
if selectedFiles[item.fullPath] then return "[✓] " .. item.nama end
else
if fileTerpilih == item.fullPath then return "[✓] " .. item.nama end
end
return item.nama
end
for _, item in ipairs(fInfo) do
jlData.add(setTextItem(item))
end
local adapter = ArrayAdapter(service, android.R.layout.simple_list_item_1, jlData)
listView.setAdapter(adapter)
layoutLokal.addView(listView, LinearLayout.LayoutParams(-1, 0, 1))
local barisBtn = buatWadah(LinearLayout.HORIZONTAL, 0, 15, 0, 0, Gravity.CENTER)
barisBtn.addView(buatTombol(cfg.teksBatal or TEKS.batal, function()
dialog.dismiss()
cfg.onBatal(fileTerpilih)
end))
local btnPilih = buatTombol(cfg.teksLanjut or TEKS.pilih_lanjut)
barisBtn.addView(btnPilih)
layoutLokal.addView(barisBtn)
if cfg.isMulti then
local function segarkanDaftar()
for idx, itm in ipairs(fInfo) do jlData.set(idx - 1, setTextItem(itm)) end
adapter.notifyDataSetChanged()
tvStatus.setText(getStatusText())
end
local function tanpaSuara(fungsi)
local asli = bicaraLayanan
bicaraLayanan = function() end
local ok, err = pcall(fungsi)
bicaraLayanan = asli
return ok, err
end
local barisSemua = buatWadah(LinearLayout.HORIZONTAL, 0, 5, 0, 0, Gravity.CENTER)
barisSemua.addView(buatTombol(TEKS.pilih_semua, function()
local baru, adaFile = 0, 0
tanpaSuara(function()
for _, item in ipairs(fInfo) do
if item.isFile then
adaFile = adaFile + 1
if not selectedFiles[item.fullPath] then
cfg.onToggleMulti(item)
baru = baru + 1
end
end
end
end)
segarkanDaftar()
if adaFile == 0 then
bicaraLayanan(TEKS.tidak_ada_file_di_folder_ini)
else
bicaraLayanan(TEKS.semua .. adaFile .. TEKS.file_di_folder_ini_terpilih_total .. getCount())
end
end))
barisSemua.addView(buatTombol(TEKS.batal_pilih_semua, function()
local daftar = {}
for k, _ in pairs(selectedFiles) do daftar[#daftar + 1] = k end
if #daftar == 0 then
bicaraLayanan(TEKS.belum_ada_file_yang_terpilih)
return
end
tanpaSuara(function()
for _, k in ipairs(daftar) do
if selectedFiles[k] then
cfg.onToggleMulti({isFile = true, fullPath = k, nama = k:match("^.+/(.+)$") or k})
end
end
end)
segarkanDaftar()
bicaraLayanan(TEKS.semua_pilihan_dibatalkan_total_terpilih .. getCount())
end))
layoutLokal.addView(barisSemua)
end
pasangKlikItem(listView, function(parent, view, position, id)
local item = fInfo[position + 1]
if item.isFile then
if cfg.isMulti then
cfg.onToggleMulti(item)
jlData.set(position, setTextItem(item))
adapter.notifyDataSetChanged()
tvStatus.setText(getStatusText())
else
if fileTerpilih == item.fullPath then
fileTerpilih = nil
bicaraLayanan(TEKS.batal_pilih .. item.nama)
else
fileTerpilih = item.fullPath
bicaraLayanan(TEKS.memilih .. item.nama)
end
if cfg.onUbahTunggal then cfg.onUbahTunggal(fileTerpilih) end
for idx, itm in ipairs(fInfo) do
jlData.set(idx - 1, setTextItem(itm))
end
adapter.notifyDataSetChanged()
tvStatus.setText(getStatusText())
end
else
dialog.dismiss()
local nextPath = item.isUp and File(path).getParent() or (path .. "/" .. item.nama)
cfg.onPindahFolder(nextPath, fileTerpilih)
end
end)
btnPilih.setOnClickListener(function()
if cfg.isMulti then
cfg.onLanjut(dialog)
else
if not fileTerpilih or fileTerpilih == "" then
bicaraLayanan(cfg.pesanKosong or TEKS.silakan_pilih_1_file_terlebih_dahulu)
return
end
dialog.dismiss()
cfg.onLanjut(fileTerpilih)
end
end)
dialog = buatDialogModular(nil, layoutLokal, function(d)
d.dismiss()
if path ~= "storage/emulated/0" then
cfg.onPindahFolder(File(path).getParent(), fileTerpilih)
else
cfg.onBatal(fileTerpilih)
end
return true
end)
tampilkanDialogUtama(dialog)
end)
end
renderPickerGabungAudio = function(path, selectedFiles, urutanAwal)
selectedFiles = selectedFiles or {}
urutanAwal = urutanAwal or {}
_G.bukaPickerUniversal({
path = path, jenis = "audio", isMulti = true, satuan = "audio",
judul = TEKS.pilih_audio_untuk_digabung,
selectedFiles = selectedFiles,
onToggleMulti = function(item)
if selectedFiles[item.fullPath] then
selectedFiles[item.fullPath] = nil
for idx = #urutanAwal, 1, -1 do
if urutanAwal[idx] == item.fullPath then table.remove(urutanAwal, idx) end
end
bicaraLayanan(TEKS.batal_pilih .. item.nama)
else
selectedFiles[item.fullPath] = true
table.insert(urutanAwal, item.fullPath)
bicaraLayanan(TEKS.memilih .. item.nama)
end
end,
onPindahFolder = function(nextPath) renderPickerGabungAudio(nextPath, selectedFiles, urutanAwal) end,
onBatal = function()
if #urutanAwal > 0 then renderUIUrutanGabung(urutanAwal) else renderMenuEditor() end
end,
onLanjut = function(dialog)
local finalFiles, sudahMasuk = {}, {}
for _, k in ipairs(urutanAwal) do
if selectedFiles[k] and not sudahMasuk[k] then table.insert(finalFiles, k); sudahMasuk[k] = true end
end
for k, _ in pairs(selectedFiles) do
if not sudahMasuk[k] then table.insert(finalFiles, k); sudahMasuk[k] = true end
end
