renderPickerCampurAudio = function(path, selectedFiles, itemAwal)
selectedFiles = selectedFiles or {}
itemAwal = itemAwal or {}
_G.bukaPickerUniversal({
path = path, jenis = "audio", isMulti = true, satuan = "audio",
judul = TEKS.pilih_audio_untuk_dicampur,
catatan = TEKS.audio_pertama_yang_anda_pilih_otomatis,
selectedFiles = selectedFiles,
onToggleMulti = function(item)
if selectedFiles[item.fullPath] then
selectedFiles[item.fullPath] = nil
for idx = #itemAwal, 1, -1 do
if itemAwal[idx].path == item.fullPath then table.remove(itemAwal, idx) end
end
bicaraLayanan(TEKS.batal_pilih .. item.nama)
else
selectedFiles[item.fullPath] = true
local isPertama = (#itemAwal == 0)
table.insert(itemAwal, {path = item.fullPath, nama = item.nama, vol = isPertama and 100 or 40, loop = true, fadeMode = 1, fadeSec = 5})
bicaraLayanan(TEKS.memilih .. item.nama)
end
end,
onPindahFolder = function(nextPath) renderPickerCampurAudio(nextPath, selectedFiles, itemAwal) end,
onBatal = function()
if #itemAwal > 0 then renderUICampurAudio(itemAwal) else _G.bersihkanCacheCampur(); renderMenuEditor() end
end,
onLanjut = function(dialog)
local finalItems, sudahMasuk = {}, {}
for _, itm in ipairs(itemAwal) do
if selectedFiles[itm.path] and not sudahMasuk[itm.path] then table.insert(finalItems, itm); sudahMasuk[itm.path] = true end
end
for k, _ in pairs(selectedFiles) do
if not sudahMasuk[k] then
local namaF = k:match("^.+/(.+)$") or k
local isPertama = (#finalItems == 0)
table.insert(finalItems, {path = k, nama = namaF, vol = isPertama and 100 or 40, loop = true, fadeMode = 1, fadeSec = 5})
sudahMasuk[k] = true
end
end
if #finalItems < 2 then bicaraLayanan(TEKS.pilih_minimal_2_file_audio_untuk); return end
dialog.dismiss()
bicaraLayanan(TEKS.silakan_atur_pencampuran_dari .. #finalItems .. TEKS.audio_berikut)
renderUICampurAudio(finalItems)
end
})
end
renderUIPotongAudio = function(filePath)
local namaFile = filePath:match("^.+/(.+)$") or filePath
local durasiTotalMs = 0
pcall(function()
local mmr = MediaMetadataRetriever()
mmr.setDataSource(filePath)
local d = mmr.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION)
if d then durasiTotalMs = tonumber(d) or 0 end
mmr.release()
end)
if durasiTotalMs <= 0 then
pcall(function()
local mp = MediaPlayer()
mp.setDataSource(filePath)
mp.prepare()
durasiTotalMs = mp.getDuration() or 0
mp.release()
end)
end
if durasiTotalMs <= 0 then
bicaraLayanan(TEKS.gagal_membaca_durasi_file_audio_ini)
renderMenuEditor()
return
end
local layoutLokal = buatWadah(LinearLayout.VERTICAL, 20, 20, 20, 20)
local dialog
layoutLokal.addView(buatTeks(TEKS.memotong .. namaFile .. TEKS.durasi_total .. formatWaktuPresisi(durasiTotalMs) .. " (" .. formatLisanPresisi(durasiTotalMs) .. ")", 16, 0, 0, 0, 15))
local posisiKursorMs = 0
local tandaAwalMs = nil
local tandaAkhirMs = nil
local modeDuaTanda = 1
local tvPosisi = buatTeks(TEKS.posisi_kursor_00_00 .. formatWaktuPresisi(durasiTotalMs), 15, 0, 5, 0, 10, Gravity.CENTER, "#2196F3")
layoutLokal.addView(tvPosisi)
local seekBar = SeekBar(service)
seekBar.setMax(durasiTotalMs)
seekBar.setProgress(0)
layoutLokal.addView(seekBar)
local semuaLangkah = {
{teks = TEKS.langkah_1_milidetik, nilai = 1},
{teks = TEKS.langkah_5_milidetik, nilai = 5},
{teks = TEKS.langkah_10_milidetik, nilai = 10},
{teks = TEKS.langkah_50_milidetik, nilai = 50},
{teks = TEKS.langkah_100_milidetik, nilai = 100},
{teks = TEKS.langkah_1_detik, nilai = 1000},
{teks = TEKS.langkah_5_detik, nilai = 5000},
{teks = TEKS.langkah_10_detik, nilai = 10000},
{teks = TEKS.langkah_30_detik, nilai = 30000},
{teks = TEKS.langkah_1_menit, nilai = 60000},
{teks = TEKS.langkah_5_menit, nilai = 300000},
{teks = TEKS.langkah_10_menit, nilai = 600000},
{teks = TEKS.langkah_30_menit, nilai = 1800000},
{teks = TEKS.langkah_1_jam, nilai = 3600000}
}
local langkahTeks = {}
local langkahNilai = {}
local idxDefaultLangkah = 0
for _, item in ipairs(semuaLangkah) do
if item.nilai <= durasiTotalMs or item.nilai == 1 then
table.insert(langkahTeks, item.teks)
table.insert(langkahNilai, item.nilai)
if item.nilai == 1000 then idxDefaultLangkah = #langkahNilai - 1 end
end
end
local langkahAktifMs = langkahNilai[idxDefaultLangkah + 1] or 1000
layoutLokal.addView(buatTeks(TEKS.ukuran_langkah_geser_kursor, 13, 0, 10, 0, 5, nil, "#555555"))
local spLangkah = Spinner(service)
_G.nadiLabelSpinner(spLangkah, TEKS.ukuran_langkah_geser_kursor_2)
spLangkah.setAdapter(ArrayAdapter(service, android.R.layout.simple_spinner_dropdown_item, langkahTeks))
spLangkah.setSelection(idxDefaultLangkah)
layoutLokal.addView(spLangkah)
local barisKontrolKursor = buatWadah(LinearLayout.HORIZONTAL, 0, 10, 0, 15, Gravity.CENTER)
local btnMundur = buatTombol(TEKS.mundur)
local btnPutarKursor = buatTombol(TEKS.putar)
local btnMaju = buatTombol(TEKS.maju)
local lpKursor = LinearLayout.LayoutParams(0, -2, 1)
btnMundur.setLayoutParams(lpKursor)
btnPutarKursor.setLayoutParams(lpKursor)
btnMaju.setLayoutParams(lpKursor)
barisKontrolKursor.addView(btnMundur)
barisKontrolKursor.addView(btnPutarKursor)
barisKontrolKursor.addView(btnMaju)
layoutLokal.addView(barisKontrolKursor)
pasangPilihan(spLangkah, function(p, v, pos, id)
langkahAktifMs = langkahNilai[pos + 1] or 1000
end)
local playerKursor = MediaPlayer()
local kursorAktif = true
local diseretKursor = false
local pemutarPratinjau = nil
local filePratinjauPotong = service.getExternalFilesDir(nil).getAbsolutePath() .. "/_pv_potong.wav"
local function hentikanPratinjauHasil()
if pemutarPratinjau then
pcall(function() pemutarPratinjau.stop(); pemutarPratinjau.release() end)
pemutarPratinjau = nil
end
hapusFile(filePratinjauPotong)
end
local function hentikanSemuaAudio()
kursorAktif = false
if playerKursor then
pcall(function() if playerKursor.isPlaying() then playerKursor.stop() end; playerKursor.release() end)
playerKursor = nil
end
hentikanPratinjauHasil()
end
pcall(function()
local fis = FileInputStream(File(filePath))
playerKursor.setDataSource(fis.getFD())
playerKursor.prepare()
fis.close()
end)
local function perbaruiTampilanKursor(ms)
if ms < 0 then ms = 0 elseif ms > durasiTotalMs then ms = durasiTotalMs end
posisiKursorMs = math.floor(ms)
seekBar.setProgress(posisiKursorMs)
tvPosisi.setText(TEKS.posisi_kursor .. formatWaktuPresisi(posisiKursorMs) .. " / " .. formatWaktuPresisi(durasiTotalMs))
end
playerKursor.setOnCompletionListener(MediaPlayer.OnCompletionListener{
onCompletion = function(mp)
btnPutarKursor.setText(TEKS.putar)
perbaruiTampilanKursor(durasiTotalMs)
end
})
local updateKursorRun
updateKursorRun = Runnable({
run = function()
if kursorAktif and playerKursor then
local sedangPutar = false
pcall(function() sedangPutar = playerKursor.isPlaying() end)
if sedangPutar and not diseretKursor then
perbaruiTampilanKursor(playerKursor.getCurrentPosition())
end
handler.postDelayed(updateKursorRun, 100)
end
end
})
handler.post(updateKursorRun)
local seekKursorDebounce = Runnable({
run = function()
if kursorAktif and playerKursor then
pcall(function() playerKursor.seekTo(posisiKursorMs) end)
end
end
})
seekBar.setOnSeekBarChangeListener(SeekBar.OnSeekBarChangeListener{
onProgressChanged = function(sb, progress, fromUser)
if fromUser then
posisiKursorMs = progress
tvPosisi.setText(TEKS.posisi_kursor .. formatWaktuPresisi(posisiKursorMs) .. " / " .. formatWaktuPresisi(durasiTotalMs))
handler.removeCallbacks(seekKursorDebounce)
handler.postDelayed(seekKursorDebounce, 150)
end
end,
onStartTrackingTouch = function(sb) diseretKursor = true end,
onStopTrackingTouch = function(sb)
diseretKursor = false
posisiKursorMs = sb.getProgress()
handler.removeCallbacks(seekKursorDebounce)
if playerKursor then pcall(function() playerKursor.seekTo(posisiKursorMs) end) end
bicaraLayanan(formatLisanPresisi(posisiKursorMs))
end
})
btnPutarKursor.setOnClickListener(function()
hentikanPratinjauHasil()
if not playerKursor then return end
if playerKursor.isPlaying() then
playerKursor.pause()
perbaruiTampilanKursor(playerKursor.getCurrentPosition())
btnPutarKursor.setText(TEKS.putar)
bicaraLayanan(TEKS.dijeda_di .. formatLisanPresisi(posisiKursorMs))
else
if posisiKursorMs >= durasiTotalMs then perbaruiTampilanKursor(0) end
pcall(function() playerKursor.seekTo(posisiKursorMs) end)
playerKursor.start()
btnPutarKursor.setText(TEKS.jeda)
end
end)
local function geserKursor(deltaMs)
if playerKursor and playerKursor.isPlaying() then
posisiKursorMs = playerKursor.getCurrentPosition()
end
local targetBaru = posisiKursorMs + deltaMs
if targetBaru < 0 then targetBaru = 0 elseif targetBaru > durasiTotalMs then targetBaru = durasiTotalMs end
perbaruiTampilanKursor(targetBaru)
if playerKursor then pcall(function() playerKursor.seekTo(posisiKursorMs) end) end
bicaraLayanan(formatLisanPresisi(posisiKursorMs))
end
