renderUIPotongVideo = function(filePath)
local namaFile = filePath:match("^.+/(.+)$") or filePath
local durasiTotalMs = 0
pcall(function()
local mmr = MediaMetadataRetriever()
mmr.setDataSource(filePath)
local d = mmr.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION)
if d then durasiTotalMs = tonumber(d) or 0 end
mmr.release()
end)
if durasiTotalMs <= 0 then
pcall(function()
local mp = MediaPlayer()
mp.setDataSource(filePath)
mp.prepare()
durasiTotalMs = mp.getDuration() or 0
mp.release()
end)
end
if durasiTotalMs <= 0 then
bicaraLayanan(TEKS.gagal_membaca_durasi_file_video_ini)
renderMenuEditor()
return
end
