handler.removeCallbacks(seekKursorDebounce)
handler.postDelayed(seekKursorDebounce, 150)
end
end,
onStartTrackingTouch = function(sb) diseretKursor = true end,
onStopTrackingTouch = function(sb)
diseretKursor = false
posisiKursorMs = sb.getProgress()
handler.removeCallbacks(seekKursorDebounce)
if playerKursor then pcall(function() playerKursor.seekTo(posisiKursorMs) end) end
bicaraLayanan(formatLisanPresisi(posisiKursorMs))
end
})
