end
return true, string.format(
TEKS.tanda_awal_belum_diatur_tanda_akhir,
formatWaktuPresisi(tandaAkhirMs), formatWaktuPresisi(tandaAkhirMs), formatWaktuPresisi(tandaAkhirMs), formatWaktuPresisi(durasiTotalMs), formatLisanPresisi(durHasil)
), 1, 0, tandaAkhirMs
else
if tandaAwalMs >= tandaAkhirMs then
return false, string.format(
TEKS.tidak_valid_tanda_awal_harus_lebih,
formatWaktuPresisi(tandaAwalMs), formatWaktuPresisi(tandaAkhirMs)
), nil, nil, nil
end
if modeDuaTanda == 1 then
local durHasil = tandaAwalMs + (durasiTotalMs - tandaAkhirMs)
if durHasil <= 0 then
return false, TEKS.tidak_valid_tanda_awal_di_00_2, nil, nil, nil
end
return true, string.format(
TEKS.tanda_awal_tanda_akhir_aksi_menghapus,
formatWaktuPresisi(tandaAwalMs), formatWaktuPresisi(tandaAkhirMs), formatWaktuPresisi(tandaAwalMs), formatWaktuPresisi(tandaAkhirMs), formatLisanPresisi(durHasil)
), 2, tandaAwalMs, tandaAkhirMs
else
local durHasil = tandaAkhirMs - tandaAwalMs
return true, string.format(
TEKS.tanda_awal_tanda_akhir_aksi_mengambil,
formatWaktuPresisi(tandaAwalMs), formatWaktuPresisi(tandaAkhirMs), formatWaktuPresisi(tandaAwalMs), formatWaktuPresisi(tandaAkhirMs), formatLisanPresisi(durHasil)
), 1, tandaAwalMs, tandaAkhirMs
end
end
end
