renderUIMusikVideo = function(videoPath, musikPath, stateLama)
local namaVideo = videoPath:match("^.+/(.+)$") or videoPath
local namaMusik = musikPath:match("^.+/(.+)$") or musikPath
local durasiVideoMs = 0
pcall(function()
local mmr = MediaMetadataRetriever()
mmr.setDataSource(videoPath)
local d = mmr.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION)
if d then durasiVideoMs = tonumber(d) or 0 end
mmr.release()
end)
if durasiVideoMs <= 0 then
pcall(function()
local mp = MediaPlayer()
mp.setDataSource(videoPath)
mp.prepare()
durasiVideoMs = mp.getDuration() or 0
mp.release()
end)
end
if durasiVideoMs <= 0 then durasiVideoMs = 10000 end
local st = stateLama or {}
local volVid = (st.volVid ~= nil) and st.volVid or 100
local volMus = (st.volMus ~= nil) and st.volMus or 30
local loopMus = (st.loopMus ~= nil) and st.loopMus or true
local fadeMode = (st.fadeMode ~= nil) and st.fadeMode or 1
local fadeSec = (st.fadeSec ~= nil) and st.fadeSec or 5
local layoutLokal = buatWadah(LinearLayout.VERTICAL, 20, 20, 20, 20)
local dialog
local pemutarPratinjau = nil
local filePratinjauCampur = service.getExternalFilesDir(nil).getAbsolutePath() .. "/_pv_musik_vid_10d.wav"
local function hentikanPratinjau()
if pemutarPratinjau then
pcall(function() pemutarPratinjau.stop(); pemutarPratinjau.release() end)
pemutarPratinjau = nil
end
hapusFile(filePratinjauCampur)
end
local function ambilStateSekarang()
return {
volVid = volVid,
volMus = volMus,
loopMus = loopMus,
fadeMode = fadeMode,
fadeSec = fadeSec
}
end
