renderPickerGabungVideo = function(path, selectedFiles, urutanAwal)
selectedFiles = selectedFiles or {}
urutanAwal = urutanAwal or {}
_G.bukaPickerUniversal({
path = path, jenis = "video", isMulti = true, satuan = "video",
judul = TEKS.pilih_video_untuk_digabung,
selectedFiles = selectedFiles,
onToggleMulti = function(item)
if selectedFiles[item.fullPath] then
selectedFiles[item.fullPath] = nil
for idx = #urutanAwal, 1, -1 do
if urutanAwal[idx] == item.fullPath then table.remove(urutanAwal, idx) end
end
bicaraLayanan(TEKS.batal_pilih .. item.nama)
else
selectedFiles[item.fullPath] = true
table.insert(urutanAwal, item.fullPath)
bicaraLayanan(TEKS.memilih .. item.nama)
end
end,
onPindahFolder = function(nextPath) renderPickerGabungVideo(nextPath, selectedFiles, urutanAwal) end,
onBatal = function()
if #urutanAwal > 0 then renderUIUrutanGabungVideo(urutanAwal) else renderMenuEditor() end
end,
onLanjut = function(dialog)
local finalFiles, sudahMasuk = {}, {}
for _, k in ipairs(urutanAwal) do
if selectedFiles[k] and not sudahMasuk[k] then table.insert(finalFiles, k); sudahMasuk[k] = true end
end
for k, _ in pairs(selectedFiles) do
if not sudahMasuk[k] then table.insert(finalFiles, k); sudahMasuk[k] = true end
end
if #finalFiles < 2 then bicaraLayanan(TEKS.pilih_minimal_2_file_video_untuk); return end
dialog.dismiss()
bicaraLayanan(TEKS.silakan_atur_urutan_dan_resolusi_dari .. #finalFiles .. TEKS.video_berikut)
renderUIUrutanGabungVideo(finalFiles)
end
})
end
renderUIAudioKeVideo = function(audioPath, stateLama)
local namaAudio = audioPath:match("^.+/(.+)$") or audioPath
local judulBawaan = namaAudio:gsub("%.[^%.]+$", "")
local durasiAudioMs = 0
pcall(function()
local mmr = MediaMetadataRetriever()
mmr.setDataSource(audioPath)
local d = mmr.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION)
if d then durasiAudioMs = tonumber(d) or 0 end
mmr.release()
end)
local st = stateLama or {}
local modeVisual = (st.modeVisual ~= nil) and st.modeVisual or 1
local pathGambar = st.pathGambar or ""
local idxOrientasi = (st.idxOrientasi ~= nil) and st.idxOrientasi or 0
local idxResolusi = (st.idxResolusi ~= nil) and st.idxResolusi or 1
local idxSample = (st.idxSample ~= nil) and st.idxSample or 3
local idxChannel = (st.idxChannel ~= nil) and st.idxChannel or 1
local layoutLokal = buatWadah(LinearLayout.VERTICAL, 20, 20, 20, 20)
local dialog
local pemutarAudio = nil
local function hentikanPratinjau()
if pemutarAudio then
pcall(function() pemutarAudio.stop(); pemutarAudio.release() end)
pemutarAudio = nil
end
end
local spVisual, spOrientasi, spResolusi, spSample, spChannel
local function ambilStateSekarang()
return {
modeVisual = modeVisual,
pathGambar = pathGambar,
idxOrientasi = spOrientasi and spOrientasi.getSelectedItemPosition() or idxOrientasi,
idxResolusi = spResolusi and spResolusi.getSelectedItemPosition() or idxResolusi,
idxSample = spSample and spSample.getSelectedItemPosition() or idxSample,
idxChannel = spChannel and spChannel.getSelectedItemPosition() or idxChannel
}
end
