local function hitungDimensiVideo()
local ori = spOrientasi.getSelectedItemPosition()
local res = spResolusi.getSelectedItemPosition()
local pendek = {1088, 720, 480, 368}
local panjang = {1920, 1280, 848, 640}
local p = pendek[res + 1] or 720
local l = panjang[res + 1] or 1280
if ori == 0 then
return p, l
elseif ori == 1 then
return l, p
else
return p, p
end
end
