renderUIVideoKeAudio = function(videoPath)
local namaVideo = videoPath:match("^.+/(.+)$") or videoPath
local judulBawaan = namaVideo:gsub("%.[^%.]+$", "")
local durasiVideoMs = 0
pcall(function()
local mmr = MediaMetadataRetriever()
mmr.setDataSource(videoPath)
local d = mmr.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION)
if d then durasiVideoMs = tonumber(d) or 0 end
mmr.release()
end)
local layoutLokal = buatWadah(LinearLayout.VERTICAL, 20, 20, 20, 20)
local dialog
local pemutarSuara = nil
local function hentikanPratinjau()
if pemutarSuara then
pcall(function() pemutarSuara.stop(); pemutarSuara.release() end)
pemutarSuara = nil
end
end
layoutLokal.addView(buatTeks(TEKS.ubah_video_ke_audio_m4a, 18, 0, 0, 0, 10))
layoutLokal.addView(buatTeks(
TEKS.video_sumber .. namaVideo .. (durasiVideoMs > 0 and (" (" .. formatWaktu(durasiVideoMs) .. ")") or ""),
14, 0, 0, 0, 10, nil, "#2196F3"
))
local barisKontrol = buatWadah(LinearLayout.HORIZONTAL, 0, 0, 0, 15, Gravity.CENTER)
local btnPutar = buatTombol(TEKS.dengar_suara_video, function()
hentikanPratinjau()
pemutarSuara = MediaPlayer()
local okP = pcall(function()
pemutarSuara.setDataSource(videoPath)
pemutarSuara.prepare()
pemutarSuara.start()
bicaraLayanan(TEKS.memutar_suara_video)
end)
if not okP then bicaraLayanan(TEKS.gagal_memutar_suara_video) end
end)
local btnHenti = buatTombol(TEKS.hentikan, function()
hentikanPratinjau()
bicaraLayanan(TEKS.dihentikan)
end)
local btnGanti = buatTombol(TEKS.ganti_video, function()
hentikanPratinjau()
dialog.dismiss()
renderPickerVideoKeAudio("storage/emulated/0", videoPath)
end)
local lp3 = LinearLayout.LayoutParams(0, -2, 1)
btnPutar.setLayoutParams(lp3)
btnHenti.setLayoutParams(lp3)
btnGanti.setLayoutParams(lp3)
barisKontrol.addView(btnPutar)
barisKontrol.addView(btnHenti)
barisKontrol.addView(btnGanti)
layoutLokal.addView(barisKontrol)
layoutLokal.addView(buatTeks(TEKS.pengaturan_kualitas_audio_hasil_m4a, 14, 0, 10, 0, 5, nil, "#2196F3"))
local barisTarget = buatWadah(LinearLayout.HORIZONTAL, 0, 0, 0, 15)
local spSample = buatSpinner({"8000 Hz", "16000 Hz", "22050 Hz", "44100 Hz", "48000 Hz"}, 3)
local sampleData = {8000, 16000, 22050, 44100, 48000}
local spChannel = buatSpinner({"Mono", TEKS.stereo}, 1)
local channelData = {1, 2}
local spBitrate = buatSpinner({"32 kbps", "64 kbps", "96 kbps", "128 kbps", "192 kbps", "256 kbps", "320 kbps"}, 3)
local bitrateNilai = {32000, 64000, 96000, 128000, 192000, 256000, 320000}
barisTarget.addView(spSample)
barisTarget.addView(spChannel)
barisTarget.addView(spBitrate)
layoutLokal.addView(barisTarget)
_G.nadiSpFormat = _G.nadiTambahPilihFormat(layoutLokal)
local btnEksekusi = buatTombol(TEKS.jadikan_audio_sekarang, function()
hentikanPratinjau()
local cSample = sampleData[spSample.getSelectedItemPosition() + 1]
local cChannel = channelData[spChannel.getSelectedItemPosition() + 1]
local cBitrate = bitrateNilai[spBitrate.getSelectedItemPosition() + 1] or 128000
buatDialogInput(TEKS.nama_file_audio_baru, judulBawaan .. "_audio", TEKS.mulai_proses, TEKS.batal, true, function(d, namaInp)
if namaInp == "" then namaInp = "Video_Audio" end
local outDir = "storage/emulated/0/Audio Nadi/Video ke Audio"
File(outDir).mkdirs()
local finalPath = outDir .. "/" .. namaInp .. ".m4a"
_G.nadiSetTujuan(_G.nadiSpFormat, cBitrate, false)
local progStatusFile = service.getExternalFilesDir(nil).getAbsolutePath() .. "/_editor_status.txt"
hapusFile(progStatusFile)
d.dismiss()
dialog.dismiss()
mulaiProsesEditor("video_ke_audio", finalPath)
_G.eksekusiVideoKeAudio(videoPath, finalPath, cSample, cChannel, cBitrate, progStatusFile,
function() selesaiProsesEditor(progStatusFile, TEKS.berhasil_audio_hasil_ekstraksi_disimpan) end,
function(err) gagalProsesEditor(progStatusFile, TEKS.gagal_mengubah_video_ke_audio, err) end)
end)
end)
btnEksekusi.setBackgroundColor(Color.parseColor("#4CAF50"))
btnEksekusi.setTextColor(Color.WHITE)
layoutLokal.addView(btnEksekusi)
layoutLokal.addView(buatTombolKeluar(TEKS.batal_kembali, function()
hentikanPratinjau()
dialog.dismiss()
renderMenuEditor()
end))
local sv = buatScroll(layoutLokal)
dialog = buatDialogEditor(nil, sv, function(d)
hentikanPratinjau()
d.dismiss()
renderMenuEditor()
return true
end, function(d)
hentikanPratinjau()
end)
tampilkanDialogUtama(dialog)
end
