_G.nadiTambahPilihFormat = function(layout)
local teks = {TEKS.m4a_bawaan}
for _, f in ipairs(_G.nadiFormatSimpanLain) do teks[#teks + 1] = f[2] end
layout.addView(buatTeks(TEKS.format_hasil, 14, 0, 0, 0, 4, nil, "#2196F3"))
local idx = prefs.getInt("fmt_editor", 0)
if idx < 0 or idx > #_G.nadiFormatSimpanLain then idx = 0 end
local sp = buatSpinner(teks, idx)
sp.setLayoutParams(LinearLayout.LayoutParams(-1, -2))
_G.nadiLabelSpinner(sp, TEKS.format_hasil_2)
layout.addView(sp)
layout.addView(buatTeks(TEKS.pilih_m4a_untuk_memakai_format_bawaan, 13, 0, 4, 0, 10, nil, "#888888"))
return sp
end
_G.nadiSetTujuan = function(sp, bitrate, isVid)
_G.nadiFormatTujuan = nil
if isVid or sp == nil then return end
local pos = sp.getSelectedItemPosition()
prefs.edit().putInt("fmt_editor", pos).apply()
if pos > 0 then
local f = _G.nadiFormatSimpanLain[pos]
_G.nadiFormatTujuan = {f[1], f[2], f[3], bitrate}
end
end
_G.nadiBersihkanNama = function(namaInp)
return (tostring(namaInp or ""):gsub('[/\\:%*%?"<>|%c]', ""):gsub("^%s+", ""):gsub("%s+$", ""))
end
_G.nadiBuatDaftarKeluar = function(daftarFile, namaBersih, outDir, ext)
File(outDir).mkdirs()
local total = #daftarFile
local daftarKeluar = {}
local dipakai = {}
for i, jalur in ipairs(daftarFile) do
local asli = (jalur:match("^.+/(.+)$") or jalur):gsub("%.[^%.]+$", "")
local dasar = asli
if namaBersih ~= "" then
if total > 1 then dasar = namaBersih .. " " .. i else dasar = namaBersih end
end
local calon = outDir .. "/" .. dasar .. ext
local n = 2
while File(calon).exists() or dipakai[calon] do
calon = outDir .. "/" .. dasar .. " (" .. n .. ")" .. ext
n = n + 1
end
dipakai[calon] = true
table.insert(daftarKeluar, calon)
end
return daftarKeluar
end
_G.nadiBarisPilihan = function(layout, label, daftarTeks, indeks)
layout.addView(buatTeks(label, 14, 0, 10, 0, 4, nil, "#2196F3"))
local sp = buatSpinner(daftarTeks, indeks)
sp.setLayoutParams(LinearLayout.LayoutParams(-1, -2))
_G.nadiLabelSpinner(sp, label)
layout.addView(sp)
return sp
end
_G.nadiAmbilIndeks = function(kunci, jumlah, bawaan)
local v = prefs.getInt(kunci, bawaan)
if v < 0 or v >= jumlah then v = bawaan end
return v
end
_G.renderPickerKonversiAudio = function(path, selectedFiles, urutanAwal, tujuan)
selectedFiles = selectedFiles or {}
urutanAwal = urutanAwal or {}
tujuan = tujuan or "konversi_audio"
local jenisBerkas = "audio"
local judulPicker = TEKS.pilih_audio_yang_akan_dikonversi
if tujuan == "kompres_audio" then judulPicker = TEKS.pilih_audio_yang_akan_dikompres end
if tujuan == "kompres_video" then jenisBerkas = "video"; judulPicker = TEKS.pilih_video_yang_akan_dikompres end
_G.bukaPickerUniversal({
path = path, jenis = jenisBerkas, isMulti = true, satuan = jenisBerkas,
formatTambahan = (jenisBerkas == "audio") and {".aiff", ".aif", ".aifc", ".caf"} or nil,
judul = judulPicker,
selectedFiles = selectedFiles,
onToggleMulti = function(item)
if selectedFiles[item.fullPath] then
selectedFiles[item.fullPath] = nil
for idx = #urutanAwal, 1, -1 do
if urutanAwal[idx] == item.fullPath then table.remove(urutanAwal, idx) end
end
bicaraLayanan(TEKS.batal_pilih .. item.nama)
else
selectedFiles[item.fullPath] = true
table.insert(urutanAwal, item.fullPath)
bicaraLayanan(TEKS.memilih .. item.nama)
end
end,
onPindahFolder = function(nextPath) _G.renderPickerKonversiAudio(nextPath, selectedFiles, urutanAwal, tujuan) end,
onBatal = function() renderMenuEditor() end,
onLanjut = function(dialog)
local finalFiles, sudahMasuk = {}, {}
for _, k in ipairs(urutanAwal) do
if selectedFiles[k] and not sudahMasuk[k] then table.insert(finalFiles, k); sudahMasuk[k] = true end
end
for k, _ in pairs(selectedFiles) do
if not sudahMasuk[k] then table.insert(finalFiles, k); sudahMasuk[k] = true end
end
if #finalFiles == 0 then bicaraLayanan(TEKS.anda_belum_memilih_file .. jenisBerkas .. TEKS.apa_pun); return end
dialog.dismiss()
if tujuan == "kompres_audio" then
_G.renderUIKompresAudio(finalFiles)
elseif tujuan == "kompres_video" then
_G.renderUIKompresVideo(finalFiles)
else
_G.renderUIKonversiAudio(finalFiles)
end
end
})
end
