_G.renderInfoMesin = function()
local judulDaftar = {TEKS.format_yang_bisa_dibuat_muxers, TEKS.format_yang_bisa_dibaca_demuxers, TEKS.pengubah_suara_dan_video_encoders, TEKS.pembaca_suara_dan_video_decoders, TEKS.efek_dan_filter_filters, TEKS.semua_kodek_codecs}
local kunciDaftar = {"muxers", "demuxers", "encoders", "decoders", "filters", "codecs"}
buatDialogPilihan(TEKS.lihat_kemampuan_mesin_konversi, judulDaftar, -1, function(dPil, which)
dPil.dismiss()
local kunci = kunciDaftar[which + 1]
local judulPilih = judulDaftar[which + 1]
local pd = buatDialogTunggu(TEKS.mengambil_daftar_mohon_tunggu)
File("storage/emulated/0/Audio Nadi/Info Mesin").mkdirs()
local pathTxt = "storage/emulated/0/Audio Nadi/Info Mesin/" .. kunci .. ".txt"
local progStatusFile = service.getExternalFilesDir(nil).getAbsolutePath() .. "/_editor_status.txt"
_G.eksekusiKonversiAudio({kunci}, {pathTxt}, "", 0, 0, 0, progStatusFile,
function()
pd.dismiss()
hapusFile(progStatusFile)
local isi = ""
pcall(function()
local br = luajava.newInstance("java.io.BufferedReader", luajava.newInstance("java.io.InputStreamReader", luajava.newInstance("java.io.FileInputStream", File(pathTxt)), "UTF-8"))
local baris = br.readLine()
local kumpul = {}
while baris ~= nil do
kumpul[#kumpul + 1] = tostring(baris)
baris = br.readLine()
end
br.close()
isi = table.concat(kumpul, "\n")
end)
local layInfo = buatWadah(LinearLayout.VERTICAL, 20, 20, 20, 20)
layInfo.addView(buatTeks(TEKS.daftar_ini_juga_disimpan_sebagai_berkas .. pathTxt, 13, 0, 0, 0, 10, nil, "#888888"))
layInfo.addView(buatTeks(isi, 12, 0, 0, 0, 10))
local dlgInfo
layInfo.addView(buatTombol(TEKS.tutup, function() dlgInfo.dismiss() end))
dlgInfo = buatDialogKustom(judulPilih, buatScroll(layInfo))
end,
function(err)
pd.dismiss()
hapusFile(progStatusFile)
bicaraLayanan(TEKS.gagal_mengambil_daftar .. tostring(err))
end, "info")
end)
end
_G.renderUIKonversiAudio = function(daftarFile)
local daftarFormat = {
{"mp3", "MP3", ".mp3", ""},
{"m4a", TEKS.m4a_aac, ".m4a", ""},
{"aac", TEKS.aac_adts, ".aac", TEKS.aac_mentah_tanpa_wadah_m4a_cocok},
{"ogg", TEKS.ogg_vorbis, ".ogg", ""},
{"opus", "OPUS", ".opus", TEKS.opus_hanya_mendukung_sample_rate_8000},
{"wav", TEKS.wav_tanpa_kompresi_2, ".wav", TEKS.wav_tanpa_kompresi_pengaturan_bitrate_di},
{"flac", TEKS.flac_lossless_2, ".flac", TEKS.flac_dikompres_tanpa_mengurangi_kualitas},
{"alac", TEKS.alac_lossless_m4a_2, ".m4a", TEKS.alac_dikompres_tanpa_mengurangi_kualitas},
{"wma", "WMA", ".wma", ""},
{"amr", TEKS.amr_khusus_suara, ".amr", TEKS.amr_hanya_untuk_suara_selalu_mono},
{"awb", TEKS.amr_wb_khusus_suara, ".awb", TEKS.amr_wb_hanya_untuk_suara_selalu},
{"ac3", "AC3", ".ac3", TEKS.ac3_hanya_mendukung_sample_rate_32000},
{"mp2", "MP2", ".mp2", ""},
{"aiff", TEKS.aiff_tanpa_kompresi_2, ".aiff", TEKS.aiff_tanpa_kompresi_pengaturan_bitrate_d}
}
