local channelData = {1, 2}
local wadahDaftarSegmen = buatWadah(LinearLayout.VERTICAL, 0, 5, 0, 10)
local bukaDialogKelolaSegmen
local namaNadaDasarAt = {"C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"}
local namaTanggaNadaAt = {TEKS.kromatik_otomatis_semua_nada, TEKS.mayor, TEKS.minor}
local function ringkasEfekSegmen(fx)
if not fx then return TEKS.belum_ada_efek end
local list = {}
if fx.gate then table.insert(list, TEKS.noise_gate .. tostring(fx.gate.thresh) .. "%)") end
if fx.pitch then table.insert(list, TEKS.pitch .. string.format("%+d", tonumber(fx.pitch.semitone) or 0) .. ")") end
if fx.autotune then
local kName = namaNadaDasarAt[(tonumber(fx.autotune.key) or 0) + 1] or "C"
local sIdx = tonumber(fx.autotune.scale) or 0
local labelSkala = (sIdx == 0) and TEKS.kromatik or (kName .. " " .. (sIdx == 1 and TEKS.mayor or TEKS.minor))
table.insert(list, TEKS.auto_tune .. labelSkala .. ", " .. tostring(fx.autotune.speed or 80) .. "%)")
end
if fx.reverb then table.insert(list, TEKS.reverb .. tostring(fx.reverb.wet) .. "%)") end
if fx.echo then table.insert(list, TEKS.echo .. tostring(fx.echo.delay) .. TEKS.ms) end
if fx.suaradua then table.insert(list, TEKS.suara_dua) end
if fx.sensor then table.insert(list, TEKS.sensor_suara) end
if fx.bt then table.insert(list, TEKS.bass_treble) end
if fx.eq then table.insert(list, TEKS.equalizer_5_band) end
if #list == 0 then return TEKS.belum_ada_efek_ketuk_untuk_tambah end
return table.concat(list, ", ")
end
local function punyaMinimalSatuEfek(fx)
return fx and (fx.gate or fx.pitch or fx.autotune or fx.reverb or fx.echo or fx.bt or fx.eq or fx.suaradua or fx.sensor) ~= nil
end
