local function sliderGate(label, curVal, maxVal, unit, cb)
local lay = buatWadah(LinearLayout.VERTICAL, 0, 10, 0, 10)
local tv = buatTeks(label .. ": " .. curVal .. unit, 14)
local sb = _G.nadiStepperBar(maxVal, curVal)
_G.nadiPasangStepper(sb, function(s, prog, fromUser)
tv.setText(label .. ": " .. prog .. unit); cb(prog)
if fromUser then bicaraLayanan(prog .. (unit == " ms" and " milidetik" or " persen")) end
end)
lay.addView(tv); lay.addView(sb.view); pLayout.addView(lay)
end
sliderGate(TEKS.sensitivitas_kebisingan, g.thresh, 100, "%", function(v) g.thresh = v; if ctrlPt then ctrlPt.ubah() end end)
