local barisBtn = buatWadah(LinearLayout.HORIZONTAL, 0, 0, 0, 10, Gravity.CENTER)
barisBtn.addView(buatTombol(TEKS.turunkan, function()
p.semitone = p.semitone - 1
p.val = p.semitone
