local pNames = {}
for _, pr in ipairs(pData) do table.insert(pNames, pr.nama) end
buatDialogPilihan(TEKS.pilih_preset_pitch, pNames, -1, function(d, w)
local tgt = pData[w + 1]
if tgt then
if tgt.lj then
for k, v in pairs(tgt.lj) do p[k] = v end
else
p.val = tonumber(tgt.nilai) or 0
p.glOn = false
p.lanjut = false
end
p.semitone = math.floor((p.val or 0) + 0.5)
wadahPLseg.removeAllViews()
_G.nadiBangunUiPitchLanjut(wadahPLseg, p, function() end, {cek = true, onUbah = function() if ctrlPt then ctrlPt.ubah() end end, onMode = function(on)
tvPitchVal.setVisibility(on and View.GONE or View.VISIBLE)
barisBtn.setVisibility(on and View.GONE or View.VISIBLE)
end})
if ctrlPt then ctrlPt.ubah() end
bicaraLayanan(TEKS.preset .. tgt.nama .. TEKS.diterapkan)
end
d.dismiss()
end)
end))
