local ljSalinSeg = {}
for k, v in pairs({lanjut = p.lanjut, val = p.val, glOn = p.glOn, g0 = p.g0, g1 = p.g1, gd = p.gd, langkah = p.langkah}) do ljSalinSeg[k] = v end
table.insert(pData, {nama = nama, nilai = p.semitone, lj = ljSalinSeg})
simpanJson("pitch_presets", pData)
bicaraLayanan(TEKS.preset_disimpan)
d.dismiss()
end
end)
end))
