local Typeface = luajava.bindClass("android.graphics.Typeface")
local ttsPrefs = service.getSharedPreferences("nadi tts SDP", Context.MODE_PRIVATE)
local function simpanTts(k, v) ttsPrefs.edit().putString(k, tostring(v)).apply() end
local function ambilTts(k, def) return tostring(ttsPrefs.getString(k, tostring(def))) end
local function ambilKelasTTSJava()
local stamp = tostring(luajava.bindClass("java.io.File")(_G.jalurDexNadi).lastModified())
if _G.kelasTtsJava and _G.kelasTtsJavaStamp == stamp then return _G.kelasTtsJava end
local odexDir = jalurOdex()
local cL = luajava.bindClass("dalvik.system.DexClassLoader")(_G.jalurDexNadi, odexDir, nil, service.getClassLoader())
_G.kelasTtsJava = cL.loadClass("FastMuxer")
_G.kelasTtsJavaStamp = stamp
_G.metodeTtsJava = nil
return _G.kelasTtsJava
end
local function panggilTTSJava(aksi, ...)
local bagian = {...}
for i = 1, select("#", ...) do
local v = bagian[i]
if v == nil then v = "" end
bagian[i] = tostring(v)
end
local data = table.concat(bagian, string.char(31))
local ok, res = pcall(function()
local kls = ambilKelasTTSJava()
if not _G.metodeTtsJava then
local tipe = luajava.newArray(luajava.bindClass("java.lang.Class"), 3)
tipe[0] = luajava.bindClass("android.content.Context")
tipe[1] = luajava.bindClass("java.lang.String")
tipe[2] = luajava.bindClass("java.lang.String")
_G.metodeTtsJava = kls.getDeclaredMethod("ttsPerintah", tipe)
end
local args = luajava.newArray(luajava.bindClass("java.lang.Object"), 3)
args[0] = service
args[1] = aksi
args[2] = data
return tostring(_G.metodeTtsJava.invoke(nil, args))
end)
if ok then return res end
return "GAGAL: " .. tostring(res)
end
local function pecahBarisTTS(teks)
local hasil = {}
for baris in (teks .. "\n"):gmatch("(.-)\n") do
local a, b = baris:match("^(.-)\t(.*)$")
if a and b and a ~= "" then table.insert(hasil, {a, b}) end
end
return hasil
end
