panggilTTSJava("terapkan", ambilTts("suara", ""), ambilTts("kecepatan", "50"), ambilTts("nada", "50"), ambilTts("bahasaKey", ""))
end
local function bicaraTTSStatus(teks, flush)
if not teks or teks == "" then return TEKS.gagal_teks_kosong end
return panggilTTSJava("bicara", teks, flush and "1" or "0", ambilTts("mesin", ""), ambilTts("suara", ""), ambilTts("kecepatan", "50"), ambilTts("nada", "50"), ambilTts("bahasaKey", ""))
end
local function hentikanTTSStatus() panggilTTSJava("henti") end
local function lepasTTSStatus() panggilTTSJava("lepas") end
local function awasiHasilTTS()
local cek = 0
local siapBerturut = 0
local loopAwas
loopAwas = Runnable({run = function()
cek = cek + 1
local stt = panggilTTSJava("status")
if stt:sub(1, 5) == "GAGAL" then
bicaraLayanan(TEKS.tts_gagal .. stt:sub(8))
return
end
if stt == "SIAP" then siapBerturut = siapBerturut + 1 end
if siapBerturut >= 2 or cek >= 40 or stt == "KOSONG" then return end
handler.postDelayed(loopAwas, 700)
end})
handler.postDelayed(loopAwas, 700)
end
local function dengarTeksTTS(teks)
local r = bicaraTTSStatus(teks, true)
if r:sub(1, 5) == "GAGAL" then
bicaraLayanan(TEKS.tts_gagal .. r:sub(8))
return
end
awasiHasilTTS()
end
