local function perbaikiHeaderWav(path)
local okFix, hasil = pcall(function()
local f = File(path)
local panjang = f.length()
local pNum = tonumber(panjang) or 0
if pNum <= 44 then return TEKS.file_terlalu_kecil end
local raf = luajava.newInstance("java.io.RandomAccessFile", f, "rw")
local batas = (pNum < 256) and math.floor(pNum) or 256
local arr = luajava.newArray(luajava.bindClass("java.lang.Byte").TYPE, batas)
raf.seek(0)
raf.read(arr)
local isWav = (arr[0] == 82 and arr[1] == 73 and arr[2] == 70 and arr[3] == 70)
if not isWav then
raf.close()
local fis = luajava.newInstance("java.io.FileInputStream", f)
local pcmData = luajava.newArray(luajava.bindClass("java.lang.Byte").TYPE, pNum)
fis.read(pcmData)
fis.close()
local fos = luajava.newInstance("java.io.FileOutputStream", f)
local ByteBuffer = luajava.bindClass("java.nio.ByteBuffer")
local ByteOrder = luajava.bindClass("java.nio.ByteOrder")
local String = luajava.bindClass("java.lang.String")
local sR = 22050
local ch = 1
local byteRate = 16 * sR * ch / 8
local buffer = ByteBuffer.allocate(44).order(ByteOrder.LITTLE_ENDIAN)
buffer.put(String("RIFF").getBytes()); buffer.putInt(pNum + 36)
buffer.put(String("WAVE").getBytes()); buffer.put(String("fmt ").getBytes())
buffer.putInt(16); buffer.putShort(1); buffer.putShort(ch)
buffer.putInt(sR); buffer.putInt(byteRate); buffer.putShort(ch * 2)
buffer.putShort(16); buffer.put(String("data").getBytes()); buffer.putInt(pNum)
fos.write(buffer.array())
fos.write(pcmData)
fos.close()
return TEKS.header_wav_berhasil_disuntikkan_secara_p
end
local dataOff = -1
for i = 12, batas - 4 do
if arr[i] == 100 and arr[i+1] == 97 and arr[i+2] == 116 and arr[i+3] == 97 then
dataOff = i
break
end
end
if dataOff == -1 then raf.close(); return TEKS.chunk_data_tidak_ditemukan end
local rb = luajava.bindClass("java.lang.Integer")
local dataLen = pNum - (dataOff + 8)
raf.seek(4); raf.writeInt(rb.reverseBytes(pNum - 8))
raf.seek(dataOff + 4); raf.writeInt(rb.reverseBytes(dataLen))
raf.close()
return TEKS.header_wav_dinamis_diperbaiki
end)
return okFix and tostring(hasil) or (TEKS.gagal_memeriksa .. tostring(hasil))
end
