_G.bukaPencariTitikMusikUmum = function(bgmPath, mulaiAwalMs, cbSimpan)
local durMus = 0
pcall(function()
local mmr = MediaMetadataRetriever()
mmr.setDataSource(bgmPath)
local d = mmr.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION)
if d then durMus = tonumber(d) or 0 end
mmr.release()
end)
local pl = MediaPlayer()
local okSiap = pcall(function()
local fis = FileInputStream(File(bgmPath))
pl.setDataSource(fis.getFD())
pl.prepare()
fis.close()
end)
if not okSiap then
pcall(function() pl.release() end)
bicaraLayanan(TEKS.gagal_membuka_musik)
return
end
if durMus <= 0 then pcall(function() durMus = pl.getDuration() or 0 end) end
if durMus <= 0 then durMus = 1000 end
local pos = mulaiAwalMs or 0
if pos > durMus then pos = 0 end
local aktif = true
local diseret = false
local dlg
local lay = buatWadah(LinearLayout.VERTICAL, 20, 20, 20, 20)
local tvPos = buatTeks("", 15, 0, 0, 0, 10)
local sb = SeekBar(service)
sb.setMax(durMus)
local btnPutar = buatTombol(TEKS.putar)
local function tampil(ms)
if ms < 0 then ms = 0 elseif ms > durMus then ms = durMus end
pos = math.floor(ms)
sb.setProgress(pos)
tvPos.setText(TEKS.posisi_kursor .. formatWaktuPresisi(pos) .. " / " .. formatWaktuPresisi(durMus))
end
local function bersih()
if not aktif then return end
aktif = false
pcall(function() if pl.isPlaying() then pl.stop() end end)
pcall(function() pl.release() end)
end
local function posisiSekarang()
local cur = pos
pcall(function() if pl.isPlaying() then cur = pl.getCurrentPosition() end end)
return cur
end
pl.setOnCompletionListener(MediaPlayer.OnCompletionListener{
onCompletion = function(mp) btnPutar.setText(TEKS.putar) end
})
local updRun
updRun = Runnable({
run = function()
if aktif then
local main = false
pcall(function() main = pl.isPlaying() end)
if main and not diseret then tampil(pl.getCurrentPosition()) end
handler.postDelayed(updRun, 100)
end
end
})
sb.setOnSeekBarChangeListener(SeekBar.OnSeekBarChangeListener{
onProgressChanged = function(sbx, progress, fromUser)
if fromUser and aktif then tampil(progress) end
end,
onStartTrackingTouch = function() diseret = true end,
onStopTrackingTouch = function()
diseret = false
if aktif then
pcall(function() pl.seekTo(pos) end)
bicaraLayanan(formatLisanPresisi(pos))
end
end
})
local function lompat(delta)
if not aktif then return end
tampil(posisiSekarang() + delta)
pcall(function() pl.seekTo(pos) end)
bicaraLayanan(formatLisanPresisi(pos))
end
local btnMundur = buatTombol(TEKS.mundur_10_detik, function() lompat(-10000) end)
local btnMaju = buatTombol(TEKS.maju_10_detik, function() lompat(10000) end)
btnPutar.setOnClickListener(function()
if not aktif then return end
local main = false
pcall(function() main = pl.isPlaying() end)
if main then
tampil(posisiSekarang())
pcall(function() pl.pause() end)
btnPutar.setText(TEKS.putar)
bicaraLayanan(TEKS.jeda)
else
pcall(function() pl.seekTo(pos); pl.start() end)
btnPutar.setText(TEKS.jeda)
bicaraLayanan(TEKS.memutar)
end
end)
local barisKontrol = buatWadah(LinearLayout.HORIZONTAL, 0, 10, 0, 10, Gravity.CENTER)
btnMundur.setLayoutParams(LinearLayout.LayoutParams(0, -2, 1))
btnPutar.setLayoutParams(LinearLayout.LayoutParams(0, -2, 1))
btnMaju.setLayoutParams(LinearLayout.LayoutParams(0, -2, 1))
barisKontrol.addView(btnMundur); barisKontrol.addView(btnPutar); barisKontrol.addView(btnMaju)
local btnTandai = buatTombol(TEKS.tandai_di_posisi_ini_simpan, function()
local final = math.floor(posisiSekarang())
bersih()
dlg.dismiss()
if cbSimpan then cbSimpan(final) end
bicaraLayanan(TEKS.suara_masuk_ditandai_pada .. formatLisanPresisi(final))
end)
btnTandai.setBackgroundColor(Color.parseColor("#4CAF50"))
btnTandai.setTextColor(Color.WHITE)
local btnBatalCari = buatTombol(TEKS.batal, function()
bersih()
dlg.dismiss()
end)
lay.addView(buatTeks(TEKS.putar_lagu_dari_awal_lalu_tandai, 13, 0, 0, 0, 10, nil, "#888888"))
lay.addView(tvPos)
lay.addView(sb)
lay.addView(barisKontrol)
lay.addView(btnTandai)
lay.addView(btnBatalCari)
tampil(pos)
pcall(function() pl.seekTo(pos) end)
dlg = buatDialogKustom(TEKS.tandai_titik_suara_masuk_di_musik, buatScroll(lay))
pcall(function()
dlg.setOnDismissListener(luajava.createProxy("android.content.DialogInterface$OnDismissListener", {
onDismiss = function() bersih() end
}))
end)
handler.post(updRun)
end
_G.nadiMuatSuaraDua = function()
return {
s2 = prefs.getInt("sd_s2", 4), vol2 = prefs.getInt("sd_vol2", 70), dly2 = prefs.getInt("sd_dly2", 12), pan2 = prefs.getInt("sd_pan2", 30),
on3 = prefs.getBoolean("sd_aktif3", false), s3 = prefs.getInt("sd_s3", -5), vol3 = prefs.getInt("sd_vol3", 50), dly3 = prefs.getInt("sd_dly3", 22), pan3 = prefs.getInt("sd_pan3", -30),
dry = prefs.getInt("sd_dry", 100), fo = prefs.getInt("sd_fo", 0), nat = prefs.getInt("sd_nat", 50)
}
end
_G.nadiSimpanSuaraDua = function(sd)
local e = prefs.edit()
e.putInt("sd_s2", math.floor(sd.s2)); e.putInt("sd_vol2", math.floor(sd.vol2)); e.putInt("sd_dly2", math.floor(sd.dly2)); e.putInt("sd_pan2", math.floor(sd.pan2))
e.putBoolean("sd_aktif3", sd.on3 and true or false)
e.putInt("sd_s3", math.floor(sd.s3)); e.putInt("sd_vol3", math.floor(sd.vol3)); e.putInt("sd_dly3", math.floor(sd.dly3)); e.putInt("sd_pan3", math.floor(sd.pan3))
e.putInt("sd_dry", math.floor(sd.dry)); e.putInt("sd_fo", math.floor(sd.fo)); e.putInt("sd_nat", math.floor(sd.nat))
e.apply()
end
_G.nadiSuaraDuaCfg = function()
local sd = _G.nadiMuatSuaraDua()
local function f(x) return (tostring(x):gsub(",", ".")) end
local stereo = (prefs.getInt("channel", 1) == 2)
local p2 = stereo and sd.pan2 / 100 or 0
local p3 = stereo and sd.pan3 / 100 or 0
return table.concat({
"1", f(sd.s2), f(sd.vol2 / 100), f(sd.dly2), f(p2),
(sd.on3 and "1" or "0"), f(sd.s3), f(sd.vol3 / 100), f(sd.dly3), f(p3),
f(sd.dry / 100), f(sd.fo), f(sd.nat / 100)
}, ",")
end
_G.cekSuaraDua = function()
local hasil = TEKS.belum_siap
pcall(function()
local dPath = service.getDir("dex", 0).getAbsolutePath()
local cL = luajava.bindClass("dalvik.system.DexClassLoader")(_G.jalurDexNadi, dPath, nil, service.getClassLoader())
local k = cL.loadClass("FastMuxer")
local m = k.getDeclaredMethod("suaraDuaSiap", luajava.newArray(luajava.bindClass("java.lang.Class"), 0))
hasil = tostring(m.invoke(nil, luajava.newArray(luajava.bindClass("java.lang.Object"), 0)))
end)
return hasil
end
