_G.nadiNamaInterval = function(n)
local t = {[0] = TEKS.sama_dengan_suara_asli, [1] = TEKS.setengah_nada, [2] = TEKS.satu_nada, [3] = TEKS.terts_kecil, [4] = TEKS.terts_besar, [5] = "kuart", [6] = "tritonus", [7] = "kuint", [8] = TEKS.sekst_kecil, [9] = TEKS.sekst_besar, [10] = TEKS.septim_kecil, [11] = TEKS.septim_besar, [12] = TEKS.satu_oktaf}
local a = math.abs(n)
local arah = (n > 0) and TEKS.di_atas or ((n < 0) and TEKS.di_bawah or "")
return arah .. (t[a] or "")
end
