local tv = buatTeks(teks(val), 14)
local sb = _G.nadiStepperBar(maxV, val, minV)
_G.nadiPasangStepper(sb, function(sx, v, fromUser)
setter(v)
tv.setText(teks(v))
simpan()
if fromUser then bicaraLayanan(fmt and fmt(v) or (v .. unit)) end
end)
w.addView(tv)
w.addView(sb.view)
induk.addView(w)
end
local function fmtInterval(v)
local sign = (v > 0) and "+" or ""
return sign .. v .. TEKS.nada_4 .. _G.nadiNamaInterval(v) .. ")"
end
local function fmtPan(v)
