_G.nadiMuatPitchLanjut = function()
local nilaiAwal = prefs.getInt("efek_pitch_semitone", 0)
if prefs.contains("pitch_lj_x2") then nilaiAwal = prefs.getInt("pitch_lj_x2", 0) / 2 end
return {
lanjut = prefs.getBoolean("pitch_lanjut", false),
val = nilaiAwal,
glOn = prefs.getBoolean("pitch_lj_glide", false),
g0 = prefs.getInt("pitch_lj_g0_x2", 0) / 2,
g1 = prefs.getInt("pitch_lj_g1_x2", 8) / 2,
gd = prefs.getInt("pitch_lj_gdur", 0),
langkah = prefs.getInt("pitch_lj_langkah", 2)
}
end
_G.nadiSimpanPitchLanjut = function(ps)
local e = prefs.edit()
e.putBoolean("pitch_lanjut", ps.lanjut and true or false)
e.putInt("pitch_lj_x2", math.floor(ps.val * 2 + 0.5))
e.putInt("efek_pitch_semitone", math.floor(ps.val + 0.5))
e.putBoolean("pitch_lj_glide", ps.glOn and true or false)
e.putInt("pitch_lj_g0_x2", math.floor(ps.g0 * 2 + 0.5))
e.putInt("pitch_lj_g1_x2", math.floor(ps.g1 * 2 + 0.5))
e.putInt("pitch_lj_gdur", math.floor(ps.gd))
e.putInt("pitch_lj_langkah", math.floor(ps.langkah))
e.apply()
end
_G.nadiPitchCfg = function(internalOnly)
local function f(x) return (tostring(x):gsub(",", ".")) end
local ps = _G.nadiMuatPitchLanjut()
if ps.lanjut and internalOnly then return nil end
if (not ps.glOn) and ps.val == 0 then return nil end
return f(ps.val) .. "\n" .. (ps.lanjut and "LANJUT" or "STD") .. "," .. (ps.glOn and "1" or "0") .. "," .. f(ps.g0) .. "," .. f(ps.g1) .. "," .. f(ps.gd)
end
