wadah.addView(buatTeks(TEKS.nada_berubah_perlahan_dari_nada_awal, 12, 0, 6, 0, 8, nil, "#888888"))
sliderHalf(wadah, TEKS.nada_awal, ps.g0, function(v) ps.g0 = v end)
sliderHalf(wadah, TEKS.nada_akhir, ps.g1, function(v) ps.g1 = v end)
local wD = buatWadah(LinearLayout.VERTICAL, 0, 8, 0, 8)
local function teksD(v) return TEKS.lama_peralihan .. ((v == 0) and TEKS.sepanjang_rekaman or (v .. " detik")) end
local tvD = buatTeks(teksD(ps.gd), 14)
local sbD = _G.nadiStepperBar(120, math.floor(ps.gd))
_G.nadiPasangStepper(sbD, function(sx, prog, fromUser)
ps.gd = prog
tvD.setText(teksD(prog))
simpan()
if fromUser then bicaraLayanan(teksD(prog)) end
end)
wD.addView(tvD)
wD.addView(sbD.view)
wadah.addView(wD)
local barisCepat = buatWadah(LinearLayout.VERTICAL, 0, 6, 0, 6)
barisCepat.addView(buatTombol(TEKS.naik_pelan_pelan_0_ke_plus, function()
ps.g0 = 0; ps.g1 = 4
simpan(); isi()
bicaraLayanan(TEKS.naik_pelan_pelan_dari_nol_ke)
end))
barisCepat.addView(buatTombol(TEKS.turun_pelan_pelan_0_ke_minus, function()
ps.g0 = 0; ps.g1 = -4
simpan(); isi()
bicaraLayanan(TEKS.turun_pelan_pelan_dari_nol_ke)
end))
wadah.addView(barisCepat)
end
end
cbLanjut.setOnCheckedChangeListener(function(v, isChecked)
ps.lanjut = isChecked
simpan()
isi()
bicaraLayanan(isChecked and TEKS.mode_nada_tingkat_lanjut_aktif or TEKS.mode_nada_biasa_aktif)
end)
isi()
if opsi.onMode then opsi.onMode(true) end
end
-- Nilai Bass & Treble / Ekualiser dari pengaturan tersimpan. Mode "bt": hanya bass dan treble yang bekerja;
-- mode "eq": hanya lima pita yang bekerja (sama dengan cara efek ini dipakai saat disimpan).
_G.nadiToneDariPrefs = function(mode)
local function g(k) return prefs.getInt(k, 50) end
if mode == "bt" then
return {bass = g("tone_bass"), treble = g("tone_treble"), b1 = 50, b2 = 50, b3 = 50, b4 = 50, b5 = 50}
end
return {bass = 50, treble = 50, b1 = g("tone_b1"), b2 = g("tone_b2"), b3 = g("tone_b3"), b4 = g("tone_b4"), b5 = g("tone_b5")}
end
_G.nadiBangunPratinjauNada = function(parent, ps, opsi)
opsi = opsi or {}
local modeSd = (opsi.mode == "sd")
local modeTone = (opsi.mode == "tone")
local modeGate = (opsi.mode == "gate")
local modeRvb = (opsi.mode == "reverb")
local modeEco = (opsi.mode == "echo")
local modeAt = (opsi.mode == "autotune")
local lastCfg = nil
local kerja = service.getExternalFilesDir(nil).getAbsolutePath() .. "/_nada_langsung"
local handler = Handler(Looper.getMainLooper())
local ctrl = {}
local tutup = false
local siap = false
local menyiapkan = false
local memutar = false
local kunciSiap = nil
local posTerakhir = 0
local durMs = 0
local ljAkhir = "mati"
local btnMain, tvStatus, tvMesin, cbUlang
local poll
local function angka(x)
return (tostring(tonumber(x) or 0):gsub(",", "."))
end
local function lisan(ms)
local d = math.floor((ms or 0) / 1000)
local m = math.floor(d / 60)
d = d % 60
if m > 0 then return m .. " menit " .. d .. " detik" end
return d .. " detik"
end
local function cfg()
local nilai = ps.val
if nilai == nil then nilai = tonumber(ps.semitone) or 0 end
return table.concat({
ps.lanjut and "1" or "0",
cbUlang.isChecked() and "1" or "0",
ps.glOn and "1" or "0",
angka(nilai), angka(ps.g0), angka(ps.g1), angka(ps.gd)
}, "|")
end
local function cfgSd()
local sd = opsi.ambilSd() or {}
local stereo = opsi.stereo and opsi.stereo() or false
local function suara(on, semi, vol, pan, dly)
return table.concat({on and "1" or "0", angka(semi), angka((vol or 0) / 100), angka(stereo and ((pan or 0) / 100) or 0), angka(dly)}, "|")
end
return table.concat({
cbUlang.isChecked() and "1" or "0",
angka((sd.dry or 100) / 100), angka(sd.fo or 0), angka((sd.nat or 50) / 100), "0.6",
suara(true, sd.s2 or 4, sd.vol2 or 70, sd.pan2 or 30, sd.dly2 or 12),
suara(sd.on3 and true or false, sd.s3 or -5, sd.vol3 or 50, sd.pan3 or -30, sd.dly3 or 22),
"0|0|0|0|0"
}, "|")
end
-- Bass & Treble / Ekualiser: "ulang|bass|treble|pita1|pita2|pita3|pita4|pita5" (persen, 50 = netral)
local function cfgTone()
local t = (opsi.ambilTone and opsi.ambilTone()) or {}
local function n(v)
v = tonumber(v)
if v == nil then v = 50 end
if v < 0 then v = 0 elseif v > 100 then v = 100 end
return angka(v)
end
return table.concat({
cbUlang.isChecked() and "1" or "0",
n(t.bass), n(t.treble), n(t.b1), n(t.b2), n(t.b3), n(t.b4), n(t.b5)
}, "|")
end
-- Pengurang Kebisingan: "ulang|sensitivitas%|attackMd|releaseMd"
local function cfgGate()
local t = (opsi.ambilGate and opsi.ambilGate()) or {}
return table.concat({
cbUlang.isChecked() and "1" or "0",
angka(t.thresh or 0), angka(t.attack or 5), angka(t.release or 150)
}, "|")
end
-- Reverb: "ulang|ruangan|peredam|asli|gema"; Echo: "ulang|jarakMd|ekor|peredam|asli|pantulan" (pecahan 0..1, kecuali md)
local function cfgFx()
local t = (opsi.ambilFx and opsi.ambilFx()) or {}
local function pc(v, d)
v = tonumber(v)
if v == nil then v = d end
if v < 0 then v = 0 elseif v > 100 then v = 100 end
return angka(v / 100)
end
local u = cbUlang.isChecked() and "1" or "0"
if modeRvb then return table.concat({u, pc(t.room, 50), pc(t.damp, 50), pc(t.dry, 70), pc(t.wet, 30)}, "|") end
return table.concat({u, angka(tonumber(t.delay) or 300), pc(t.fb, 30), pc(t.damp, 50), pc(t.dry, 100), pc(t.wet, 30)}, "|")
end
-- AutoTune: "ulang|kunci 0..11|tangga nada 0..2|kecepatan 1..100"
local function cfgAt()
local t = (opsi.ambilAt and opsi.ambilAt()) or {}
local sp = tonumber(t.speed) or 80
if sp < 1 then sp = 1 elseif sp > 100 then sp = 100 end
return table.concat({
cbUlang.isChecked() and "1" or "0",
angka(tonumber(t.key) or 0), angka(tonumber(t.scale) or 0), angka(sp)
}, "|")
end
local function kirimCfg()
if modeAt then
local c = cfgAt()
lastCfg = c
return _G.rapikanLive("pt_atur_autotune", c)
end
if modeRvb or modeEco then
local c = cfgFx()
lastCfg = c
return _G.rapikanLive("pt_atur_fx", c)
end
if modeGate then return _G.rapikanLive("pt_atur_gate", cfgGate()) end
if modeTone then return _G.rapikanLive("pt_atur_tone", cfgTone()) end
if modeSd then return _G.rapikanLive("pt_atur_sd", cfgSd()) end
return _G.rapikanLive("pt_atur", cfg())
end
local function tampilBerhenti()
memutar = false
btnMain.setText(TEKS.putar_langsung)
end
local function segarkan()
if tutup then return end
if menyiapkan then
local pct = _G.nadiBacaProgresUmum()
tvStatus.setText(TEKS.menyiapkan_suara_contoh .. (pct and (" " .. pct .. " persen") or "..."))
return
end
if not siap then return end
local r = _G.rapikanLive("pt_status")
local lj, pers, pos, jalan, dur, mesin, selesai, pesan = tostring(r):match("^([^|]*)|(%-?%d+)|(%-?%d+)|(%d+)|(%d+)|(%d+)|(%d+)|(.*)$")
if not lj then return end
posTerakhir = tonumber(pos) or 0
durMs = tonumber(dur) or durMs
if jalan == "1" then
memutar = true
btnMain.setText(TEKS.hentikan_pemutaran)
tvStatus.setText(TEKS.memutar_2 .. formatWaktu(posTerakhir) .. TEKS.dari .. formatWaktu(durMs))
elseif memutar then
tampilBerhenti()
if selesai == "1" then
tvStatus.setText(TEKS.selesai_diputar_ketuk_putar_langsung_unt)
bicaraLayanan(TEKS.selesai_diputar)
else
tvStatus.setText(TEKS.pemutaran_berhenti .. ((pesan ~= "" and (": " .. pesan)) or "."))
bicaraLayanan(TEKS.pemutaran_berhenti_2 .. pesan)
end
else
tvStatus.setText(TEKS.berhenti_di .. formatWaktu(posTerakhir) .. TEKS.dari .. formatWaktu(durMs))
end
if modeSd or (ps and ps.lanjut) then
local nama = modeSd and TEKS.suara_dua_langsung or TEKS.mode_tingkat_lanjut_nama
local cadangan = modeSd and TEKS.suara_asli_saja or TEKS.mode_biasa
tvMesin.setVisibility(View.VISIBLE)
if lj == "analisis" then
tvMesin.setText(nama .. TEKS.sedang_disiapkan .. pers .. TEKS.persen_2 .. ((jalan == "1") and (TEKS.sementara_ini_terdengar .. cadangan .. TEKS.titik) or ""))
elseif lj == "siap" then
tvMesin.setText(nama .. TEKS.siap_dipakai_titik)
elseif lj == "galat" then
tvMesin.setText(nama .. TEKS.tidak_bisa_dipakai_titik_dua .. pesan .. TEKS.terdengar_spasi .. cadangan .. TEKS.titik)
else
tvMesin.setText("")
end
if lj ~= ljAkhir then
if lj == "siap" then
bicaraLayanan(nama .. TEKS.siap_dipakai_lisan)
elseif lj == "galat" then
bicaraLayanan(nama .. TEKS.tidak_bisa_dipakai_lisan .. pesan .. TEKS.terdengar_spasi .. cadangan)
end
end
else
tvMesin.setVisibility(View.GONE)
end
ljAkhir = lj
end
poll = Runnable({run = function()
if tutup then return end
pcall(segarkan)
if not tutup then handler.postDelayed(poll, 400) end
end})
-- Reverb / Echo: banyak jalur mengubah angka (penggeser, tombol +/-, preset), jadi pengaturan dipantau tiap
-- 100 md dan dikirim begitu berubah, sehingga perubahan terdengar seketika.
local pantauRun
pantauRun = Runnable({run = function()
if tutup then return end
if siap and (modeRvb or modeEco or modeAt) then
local okc, c = pcall(modeAt and cfgAt or cfgFx)
if okc and c ~= lastCfg then pcall(kirimCfg) end
end
if not tutup then handler.postDelayed(pantauRun, 100) end
end})
local function mulaiMemutar(awal)
local r = _G.rapikanLive("pt_main", tostring(awal))
if tostring(r):sub(1, 6) ~= "SUKSES" then
tampilBerhenti()
tvStatus.setText(TEKS.gagal_memutar .. tostring(r))
bicaraLayanan(TEKS.gagal_memutar_2 .. tostring(r))
return
end
memutar = true
btnMain.setText(TEKS.hentikan_pemutaran)
bicaraLayanan(TEKS.memutar)
end
local function siapkan(sp)
menyiapkan = true
siap = false
kunciSiap = nil
btnMain.setText("Menyiapkan...")
tvStatus.setText(TEKS.menyiapkan_suara_contoh_2)
bicaraLayanan(TEKS.menyiapkan_suara_contoh)
pcall(function() _G.rapikanLive("pt_lepas") end)
local cmd, a, b, c, d
if sp.jenis == "mentah" then
cmd = "pt_siapkan_raw"
a = sp.path; b = kerja; c = tostring(sp.sr); d = tostring(sp.ch)
else
cmd = "pt_siapkan"
a = sp.path; b = kerja
c = tostring(math.floor(sp.awalMs or 0)) .. "," .. tostring(math.floor(sp.akhirMs or 0)); d = ""
end
_G.rapikanAsync(cmd, a, b, c, d, function(r)
menyiapkan = false
if tutup then return end
local dur = tostring(r):match("^SUKSES:(%d+)$")
if not dur then
tampilBerhenti()
local pesan = tostring(r):gsub("^GAGAL:%s*", "")
tvStatus.setText(TEKS.gagal_menyiapkan_suara_contoh .. pesan)
bicaraLayanan(TEKS.gagal_menyiapkan_suara_contoh_2 .. pesan)
return
end
local ro = _G.rapikanLive("pt_buka", kerja, modeSd and "sd" or (modeTone and "tone" or (modeGate and "gate" or (modeRvb and "reverb" or (modeEco and "echo" or (modeAt and "autotune" or ""))))), (modeSd and opsi.stereo and opsi.stereo()) and "1" or "0")
if tostring(ro):sub(1, 6) ~= "SUKSES" then
tampilBerhenti()
tvStatus.setText(TEKS.gagal_membuka_pemutar .. tostring(ro))
bicaraLayanan(TEKS.gagal_membuka_pemutar_2 .. tostring(ro))
return
end
siap = true
kunciSiap = sp.kunci
durMs = tonumber(dur) or 0
ljAkhir = "mati"
kirimCfg()
mulaiMemutar(0)
end)
end
local function lompat(delta)
if not siap then bicaraLayanan(TEKS.putar_dulu_suara_contohnya); return end
local baru = posTerakhir + delta
if baru < 0 then baru = 0 end
if durMs > 0 and baru > durMs - 500 then baru = math.max(0, durMs - 500) end
_G.rapikanLive("pt_cari", tostring(math.floor(baru)))
posTerakhir = baru
bicaraLayanan(TEKS.posisi_2 .. lisan(baru))
end
parent.addView(buatTeks(TEKS.dengarkan_langsung, 16, 0, 10, 0, 6, Gravity.CENTER, "#2196F3"))
parent.addView(buatTeks((modeTone or modeGate or modeRvb or modeEco or modeAt) and TEKS.putar_suara_contoh_lalu_geser_nada_tone or (modeSd and TEKS.putar_suara_contoh_lalu_ubah_suara_dua or TEKS.putar_suara_contoh_lalu_naikkan_atau), 12, 0, 0, 0, 8, nil, "#888888"))
btnMain = buatTombol(TEKS.putar_langsung, function()
if tutup then return end
if menyiapkan then bicaraLayanan(TEKS.masih_menyiapkan_suara_contoh); return end
if memutar then
_G.rapikanLive("pt_henti")
tampilBerhenti()
bicaraLayanan(TEKS.dihentikan)
return
end
local sp, pesan = opsi.sumber()
if not sp then
bicaraLayanan(pesan or TEKS.belum_ada_suara_contoh)
tvStatus.setText(pesan or TEKS.belum_ada_suara_contoh_2)
return
end
if opsi.sebelumMulai then pcall(opsi.sebelumMulai) end
if siap and kunciSiap == sp.kunci then
kirimCfg()
mulaiMemutar(-1)
else
siapkan(sp)
end
end)
parent.addView(btnMain)
tvStatus = buatTeks(TEKS.belum_diputar, 14, 0, 4, 0, 4)
parent.addView(tvStatus)
local baris = buatWadah(LinearLayout.HORIZONTAL, 0, 0, 0, 0, Gravity.CENTER)
local btnMundur = buatTombol(TEKS.mundur_10_detik, function() lompat(-10000) end)
local btnMaju = buatTombol(TEKS.maju_10_detik, function() lompat(10000) end)
btnMundur.setLayoutParams(LinearLayout.LayoutParams(0, -2, 1))
btnMaju.setLayoutParams(LinearLayout.LayoutParams(0, -2, 1))
baris.addView(btnMundur)
baris.addView(btnMaju)
parent.addView(baris)
cbUlang = buatCentang(TEKS.ulangi_dari_awal_bila_selesai, false)
cbUlang.setOnCheckedChangeListener(function(v, isChecked)
ctrl.ubah()
bicaraLayanan(isChecked and TEKS.ulangi_aktif or TEKS.ulangi_mati)
end)
parent.addView(cbUlang)
tvMesin = buatTeks("", 12, 0, 2, 0, 6, nil, "#888888")
tvMesin.setVisibility(View.GONE)
parent.addView(tvMesin)
ctrl.ubah = function()
if tutup or not siap then return end
pcall(kirimCfg)
end
ctrl.hentikan = function()
if memutar then
pcall(function() _G.rapikanLive("pt_henti") end)
tampilBerhenti()
end
end
ctrl.tutup = function()
tutup = true
pcall(function() _G.rapikanLive("pt_henti") end)
pcall(function() _G.rapikanLive("pt_lepas") end)
pcall(function() handler.removeCallbacks(poll) end)
pcall(function() handler.removeCallbacks(pantauRun) end)
pcall(function() hapusFile(kerja .. "/nada_pt.raw") end)
end
handler.postDelayed(poll, 400)
if modeRvb or modeEco or modeAt then handler.postDelayed(pantauRun, 100) end
return ctrl
end
_G.nadiOpsiLangkah = function(minV, maxV)
local range = maxV - minV
local kandidat = {1, 2, 5, 10, 25, 50, 100, 250, 500, 1000, 2500, 5000, 10000}
local hasil = {}
for _, k in ipairs(kandidat) do
if k <= range / 2 or #hasil == 0 then table.insert(hasil, k) end
end
return hasil
end
_G.nadiStepperBar = function(maxV, cur, minV, op)
op = op or {}
minV = minV or 0
local o = {min = minV, max = maxV, val = minV, cb = nil}
local function klem(v)
if v < o.min then v = o.min elseif v > o.max then v = o.max end
return v
end
o.val = klem(cur or minV)
local opsi = _G.nadiOpsiLangkah(o.min, o.max)
local range = o.max - o.min
local idx = #opsi
for i, k in ipairs(opsi) do
if k >= range / 20 then idx = i; break end
end
if op.awal then
for i, k in ipairs(opsi) do
if k == op.awal then idx = i end
end
end
local function besarLangkah(k) return op.fmt and op.fmt(k) or (tostring(k) .. " langkah") end
local function namaLangkah(k) return besarLangkah(k) end
local function bersihkanNama(n)
n = tostring(n or "")
n = n:gsub("%s*%b()", "")
n = n:gsub("%s+[Ss]aat [Ii]ni%s*$", "")
n = n:gsub("^%s+", "")
n = n:gsub("%s+$", "")
if n == "" then return nil end
if not n:find("%u%u") then n = n:lower() end
return n
end
local view = buatWadah(LinearLayout.VERTICAL, 0, 0, 0, 6)
local label = nil
local bLangkah, bKurang, bTambah
local slider = SeekBar(service)
slider.setPadding(30, 10, 30, 10)
local function sinkronSlider()
slider.setMax(o.max - o.min)
slider.setProgress(o.val - o.min)
end
sinkronSlider()
pasangSeek(slider, function(sb, prog, fromUser)
if not fromUser then return end
local baru = klem(prog + o.min)
if baru == o.val then return end
o.val = baru
if o.cb then o.cb(nil, baru, true) end
end)
local function teksLangkah()
if label then return TEKS.atur_langkah_untuk .. label .. TEKS.saat_ini .. besarLangkah(opsi[idx]) end
return TEKS.atur_besar_langkah_saat_ini .. besarLangkah(opsi[idx])
end
local function perbaruiTeks()
bLangkah.setText(teksLangkah())
bKurang.setText(label and (TEKS.kurangi .. label) or TEKS.kurangi_2)
bTambah.setText(label and (TEKS.tambah .. label) or TEKS.tambah_2)
end
local function pindah(arah)
local baru = klem(o.val + arah * opsi[idx])
if baru == o.val then
bicaraLayanan(arah < 0 and TEKS.sudah_di_batas_bawah or TEKS.sudah_di_batas_atas)
return
end
o.val = baru
sinkronSlider()
if o.cb then o.cb(nil, baru, true) end
end
bLangkah = buatTombol("", function()
idx = idx % #opsi + 1
perbaruiTeks()
bicaraLayanan(namaLangkah(opsi[idx]))
end)
bKurang = buatTombol("", function() pindah(-1) end)
bTambah = buatTombol("", function() pindah(1) end)
local slotNilai = buatWadah(LinearLayout.VERTICAL, 0, 4, 0, 4, Gravity.CENTER)
perbaruiTeks()
view.addView(bLangkah, LinearLayout.LayoutParams(-1, -2))
view.addView(bKurang, LinearLayout.LayoutParams(-1, -2))
view.addView(slotNilai, LinearLayout.LayoutParams(-1, -2))
view.addView(bTambah, LinearLayout.LayoutParams(-1, -2))
view.addView(slider, LinearLayout.LayoutParams(-1, -2))
Handler(Looper.getMainLooper()).post(Runnable{run = function()
pcall(function()
local par = view.getParent()
if not par then return end
local i = par.indexOfChild(view)
if i < 1 then return end
local prev = par.getChildAt(i - 1)
local kls = tostring(prev.getClass().getName())
if kls:sub(-8) ~= "TextView" then return end
local nama = tostring(prev.getText()):match("^%s*(.-)%s*:")
nama = bersihkanNama(nama)
if nama and #nama <= 60 then label = nama end
par.removeView(prev)
slotNilai.addView(prev)
perbaruiTeks()
end)
end})
o.view = view
o.setMax = function(m) o.max = m; o.val = klem(o.val); sinkronSlider() end
o.setProgress = function(v)
o.val = klem(v)
sinkronSlider()
if o.cb then o.cb(nil, o.val, false) end
end
o.getProgress = function() return o.val end
return o
end
_G.nadiPasangStepper = function(o, fn)
o.cb = fn
end
_G.nadiNamaSensor = {TEKS.beep_nada_murni, TEKS.sunyi_suara_ditiadakan, TEKS.derau_desis_seperti_radio, TEKS.dengung_nada_rendah}
_G.nadiFmtDetik = function(t10)
return (string.format("%.1f", t10 / 10):gsub("%.", ","))
end
_G.nadiBangunUiSensor = function(parent, sn, simpan, opsi)
opsi = opsi or {}
simpan = simpan or function() end
local def = {kind = 1, freq = 1000, vol = 60, mix = 0, fade = 10}
for k, v in pairs(def) do if sn[k] == nil then sn[k] = v end end
if opsi.track and sn.rentang == nil then sn.rentang = {} end
parent.addView(buatTeks(TEKS.sensor_suara, 16, 0, 0, 0, 8, Gravity.CENTER))
parent.addView(buatTeks(TEKS.menutupi_bagian_suara_tertentu_dengan_bu .. (opsi.track and TEKS.tentukan_rentang_waktu_yang_ingin_disens or TEKS.sensor_berlaku_pada_seluruh_bagian_waktu), 13, 0, 0, 0, 10, nil, "#888888"))
local wadah = buatWadah(LinearLayout.VERTICAL, 0, 0, 0, 0)
parent.addView(wadah)
local isi
local function atur(label, minV, maxV, nilai, setter, fmt, op)
local w = buatWadah(LinearLayout.VERTICAL, 0, 8, 0, 8)
local function teks(v) return label .. ": " .. (fmt and fmt(v) or tostring(v)) end
local tv = buatTeks(teks(nilai), 14)
local bar = _G.nadiStepperBar(maxV, nilai, minV, op)
_G.nadiPasangStepper(bar, function(sx, v, fromUser)
setter(v)
tv.setText(teks(v))
simpan()
if fromUser then bicaraLayanan(fmt and fmt(v) or tostring(v)) end
end)
w.addView(tv)
w.addView(bar.view)
wadah.addView(w)
end
isi = function()
wadah.removeAllViews()
wadah.addView(buatTombol(TEKS.jenis_sensor .. _G.nadiNamaSensor[sn.kind] .. TEKS.ketuk_untuk_mengganti, function()
buatDialogPilihan(TEKS.pilih_jenis_sensor, _G.nadiNamaSensor, sn.kind - 1, function(d, w)
sn.kind = w + 1
if sn.kind == 4 and sn.freq > 400 then sn.freq = 150 end
if sn.kind == 1 and sn.freq < 400 then sn.freq = 1000 end
simpan()
d.dismiss()
isi()
bicaraLayanan(_G.nadiNamaSensor[sn.kind])
end)
end))
if sn.kind == 1 or sn.kind == 4 then
atur(TEKS.frekuensi_bunyi, 100, 4000, sn.freq, function(v) sn.freq = v end, function(v) return v .. " Hz" end)
end
if sn.kind ~= 2 then
atur(TEKS.kerasnya_bunyi_sensor, 0, 100, sn.vol, function(v) sn.vol = v end, function(v) return v .. " persen" end)
end
atur(TEKS.suara_asli_yang_tersisa_0_berarti, 0, 100, sn.mix, function(v) sn.mix = v end, function(v) return v .. " persen" end)
atur(TEKS.pelunakan_tepi_agar_tidak_berbunyi_klik, 0, 200, sn.fade, function(v) sn.fade = v end, function(v) return v .. " milidetik" end)
if opsi.track then
wadah.addView(buatTeks(TEKS.rentang_waktu_yang_disensor, 15, 0, 14, 0, 4, nil, "#E91E63"))
if #sn.rentang == 0 then
wadah.addView(buatTeks(TEKS.belum_ada_rentang_tambahkan_rentang_wakt, 12, 0, 0, 0, 8, nil, "#888888"))
end
for i, rg in ipairs(sn.rentang) do
wadah.addView(buatTeks(i .. TEKS.dari_detik .. _G.nadiFmtDetik(rg.m) .. TEKS.sampai_detik .. _G.nadiFmtDetik(rg.s), 13, 0, 0, 0, 4))
end
wadah.addView(buatTombol(TEKS.tambah_rentang_sensor, function()
local mulai, selesai = 0, 10
local lay = buatWadah(LinearLayout.VERTICAL, 20, 20, 20, 20)
local dlg
local function stp(label, nilai, setter)
local w = buatWadah(LinearLayout.VERTICAL, 0, 8, 0, 8)
local function teks(v) return label .. TEKS.detik_2 .. _G.nadiFmtDetik(v) end
local tv = buatTeks(teks(nilai), 14)
local bar = _G.nadiStepperBar(36000, nilai, 0, {awal = 10, fmt = function(k) return _G.nadiFmtDetik(k) .. " detik" end})
_G.nadiPasangStepper(bar, function(sx, v, fromUser)
setter(v)
tv.setText(teks(v))
if fromUser then bicaraLayanan(teks(v)) end
end)
w.addView(tv)
w.addView(bar.view)
lay.addView(w)
end
lay.addView(buatTeks(TEKS.atur_rentang_waktu_yang_akan_disensor, 13, 0, 0, 0, 10, nil, "#888888"))
stp(TEKS.mulai, mulai, function(v) mulai = v end)
stp(TEKS.selesai, selesai, function(v) selesai = v end)
lay.addView(buatTombol(TEKS.simpan_rentang, function()
if selesai <= mulai then
bicaraLayanan(TEKS.waktu_selesai_harus_lebih_besar_dari)
return
end
table.insert(sn.rentang, {m = mulai, s = selesai})
simpan()
dlg.dismiss()
isi()
bicaraLayanan(TEKS.rentang_ditambahkan)
end))
lay.addView(buatTombol(TEKS.batal, function() dlg.dismiss() end))
dlg = buatDialogKustom(TEKS.tambah_rentang_sensor, buatScroll(lay))
end))
wadah.addView(buatTombol(TEKS.hapus_rentang_sensor, function()
if #sn.rentang == 0 then bicaraLayanan(TEKS.belum_ada_rentang); return end
local nama = {}
for i, rg in ipairs(sn.rentang) do table.insert(nama, i .. TEKS.detik_3 .. _G.nadiFmtDetik(rg.m) .. TEKS.sampai .. _G.nadiFmtDetik(rg.s)) end
buatDialogPilihan(TEKS.hapus_rentang, nama, -1, function(d, w)
table.remove(sn.rentang, w + 1)
simpan()
d.dismiss()
isi()
bicaraLayanan(TEKS.rentang_dihapus)
end)
end))
end
end
isi()
end
local renderUIStatusCerita
renderUIStatusCerita = function(stateLama)
local prevDir = service.getExternalFilesDir(nil).getAbsolutePath()
local defaultRecRaw = prevDir .. "/_status_manusia_mic.raw"
local defaultRecWav = prevDir .. "/_status_manusia_out.wav"
local defaultTtsWav = prevDir .. "/_status_tts_out.wav"
local pvVidPath = prevDir .. "/_pv_status_cerita.mp4"
local function hentikanPratinjauStatus()
if _G.pemutarPratinjauStatus then
pcall(function() _G.pemutarPratinjauStatus.stop() end)
pcall(function() _G.pemutarPratinjauStatus.release() end)
_G.pemutarPratinjauStatus = nil
end
hapusFile(pvVidPath)
end
hentikanPratinjauStatus()
local function jepitNilai(v, lo, hi)
v = tonumber(v) or lo
if v < lo then return lo elseif v > hi then return hi end
return math.floor(v)
end
local function nilaiDalamDaftar(tabel, v, def)
for _, x in ipairs(tabel) do
if x == v then return v end
end
return def
end
local function pathMasihAda(p)
if p and p ~= "" and File(p).exists() then return p end
return ""
end
local st = stateLama or {
modePembicara = jepitNilai(prefs.getInt("st_mode", 2), 1, 4),
teksGemini = _G.nadiGemini.statusTeks(),
cMic = nilaiDalamDaftar(micNilai, prefs.getInt("st_mic", prefs.getInt("mic", 6)), 6),
cSample = nilaiDalamDaftar(sampleRatesNilai, prefs.getInt("st_sample", 44100), 44100),
cBitrate = nilaiDalamDaftar(bitratesNilai, prefs.getInt("st_bitrate", 128000), 128000),
cChannel = nilaiDalamDaftar(channelsNilai, prefs.getInt("st_channel", 2), 2),
idxUkuran = jepitNilai(prefs.getInt("st_ukuran", 1), 0, 3),
idxRasio = jepitNilai(prefs.getInt("st_rasio", 0), 0, 3),
idxLatar = jepitNilai(prefs.getInt("st_latar", 1), 0, 2),
imgPath = pathMasihAda(prefs.getString("st_img", "")),
idxDurasi = jepitNilai(prefs.getInt("st_durasi", 0), 0, 4),
instPath = "",
offsetSec = 0,
fadeInAktif = prefs.getBoolean("st_fadein_on", false),
fadeInSec = jepitNilai(prefs.getInt("st_fadein", 2), 1, 6),
fadeOutAktif = prefs.getBoolean("st_fadeout_on", false),
fadeOutSec = jepitNilai(prefs.getInt("st_fadeout", 3), 1, 8),
creator = prefs.getString("status_creator_ Terakhir", ""),
devWm = prefs.getBoolean("st_devwm", true),
teksCerita = "",
sudahRekamManusia = false,
narImporPath = pathMasihAda(prefs.getString("st_nar_impor", "")),
radioAktif = prefs.getBoolean("st_radio", false),
radioMs = 0,
radioHold = jepitNilai(prefs.getInt("st_radio_hold", 5), 0, 30),
radioFade = jepitNilai(prefs.getInt("st_radio_fade", 3), 1, 30),
volNarator = jepitNilai(prefs.getInt("st_vol_nar", 100), 0, 200),
volInstrumen = jepitNilai(prefs.getInt("st_vol_inst", 30), 0, 200),
rvbAktif = prefs.getBoolean("st_rvb_on", false),
rvbRoom = jepitNilai(prefs.getInt("st_rvb_room", prefs.getInt("rvb_room", 50)), 0, 100),
rvbDamp = jepitNilai(prefs.getInt("st_rvb_damp", prefs.getInt("rvb_damp", 50)), 0, 100),
rvbDry = jepitNilai(prefs.getInt("st_rvb_dry", prefs.getInt("rvb_dry", 70)), 0, 100),
rvbWet = jepitNilai(prefs.getInt("st_rvb_wet", prefs.getInt("rvb_wet", 30)), 0, 100),
rvbStereo = jepitNilai(prefs.getInt("st_rvb_stereo", prefs.getInt("rvb_stereo", 50)), 0, 100),
btAktif = prefs.getBoolean("st_bt_on", false),
btBass = jepitNilai(prefs.getInt("st_bt_bass", prefs.getInt("tone_bass", 50)), 0, 100),
btTreble = jepitNilai(prefs.getInt("st_bt_treble", prefs.getInt("tone_treble", 50)), 0, 100)
}
local function simpanPrefStatus()
pcall(function()
local e = prefs.edit()
e.putInt("st_mode", math.floor(st.modePembicara))
e.putInt("st_mic", math.floor(st.cMic))
e.putInt("st_sample", math.floor(st.cSample))
e.putInt("st_bitrate", math.floor(st.cBitrate))
e.putInt("st_channel", math.floor(st.cChannel))
e.putInt("st_ukuran", math.floor(st.idxUkuran))
e.putInt("st_rasio", math.floor(st.idxRasio))
e.putInt("st_latar", math.floor(st.idxLatar))
e.putString("st_img", st.imgPath or "")
e.putString("st_nar_impor", st.narImporPath or "")
e.putBoolean("st_radio", st.radioAktif and true or false)
e.putInt("st_radio_hold", math.floor(st.radioHold or 5))
e.putInt("st_radio_fade", math.floor(st.radioFade or 3))
e.putInt("st_durasi", math.floor(st.idxDurasi))
e.putString("st_inst", "")
e.putBoolean("st_fadein_on", st.fadeInAktif and true or false)
e.putInt("st_fadein", math.floor(st.fadeInSec))
e.putBoolean("st_fadeout_on", st.fadeOutAktif and true or false)
e.putInt("st_fadeout", math.floor(st.fadeOutSec))
e.putBoolean("st_devwm", st.devWm and true or false)
e.putInt("st_vol_nar", math.floor(st.volNarator))
e.putInt("st_vol_inst", math.floor(st.volInstrumen))
e.putBoolean("st_rvb_on", st.rvbAktif and true or false)
e.putInt("st_rvb_room", math.floor(st.rvbRoom))
e.putInt("st_rvb_damp", math.floor(st.rvbDamp))
e.putInt("st_rvb_dry", math.floor(st.rvbDry))
e.putInt("st_rvb_wet", math.floor(st.rvbWet))
e.putInt("st_rvb_stereo", math.floor(st.rvbStereo or 50))
e.putBoolean("st_bt_on", st.btAktif and true or false)
e.putInt("st_bt_bass", math.floor(st.btBass))
e.putInt("st_bt_treble", math.floor(st.btTreble))
e.apply()
end)
end
_G.nadiNamaModeStatus = function(m)
if m == 4 then return "Pembicara Gemini TTS (suara AI Gemini)" end
if m == 1 then return TEKS.pembicara_manusia_rekam_langsung
elseif m == 3 then return TEKS.pembicara_audio_impor_pilih_file end
return TEKS.pembicara_tts_suara_otomatis
end
_G.nadiLabelVolNarStatus = function(m)
if m == 4 then return "Volume Suara Gemini: " end
if m == 1 then return TEKS.volume_suara_manusia
elseif m == 3 then return TEKS.volume_audio_narator end
return TEKS.volume_mesin_tts
end
