if not st.instPath or st.instPath == "" then
bicaraLayanan(TEKS.pilih_instrumen_dulu_untuk_mode_radio)
return
end
local durMus = 0
pcall(function()
local mmr = MediaMetadataRetriever()
mmr.setDataSource(st.instPath)
local d = mmr.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION)
if d then durMus = tonumber(d) or 0 end
mmr.release()
end)
local pl = MediaPlayer()
local okSiap = pcall(function()
local fis = FileInputStream(File(st.instPath))
pl.setDataSource(fis.getFD())
pl.prepare()
fis.close()
end)
if not okSiap then
pcall(function() pl.release() end)
bicaraLayanan(TEKS.gagal_membuka_musik)
return
end
if durMus <= 0 then pcall(function() durMus = pl.getDuration() or 0 end) end
if durMus <= 0 then durMus = 1000 end
local pos = st.radioMs or 0
if pos > durMus then pos = 0 end
local aktif = true
local diseret = false
local dlgR
local layR = buatWadah(LinearLayout.VERTICAL, 20, 20, 20, 20)
local tvPos = buatTeks("", 15, 0, 0, 0, 10)
local sbR = SeekBar(service)
sbR.setMax(durMus)
local btnPutar = buatTombol(TEKS.putar)
local function tampil(ms)
if ms < 0 then ms = 0 elseif ms > durMus then ms = durMus end
pos = math.floor(ms)
sbR.setProgress(pos)
tvPos.setText(TEKS.posisi_kursor .. formatWaktuPresisi(pos) .. " / " .. formatWaktuPresisi(durMus))
end
local function bersih()
if not aktif then return end
aktif = false
pcall(function() if pl.isPlaying() then pl.stop() end end)
pcall(function() pl.release() end)
end
local function posisiSekarang()
local cur = pos
pcall(function() if pl.isPlaying() then cur = pl.getCurrentPosition() end end)
return cur
end
pl.setOnCompletionListener(MediaPlayer.OnCompletionListener{
onCompletion = function(mp) btnPutar.setText(TEKS.putar) end
})
local updRun
updRun = Runnable({
run = function()
if aktif then
local main = false
pcall(function() main = pl.isPlaying() end)
if main and not diseret then tampil(pl.getCurrentPosition()) end
handler.postDelayed(updRun, 100)
end
end
})
sbR.setOnSeekBarChangeListener(SeekBar.OnSeekBarChangeListener{
onProgressChanged = function(sbx, progress, fromUser)
if fromUser and aktif then tampil(progress) end
end,
onStartTrackingTouch = function() diseret = true end,
onStopTrackingTouch = function()
diseret = false
if aktif then
pcall(function() pl.seekTo(pos) end)
bicaraLayanan(formatLisanPresisi(pos))
end
end
})
local function lompat(delta)
if not aktif then return end
tampil(posisiSekarang() + delta)
pcall(function() pl.seekTo(pos) end)
bicaraLayanan(formatLisanPresisi(pos))
end
local btnMundur = buatTombol(TEKS.mundur_10_detik, function() lompat(-10000) end)
local btnMaju = buatTombol(TEKS.maju_10_detik, function() lompat(10000) end)
btnPutar.setOnClickListener(function()
if not aktif then return end
local main = false
pcall(function() main = pl.isPlaying() end)
if main then
tampil(posisiSekarang())
pcall(function() pl.pause() end)
btnPutar.setText(TEKS.putar)
bicaraLayanan(TEKS.jeda)
else
pcall(function() pl.seekTo(pos); pl.start() end)
btnPutar.setText(TEKS.jeda)
bicaraLayanan(TEKS.memutar)
end
end)
local barisKontrol = buatWadah(LinearLayout.HORIZONTAL, 0, 10, 0, 10, Gravity.CENTER)
