local function susunKonfigEksekusi(outPathTarget, isPratinjau)
local pendek = isPratinjau and {480, 480, 480, 368} or {1088, 720, 480, 368}
local panjang = isPratinjau and {848, 848, 848, 640} or {1920, 1280, 848, 640}
local p = pendek[st.idxUkuran + 1] or 480
local l = panjang[st.idxUkuran + 1] or 848
local wVid, hVid = p, l
if st.idxRasio == 2 then wVid, hVid = l, p
elseif st.idxRasio == 3 then wVid, hVid = p, p end
local durTarget = durasiNilaiDetik[st.idxDurasi + 1] or 0
if isPratinjau then durTarget = 10 end
local rCfg = st.rvbAktif and ("1," .. tostring(st.rvbRoom/100):gsub(",", ".") .. "," .. tostring(st.rvbDamp/100):gsub(",", ".") .. "," .. tostring(st.rvbDry/100):gsub(",", ".") .. "," .. tostring(st.rvbWet/100):gsub(",", ".") .. "," .. tostring(((tonumber(st.cChannel) == 2) and (st.rvbStereo or 50) or 0)/100):gsub(",", ".")) or "0,0.5,0.5,0.7,0.3"
local tCfg = st.btAktif and ("1," .. tostring(st.btBass) .. "," .. tostring(st.btTreble) .. ",50,50,50,50,50") or "0,50,50,50,50,50,50,50"
local mLatar = (st.idxLatar == 2) and 1 or ((st.idxLatar == 1) and 2 or 0)
return {
narPath = (st.modePembicara == 3) and (st.narImporPath or "") or ((st.modePembicara == 1) and defaultRecWav or defaultTtsWav),
narImpor = (st.modePembicara == 3),
radioMode = (st.radioAktif and st.instPath and st.instPath ~= "") and 1 or 0,
radioMusMs = st.radioMs or 0,
radioHold = st.radioHold or 5,
radioFade = st.radioFade or 3,
instPath = st.instPath,
outPath = outPathTarget,
cSample = tonumber(st.cSample) or 44100,
cChannel = tonumber(st.cChannel) or 2,
cBitrate = tonumber(st.cBitrate) or 128000,
volNarator = st.volNarator,
volInstrumen = st.volInstrumen,
offsetSec = st.offsetSec,
durTargetSec = durTarget,
fadeInSec = st.fadeInAktif and st.fadeInSec or 0,
fadeOutSec = st.fadeOutAktif and st.fadeOutSec or 0,
rvbCfg = rCfg,
toneCfg = tCfg,
imgPath = st.imgPath,
teksCerita = (st.modePembicara == 4) and _G.nadiGemini.teksTampil(st.teksGemini) or st.teksCerita,
creator = st.creator,
devWm = st.devWm,
modeLatar = mLatar,
reqW = wVid,
reqH = hVid
}
end
local function siapkanSuaraNaratorLalu(lanjutCallback)
if st.modePembicara == 3 then
if not st.narImporPath or st.narImporPath == "" or not File(st.narImporPath).exists() then
bicaraLayanan(TEKS.silakan_pilih_audio_narator_dulu)
return
end
lanjutCallback()
return
end
if st.modePembicara == 1 then
if not st.sudahRekamManusia or not File(defaultRecWav).exists() then
bicaraLayanan(TEKS.silakan_rekam_suara_terlebih_dahulu_di)
return
end
lanjutCallback()
elseif st.modePembicara == 4 then
if not st.teksGemini or st.teksGemini:gsub("%s", "") == "" then
bicaraLayanan("Isi teks Gemini dulu")
return
end
_G.nadiGemini.statusBuat(st.teksGemini, defaultTtsWav, function(okGm)
if okGm then lanjutCallback() end
end)
else
if not st.teksCerita or st.teksCerita == "" then
bicaraLayanan(TEKS.silakan_masukkan_kata_kata_terlebih_dahu)
return
end
local pdTts = buatDialogTunggu(TEKS.menyiapkan_suara_tts)
sintesisTeksKeWav(st.teksCerita, defaultTtsWav, function(berhasil, alasan)
pdTts.dismiss()
if not berhasil then
local a = tostring(alasan or "")
a = a:gsub("^ERROR:%s*", ""):gsub("^GAGAL:%s*", "")
if a == "" then a = TEKS.periksa_pengaturan_mesin_tts_anda end
bicaraLayanan(TEKS.gagal_membuat_suara_tts .. a)
return
end
lanjutCallback()
end)
end
end
