local renderUIMultiTrackStudio, tampilkanDialogTambahTrack, renderPickerMultiTrack, renderUIBilikRekamanKaraoke, renderUIEditTrackKaraoke
local proyekMultiTrack = {}
-- ===================== URUNGKAN / ULANGI + PROJECT .np (Studio Multi-Track) =====================
-- Riwayat menyimpan salinan keadaan meja kerja (bukan salinan audio). File hasil olahan tidak pernah
-- ditimpa; file yang tidak dipakai keadaan mana pun dibersihkan oleh mtBersihkanSampah.
_G.mtRw = {undo = {}, redo = {}, maks = 100, kotor = false, sesi = nil, namaProyek = nil, pathProyek = nil, sudahTanya = false, regMuat = false}
_G.mtBuatan = {}
_G.mtDirKerja = function()
local d = service.getExternalFilesDir(nil).getAbsolutePath() .. "/_proyek_daw"
File(d).mkdirs()
return d
end
_G.mtDirProyek = function()
local customDir = prefs.getBoolean("custom_dir_aktif", false) and prefs.getString("custom_dir_path", "storage/emulated/0/Audio Nadi") or "storage/emulated/0/Audio Nadi"
local d = customDir .. "/Proyek Studio"
File(d).mkdirs()
return d
end
_G.mtTulisTeks = function(path, teks)
local tmp = path .. ".tmp"
local fos = luajava.newInstance("java.io.FileOutputStream", tmp)
local bytes = luajava.bindClass("java.lang.String")(teks).getBytes("UTF-8")
fos.write(bytes)
fos.flush()
fos.close()
local f = File(path)
if f.exists() then f.delete() end
return File(tmp).renameTo(f)
end
_G.mtBacaTeks = function(path)
local fis = luajava.newInstance("java.io.FileInputStream", path)
local baos = luajava.newInstance("java.io.ByteArrayOutputStream")
local buf = luajava.newArray(luajava.bindClass("java.lang.Byte").TYPE, 65536)
local n = fis.read(buf)
while n ~= -1 do
baos.write(buf, 0, n)
n = fis.read(buf)
end
fis.close()
return baos.toString("UTF-8")
end
_G.mtSalinDalam = function(t)
if type(t) ~= "table" then return t end
local r = {}
for k, v in pairs(t) do r[k] = _G.mtSalinDalam(v) end
return r
end
_G.mtSalinState = function() return _G.mtSalinDalam(proyekMultiTrack) end
_G.mtSerial = function(v)
if type(v) == "table" then
local keys = {}
for k in pairs(v) do keys[#keys + 1] = k end
table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
local out = {"{"}
for _, k in ipairs(keys) do out[#out + 1] = tostring(k) .. "=" .. _G.mtSerial(v[k]) .. ";" end
out[#out + 1] = "}"
return table.concat(out)
end
return tostring(v)
end
-- ---- registri file olahan Nadi (hanya file ini yang boleh dibersihkan)
_G.mtPastikanRegistri = function()
local rw = _G.mtRw
if rw.regMuat then return end
rw.regMuat = true
pcall(function()
local f = _G.mtDirKerja() .. "/registri.json"
if File(f).exists() then
local daftar = require("cjson").decode(_G.mtBacaTeks(f))
for _, pth in ipairs(daftar) do _G.mtBuatan[pth] = true end
end
end)
end
_G.mtSimpanRegistri = function()
pcall(function()
local daftar = {}
for pth in pairs(_G.mtBuatan) do daftar[#daftar + 1] = pth end
_G.mtTulisTeks(_G.mtDirKerja() .. "/registri.json", require("cjson").encode(daftar))
end)
end
_G.mtDaftarkan = function(pth)
if not pth or pth == "" then return end
_G.mtPastikanRegistri()
_G.mtBuatan[pth] = true
_G.mtSimpanRegistri()
end
_G.mtPathDipakai = function(undoX, redoX)
local rw = _G.mtRw
local dipakai = {}
local function tandai(state)
for _, t in ipairs(state or {}) do
if t.path then dipakai[t.path] = true end
if t.pathSebelumRapi then dipakai[t.pathSebelumRapi] = true end
end
end
tandai(proyekMultiTrack)
for _, st in ipairs(undoX or rw.undo) do tandai(st.state) end
for _, st in ipairs(redoX or rw.redo) do tandai(st.state) end
return dipakai
end
_G.mtDaftarSisa = function(undoX, redoX, sapuFolder)
_G.mtPastikanRegistri()
local dipakai = _G.mtPathDipakai(undoX, redoX)
local sisa = {}
for pth in pairs(_G.mtBuatan) do
if not dipakai[pth] then sisa[pth] = true end
end
if sapuFolder then
pcall(function()
local dirRapi = service.getExternalFilesDir(nil).getAbsolutePath() .. "/_track_rapi"
local arr = File(dirRapi).listFiles()
if arr then
for i = 0, arr.length - 1 do
local pth = arr[i].getAbsolutePath()
if not dipakai[pth] then sisa[pth] = true end
end
end
end)
end
return sisa
end
_G.mtHitungBebas = function(undoX, redoX)
local total = 0
for pth in pairs(_G.mtDaftarSisa(undoX, redoX, false)) do
local f = File(pth)
if f.exists() then total = total + f.length() end
end
return total
end
_G.mtFormatMB = function(bytes)
return string.format("%.1f MB", (bytes or 0) / 1048576)
end
_G.mtBersihkanSampah = function(sapuFolder)
local bebas = 0
for pth in pairs(_G.mtDaftarSisa(nil, nil, sapuFolder)) do
local f = File(pth)
if f.exists() then
bebas = bebas + f.length()
pcall(function() f.delete() end)
end
_G.mtBuatan[pth] = nil
end
_G.mtSimpanRegistri()
return bebas
end
-- ---- riwayat
_G.mtPangkas = function()
local rw = _G.mtRw
while #rw.undo > rw.maks do table.remove(rw.undo, 1) end
end
_G.mtSimpanOtomatis = function()
pcall(function()
local rw = _G.mtRw
local data = {proyek = proyekMultiTrack, undo = rw.undo, redo = rw.redo, nama = rw.namaProyek, pathProyek = rw.pathProyek}
_G.mtTulisTeks(_G.mtDirKerja() .. "/autosave.json", require("cjson").encode(data))
end)
end
_G.mtMulaiSesi = function(label)
local rw = _G.mtRw
if rw.sesi then return end
rw.sesi = {ser = _G.mtSerial(proyekMultiTrack), state = _G.mtSalinState(), label = label}
end
_G.mtRebase = function()
local rw = _G.mtRw
local lama = rw.sesi
rw.sesi = {ser = _G.mtSerial(proyekMultiTrack), state = _G.mtSalinState(), label = lama and lama.label or nil}
end
_G.mtAkhiriSesi = function()
local rw = _G.mtRw
local sesi = rw.sesi
rw.sesi = nil
if sesi and _G.mtSerial(proyekMultiTrack) ~= sesi.ser then
table.insert(rw.undo, {label = sesi.label or "", state = sesi.state})
rw.redo = {}
_G.mtPangkas()
rw.kotor = true
_G.mtSimpanOtomatis()
end
end
_G.mtCatat = function(label)
local rw = _G.mtRw
local sesi = rw.sesi
rw.sesi = nil
if sesi and _G.mtSerial(proyekMultiTrack) ~= sesi.ser then
table.insert(rw.undo, {label = sesi.label or "", state = sesi.state})
end
table.insert(rw.undo, {label = label or "", state = _G.mtSalinState()})
rw.redo = {}
_G.mtPangkas()
rw.kotor = true
_G.mtSimpanOtomatis()
end
_G.mtBatalCatatTerakhir = function()
local rw = _G.mtRw
if #rw.undo > 0 then table.remove(rw.undo) end
end
_G.mtUndo = function()
local rw = _G.mtRw
_G.mtAkhiriSesi()
if #rw.undo == 0 then return nil end
local langkah = table.remove(rw.undo)
table.insert(rw.redo, {label = langkah.label, state = _G.mtSalinState()})
proyekMultiTrack = langkah.state
rw.kotor = true
_G.mtSimpanOtomatis()
return langkah.label
end
_G.mtRedo = function()
local rw = _G.mtRw
_G.mtAkhiriSesi()
if #rw.redo == 0 then return nil end
local langkah = table.remove(rw.redo)
table.insert(rw.undo, {label = langkah.label, state = _G.mtSalinState()})
proyekMultiTrack = langkah.state
rw.kotor = true
_G.mtSimpanOtomatis()
return langkah.label
end
