-- ---- simpan / buka project .np (zip: project.json + media/)
_G.mtSusunDataProyek = function()
local cjson = require "cjson"
local rw = _G.mtRw
local dipakai = _G.mtPathDipakai()
local urut = {}
for pth in pairs(dipakai) do urut[#urut + 1] = pth end
table.sort(urut)
local peta, media = {}, {}
local i = 0
for _, pth in ipairs(urut) do
if File(pth).exists() then
i = i + 1
local dasar = (tostring(pth:match("^.+/(.+)$") or pth):gsub("[^%w%._%-]", "_"))
local entri = "m" .. i .. "_" .. dasar
peta[pth] = "media/" .. entri
media[#media + 1] = {entri = entri, path = pth}
end
end
local function petakan(state)
local salin = _G.mtSalinDalam(state)
for _, t in ipairs(salin) do
if t.path and peta[t.path] then t.path = peta[t.path] end
if t.pathSebelumRapi and peta[t.pathSebelumRapi] then t.pathSebelumRapi = peta[t.pathSebelumRapi] end
end
return salin
end
local data = {format = "NadiProyekDAW", versi = 1, nama = rw.namaProyek, proyek = petakan(proyekMultiTrack), undo = {}, redo = {}}
for _, st in ipairs(rw.undo) do data.undo[#data.undo + 1] = {label = st.label, state = petakan(st.state)} end
for _, st in ipairs(rw.redo) do data.redo[#data.redo + 1] = {label = st.label, state = petakan(st.state)} end
return cjson.encode(data), cjson.encode(media)
end
_G.mtSimpanKe = function(pathNp, nama, selesai)
local cjson = require "cjson"
local okS, jsonData, jsonMedia = pcall(_G.mtSusunDataProyek)
if not okS then
bicaraLayanan(TEKS.gagal_menyimpan_project .. tostring(jsonData))
return
end
