task(function(jsonStr, jMedia, outPath)
require "import"
import "java.io.File"
import "java.io.FileInputStream"
import "java.io.FileOutputStream"
local cj = require "cjson"
local ok, err = pcall(function()
local media = cj.decode(jMedia)
local tmp = outPath .. ".tmp"
local fos = FileOutputStream(tmp)
local zos = luajava.newInstance("java.util.zip.ZipOutputStream", fos)
zos.setLevel(1)
zos.putNextEntry(luajava.newInstance("java.util.zip.ZipEntry", "project.json"))
zos.write(luajava.bindClass("java.lang.String")(jsonStr).getBytes("UTF-8"))
zos.closeEntry()
local buf = luajava.newArray(luajava.bindClass("java.lang.Byte").TYPE, 65536)
for _, m in ipairs(media) do
local f = File(m.path)
if f.exists() then
zos.putNextEntry(luajava.newInstance("java.util.zip.ZipEntry", "media/" .. m.entri))
local fis = FileInputStream(f)
local n = fis.read(buf)
while n ~= -1 do
zos.write(buf, 0, n)
n = fis.read(buf)
end
fis.close()
zos.closeEntry()
end
end
zos.close()
local fOut = File(outPath)
if fOut.exists() then fOut.delete() end
File(tmp).renameTo(fOut)
end)
if ok then return "OK" end
return "ERR:" .. tostring(err)
end, jsonData, jsonMedia, pathNp, function(hasil)
