_G.mtTerapkanProyek = function(data, destDir, pathNp)
local rw = _G.mtRw
local function balik(state)
for _, t in ipairs(state or {}) do
if t.path and t.path:sub(1, 6) == "media/" then
t.path = destDir .. "/" .. (t.path:sub(7):gsub("[/\\]", "_"))
_G.mtBuatan[t.path] = true
end
if t.pathSebelumRapi and t.pathSebelumRapi:sub(1, 6) == "media/" then
t.pathSebelumRapi = destDir .. "/" .. (t.pathSebelumRapi:sub(7):gsub("[/\\]", "_"))
_G.mtBuatan[t.pathSebelumRapi] = true
end
end
return state or {}
end
_G.mtPastikanRegistri()
local undoBaru, redoBaru = {}, {}
for _, st in ipairs(data.undo or {}) do undoBaru[#undoBaru + 1] = {label = st.label or "", state = balik(st.state)} end
for _, st in ipairs(data.redo or {}) do redoBaru[#redoBaru + 1] = {label = st.label or "", state = balik(st.state)} end
proyekMultiTrack = balik(data.proyek)
rw.undo = undoBaru
rw.redo = redoBaru
rw.sesi = nil
rw.namaProyek = data.nama or (tostring(pathNp:match("^.+/(.+)$") or pathNp):gsub("%.np$", ""))
rw.pathProyek = pathNp
rw.kotor = false
_G.mtSimpanRegistri()
_G.mtBersihkanSampah(false)
_G.mtSimpanOtomatis()
end
