end
local function perbaikiHeaderWav(path)
pcall(function()
local f = File(path)
local panjang = f.length()
local pNum = tonumber(panjang) or 0
if pNum <= 44 then return end
local raf = luajava.newInstance("java.io.RandomAccessFile", f, "rw")
local batas = (pNum < 256) and math.floor(pNum) or 256
local arr = luajava.newArray(luajava.bindClass("java.lang.Byte").TYPE, batas)
raf.seek(0)
raf.read(arr)
local isWav = (arr[0] == 82 and arr[1] == 73 and arr[2] == 70 and arr[3] == 70 and arr[8] == 87 and arr[9] == 65 and arr[10] == 86 and arr[11] == 69)
if isWav then
local dataOff = -1
for i = 12, batas - 4 do
if arr[i] == 100 and arr[i+1] == 97 and arr[i+2] == 116 and arr[i+3] == 97 then
dataOff = i
break
end
end
if dataOff ~= -1 then
local rb = luajava.bindClass("java.lang.Integer")
local dataLen = pNum - (dataOff + 8)
raf.seek(4); raf.writeInt(rb.reverseBytes(pNum - 8))
raf.seek(dataOff + 4); raf.writeInt(rb.reverseBytes(dataLen))
end
end
raf.close()
end)
end
local ok, err = pcall(function()
local prj = cjson.decode(jProy)
local cL = luajava.bindClass("dalvik.system.DexClassLoader")(dexP, odir, nil, service.getClassLoader())
local kls = cL.loadClass("FastMuxer")
local iT = luajava.bindClass("java.lang.Integer").TYPE
local fT = luajava.bindClass("java.lang.Float").TYPE
local bT = luajava.bindClass("java.lang.Boolean").TYPE
local sT = luajava.bindClass("java.lang.String")
local tDec = luajava.newArray(luajava.bindClass("java.lang.Class"), 5)
tDec[0]=sT; tDec[1]=sT; tDec[2]=iT; tDec[3]=iT; tDec[4]=iT
local metDec = kls.getDeclaredMethod("decodeToPCM", tDec)
local tFx = luajava.newArray(luajava.bindClass("java.lang.Class"), 9)
tFx[0]=sT; tFx[1]=sT; tFx[2]=sT; tFx[3]=iT; tFx[4]=iT; tFx[5]=iT; tFx[6]=iT; tFx[7]=fT; tFx[8]=fT
local metFx = kls.getDeclaredMethod("terapkanEfekSegmen", tFx)
local tMix = luajava.newArray(luajava.bindClass("java.lang.Class"), 7)
tMix[0]=sT; tMix[1]=sT; tMix[2]=iT; tMix[3]=iT; tMix[4]=iT; tMix[5]=iT; tMix[6]=iT
local metMix = kls.getDeclaredMethod("campurAudio", tMix)
local sRNum = tonumber(sR) or 44100
local chNum = tonumber(ch) or 2
local bRNum = tonumber(bR) or 128000
local mixLines = {}
for i, trk in ipairs(prj) do
lapor(TEKS.menyiapkan_track .. i .. ": " .. tostring(trk.nama))
local fSumber = File(trk.path or "")
if not fSumber.exists() or fSumber.length() <= 44 then
error(TEKS.file_audio_untuk_track .. i .. " (" .. tostring(trk.nama) .. TEKS.tidak_ditemukan_atau_kosong)
end
if string.match(string.lower(trk.path), "%.wav$") then
perbaikiHeaderWav(trk.path)
end
local pcmAwal = cDir .. "/trk_" .. i .. ".raw"
local pcmFx = cDir .. "/trk_fx_" .. i .. ".raw"
local pcmFinal = cDir .. "/trk_fin_" .. i .. ".raw"
pcall(function() File(pcmAwal).delete(); File(pcmFx).delete(); File(pcmFinal).delete() end)
local cacheMode = (isPrev == "cache")
local fileCache = nil
local hit = false
if cacheMode then
local okK, kunci = pcall(function()
local md = luajava.bindClass("java.security.MessageDigest").getInstance("MD5")
local fSrc = File(trk.path)
local ident = tostring(trk.path) .. "|" .. tostring(fSrc.length()) .. "|" .. tostring(fSrc.lastModified()) .. "|" .. cjson.encode(trk.efek or {}) .. "|" .. cjson.encode(trk.segmen or {}) .. "|" .. tostring(sRNum) .. "|" .. tostring(chNum)
local dig = md.digest(luajava.bindClass("java.lang.String")(ident).getBytes("UTF-8"))
local hx = {}
for b = 0, #dig - 1 do
local v = dig[b]
if v < 0 then v = v + 256 end
hx[#hx + 1] = string.format("%02x", v)
end
return table.concat(hx)
end)
if okK and kunci then
fileCache = cDir .. "/k_" .. kunci .. ".raw"
hit = File(fileCache).exists() and File(fileCache).length() > 0
end
if hit then lapor(TEKS.track .. i .. TEKS.sudah_siap_cache) end
end
local currPcm = pcmAwal
if hit then currPcm = fileCache else
local argsDec = luajava.newArray(luajava.bindClass("java.lang.Object"), 5)
argsDec[0] = trk.path
argsDec[1] = pcmAwal
argsDec[2] = luajava.newInstance("java.lang.Integer", string.format("%d", sRNum))
