_G.mtAktif = false
_G.mtTandaMuat = nil
_G.mtJumlah = 0
local function mtTanda(proyek)
local cjson = require "cjson"
local bagian = {}
for i, trk in ipairs(proyek) do
local f = File(trk.path or "")
local okE, efek = pcall(cjson.encode, trk.efek or {})
local okS, seg = pcall(cjson.encode, trk.segmen or {})
bagian[#bagian + 1] = tostring(trk.path) .. "#" .. tostring(f.length()) .. "#" .. tostring(f.lastModified()) .. "#" .. (okE and efek or "?") .. "#" .. (okS and seg or "?")
end
return table.concat(bagian, "\n")
end
_G.mtSiapkan = function(proyek, cbSiap, cbGagal)
local tanda = mtTanda(proyek)
local function angka(x, d) return string.format("%d", math.floor(tonumber(x) or d)) end
if _G.mtAktif and _G.mtTandaMuat == tanda and _G.mtJumlah == #proyek then
local bag = {}
for i, trk in ipairs(proyek) do bag[i] = angka(trk.vol, 100) .. "|" .. angka(trk.offsetMs, 0) end
local r = _G.rapikanLive("mt_atur", table.concat(bag, ";"))
if r:sub(1, 6) == "SUKSES" then cbSiap(); return end
end
local manifes = service.getExternalFilesDir(nil).getAbsolutePath() .. "/_mt_manifes.txt"
local pd = buatDialogTunggu(TEKS.menyiapkan_track_hanya_yang_berubah)
_G.eksekusiStudioDAW(proyek, manifes, "wav", 44100, 2, 128000, "cache", "", function()
pd.dismiss()
local r = _G.rapikanLive("mt_muat", manifes)
if r:sub(1, 6) == "SUKSES" then
_G.mtTandaMuat = tanda
_G.mtJumlah = #proyek
_G.mtAktif = true
cbSiap()
else
_G.mtAktif = false
cbGagal(r)
end
end, function(err)
pd.dismiss()
cbGagal(err)
end)
end
_G.mtMain = function(proyek, awalMs, solo, cbMulai, cbGagal)
_G.mtSiapkan(proyek, function()
local r = _G.rapikanLive("mt_main", tostring(math.floor(awalMs)), tostring(solo))
if r:sub(1, 6) == "SUKSES" then
if cbMulai then cbMulai() end
else
if cbGagal then cbGagal(r) end
end
end, function(err) if cbGagal then cbGagal(err) end end)
end
_G.mtLepas = function()
pcall(_G.rapikanLive, "mt_lepas")
_G.mtAktif = false
_G.mtTandaMuat = nil
_G.mtJumlah = 0
end
