local function salinFileAman(srcPath, dstPath)
local okCopy = pcall(function()
local fis = luajava.newInstance("java.io.FileInputStream", srcPath)
local fos = luajava.newInstance("java.io.FileOutputStream", dstPath)
local buf = luajava.newArray(luajava.bindClass("java.lang.Byte").TYPE, 32768)
local rd = fis.read(buf)
while rd ~= -1 do
fos.write(buf, 0, rd)
rd = fis.read(buf)
end
fos.flush(); fos.close(); fis.close()
