_G.nadiU8 = function(b) return (b + 256) % 256 end
_G.nadiWavInfo = function(path)
local info = nil
local pesan = TEKS.file_tidak_bisa_dibaca
pcall(function()
local ByteT = luajava.bindClass("java.lang.Byte").TYPE
local raf = luajava.newInstance("java.io.RandomAccessFile", File(path), "r")
local len = raf.length()
local h = luajava.newArray(ByteT, 12)
raf.seek(0)
raf.read(h)
if not (h[0] == 82 and h[1] == 73 and h[2] == 70 and h[3] == 70) then
raf.close()
pesan = TEKS.bukan_file_wav
return
end
local r = {}
local pos = 12
local c = luajava.newArray(ByteT, 8)
local f = luajava.newArray(ByteT, 16)
while pos + 8 <= len do
raf.seek(pos)
raf.read(c)
local id = string.char(_G.nadiU8(c[0]), _G.nadiU8(c[1]), _G.nadiU8(c[2]), _G.nadiU8(c[3]))
local size = _G.nadiU8(c[4]) + _G.nadiU8(c[5]) * 256 + _G.nadiU8(c[6]) * 65536 + _G.nadiU8(c[7]) * 16777216
if id == "fmt " then
raf.seek(pos + 8)
raf.read(f)
r.fmt = _G.nadiU8(f[0]) + _G.nadiU8(f[1]) * 256
r.ch = _G.nadiU8(f[2]) + _G.nadiU8(f[3]) * 256
r.sR = _G.nadiU8(f[4]) + _G.nadiU8(f[5]) * 256 + _G.nadiU8(f[6]) * 65536 + _G.nadiU8(f[7]) * 16777216
r.bits = _G.nadiU8(f[14]) + _G.nadiU8(f[15]) * 256
elseif id == "data" then
r.dataOff = pos + 8
r.dataLen = size
if r.dataLen <= 0 or r.dataLen > len - r.dataOff then r.dataLen = len - r.dataOff end
break
end
pos = pos + 8 + size + (size % 2)
end
raf.close()
if not (r.sR and r.dataOff) then pesan = TEKS.header_wav_tidak_lengkap; return end
if r.bits ~= 16 or (r.ch ~= 1 and r.ch ~= 2) or (r.fmt ~= 1 and r.fmt ~= 65534) then
pesan = TEKS.hanya_wav_16_bit_mono_atau
return
end
r.frame = r.ch * 2
r.durMs = math.floor(r.dataLen / r.frame / r.sR * 1000)
info = r
end)
return info, pesan
end
_G.nadiNolkanByte = function(raf, byteAwal, nByte)
local buf = luajava.newArray(luajava.bindClass("java.lang.Byte").TYPE, 65536)
raf.seek(byteAwal)
local sisa = nByte
while sisa > 0 do
local n = math.min(sisa, 65536)
raf.write(buf, 0, n)
sisa = sisa - n
end
end
_G.nadiRampSampel = function(raf, byteAwal, nFrame, ch, g0, g1)
if nFrame <= 0 then return end
local nByte = nFrame * ch * 2
local arr = luajava.newArray(luajava.bindClass("java.lang.Byte").TYPE, nByte)
raf.seek(byteAwal)
raf.readFully(arr)
for i = 0, nFrame - 1 do
local g = g0 + (g1 - g0) * (i / math.max(1, nFrame - 1))
for c = 0, ch - 1 do
local p = (i * ch + c) * 2
local s = _G.nadiU8(arr[p]) + _G.nadiU8(arr[p + 1]) * 256
if s >= 32768 then s = s - 65536 end
s = math.floor(s * g + 0.5)
if s < 0 then s = s + 65536 end
local lo = s % 256
local hi = math.floor(s / 256)
if lo > 127 then lo = lo - 256 end
if hi > 127 then hi = hi - 256 end
arr[p] = lo
arr[p + 1] = hi
end
end
raf.seek(byteAwal)
raf.write(arr, 0, nByte)
end
_G.nadiSalinByte = function(src, srcOff, dst, dstOff, nByte)
local buf = luajava.newArray(luajava.bindClass("java.lang.Byte").TYPE, 131072)
src.seek(srcOff)
dst.seek(dstOff)
local sisa = nByte
while sisa > 0 do
local rd = src.read(buf, 0, math.min(sisa, 131072))
if rd == nil or rd <= 0 then break end
dst.write(buf, 0, rd)
sisa = sisa - rd
end
end
