local function pastikanSalinan()
if not File(trk.path).exists() then return false end
_G.mtCatat(TEKS.lbl_edit_bagian_track .. tostring(trk.nama or ""))
local customDir = prefs.getBoolean("custom_dir_aktif", false) and prefs.getString("custom_dir_path", "storage/emulated/0/Audio Nadi") or "storage/emulated/0/Audio Nadi"
local dir = customDir .. "/Rekaman Audio"
File(dir).mkdirs()
local aman = tostring(trk.nama or TEKS.track_3):gsub("[^%w_%-]", "_")
local baru = dir .. "/" .. aman .. "_edit_" .. tostring(System.currentTimeMillis()) .. ".wav"
local ok = pcall(function()
local fis = luajava.newInstance("java.io.FileInputStream", trk.path)
local fos = luajava.newInstance("java.io.FileOutputStream", baru)
local buf = luajava.newArray(luajava.bindClass("java.lang.Byte").TYPE, 65536)
local rd = fis.read(buf)
while rd ~= -1 do
fos.write(buf, 0, rd)
rd = fis.read(buf)
end
fos.flush(); fos.close(); fis.close()
end)
if ok and File(baru).exists() and File(baru).length() > 44 then
trk.path = baru
trk.sudahSalin = true
_G.mtDaftarkan(baru)
return true
end
_G.mtBatalCatatTerakhir()
pcall(function() File(baru).delete() end)
return false
end
local function frameDari(ms) return math.floor(ms * info.sR / 1000 + 0.5) end
local function senyapkanBerkas()
local fAwal = frameDari(awal)
local fAkhir = math.min(frameDari(akhir), math.floor(info.dataLen / info.frame))
local n = fAkhir - fAwal
if n <= 0 then return false end
local F = math.min(frameDari(20), math.floor(n / 4))
local ok = pcall(function()
local raf = luajava.newInstance("java.io.RandomAccessFile", File(trk.path), "rw")
local base = info.dataOff + fAwal * info.frame
_G.nadiRampSampel(raf, base, F, info.ch, 1, 0)
_G.nadiNolkanByte(raf, base + F * info.frame, (n - 2 * F) * info.frame)
_G.nadiRampSampel(raf, base + (n - F) * info.frame, F, info.ch, 0, 1)
raf.close()
end)
return ok
end
