lepasPlayer()
if not pastikanSalinan() then
bicaraLayanan(TEKS.gagal_menyalin_file_track)
buatPlayer()
return
end
local ok = senyapkanBerkas()
_G.mtRebase()
buatPlayer()
if ok then
bicaraLayanan(TEKS.bagian_berhasil_disenyapkan)
else
bicaraLayanan(TEKS.gagal_menyenyapkan_bagian)
end
perbarui()
end)
end
