mp.setDataSource(fis.getFD())
mp.prepare()
fis.close()
local v = math.min(1.0, (tonumber(t2.vol) or 100) / 100.0)
mp.setVolume(v, v)
local p2 = tl0 - (tonumber(t2.offsetMs) or 0)
local tunda = 0
if p2 < 0 then tunda = -p2; p2 = 0 end
table.insert(pemain, {mp = mp, p = p2, tunda = tunda})
end)
end
end
local function hentikanPemain()
