bicaraLayanan(TEKS.rekam_ulang_dimulai)
local t0 = System.currentTimeMillis()
for _, e in ipairs(pemain) do
pcall(function()
e.mp.seekTo(e.p)
if e.tunda == 0 then
e.mp.start()
else
handler.postDelayed(Runnable{run = function()
if not batalRekam then pcall(function() e.mp.start() end) end
end}, e.tunda)
end
end)
