local msMulai = awal + off - tl0
local msAkhir = akhir + off - tl0
handler.postDelayed(Runnable{run = function()
if not batalRekam then pcall(function() _G.nadiGerakanPenanda() end) end
end}, math.max(0, msMulai))
handler.postDelayed(Runnable{run = function()
if not batalRekam then pcall(function() _G.nadiGerakanPenanda() end) end
end}, math.max(0, msAkhir))
handler.postDelayed(Runnable{run = function()
if batalRekam then return end
hapusFile(flagRec)
hentikanPemain()
handler.postDelayed(Runnable{run = function()
if batalRekam then return end
pcall(function() lay.removeView(btnBatal) end)
local ok, galat = pcall(function()
local tmp = _G.nadiWavInfo(rawPath)
if not tmp then error(TEKS.rekaman_tidak_terbaca) end
local tFirst = bacaAngkaFile(rawPath .. ".time") or (t0 + 150)
local fAwal = frameDari(awal)
local fAkhir = math.min(frameDari(akhir), math.floor(info.dataLen / info.frame))
local nTotal = fAkhir - fAwal
local wMulai = t0 + msMulai
local idx = math.floor((wMulai - tFirst) * info.sR / 1000 + 0.5)
local dstFrame = fAwal
local srcFrame = idx
if idx < 0 then
dstFrame = fAwal - idx
srcFrame = 0
end
local tersedia = math.floor(tmp.dataLen / tmp.frame) - srcFrame
local n = math.min(nTotal - (dstFrame - fAwal), tersedia)
if n <= 0 then error(TEKS.rekaman_terlalu_pendek) end
if not pastikanSalinan() then error(TEKS.gagal_menyalin_file_track_2) end
local rafT = luajava.newInstance("java.io.RandomAccessFile", File(trk.path), "rw")
local rafS = luajava.newInstance("java.io.RandomAccessFile", File(rawPath), "r")
local base = info.dataOff
_G.nadiNolkanByte(rafT, base + fAwal * info.frame, nTotal * info.frame)
_G.nadiSalinByte(rafS, tmp.dataOff + srcFrame * tmp.frame, rafT, base + dstFrame * info.frame, n * info.frame)
local F = math.min(frameDari(20), math.floor(n / 4))
_G.nadiRampSampel(rafT, base + dstFrame * info.frame, F, info.ch, 0, 1)
_G.nadiRampSampel(rafT, base + (dstFrame + n - F) * info.frame, F, info.ch, 1, 0)
rafS.close()
