local w = buatWadah(LinearLayout.VERTICAL, 0, 8, 0, 8)
local tv = buatTeks(label .. ": " .. curVal .. unit, 14)
local sb = _G.nadiStepperBar(maxVal, curVal)
_G.nadiPasangStepper(sb, function(s, prog, fromUser)
tv.setText(label .. ": " .. prog .. unit); cb(prog)
if fromUser then bicaraLayanan(prog .. (unit == " ms" and " milidetik" or " persen")) end
end)
w.addView(tv); w.addView(sb.view); pLayout.addView(w)
end
sliderEco(TEKS.jarak_waktu_pantulan, e.delay, 1000, " ms", function(v) e.delay = v end)
sliderEco(TEKS.banyaknya_ekor_pantulan, e.fb, 100, "%", function(v) e.fb = v end)
sliderEco(TEKS.peredam_pantulan, e.damp, 100, "%", function(v) e.damp = v end)
sliderEco(TEKS.volume_suara_asli, e.dry, 100, "%", function(v) e.dry = v end)
sliderEco(TEKS.kekuatan_suara_pantulan, e.wet, 100, "%", function(v) e.wet = v end)
e.stereo = e.stereo or prefs.getInt("eco_stereo", 50)
sliderEco(TEKS.tingkat_stereo_pantulan_berlaku_bila_cha, e.stereo, 100, "%", function(v) e.stereo = v end)
elseif jenisEfek == "bt" then
fx.eq = nil
fx.bt = fx.bt or {bass = prefs.getInt("tone_bass", 50), treble = prefs.getInt("tone_treble", 50)}
local bt = fx.bt
pLayout.addView(buatTeks(TEKS.pengaturan_bass_treble_50_erarti_netral, 16, 0, 0, 0, 15, Gravity.CENTER))
bangunPratinjauTone(function() return {bass = bt.bass, treble = bt.treble} end)
local function sliderBT(nama, key)
local w = buatWadah(LinearLayout.VERTICAL, 0, 8, 0, 8)
local tv = buatTeks(nama .. ": " .. bt[key] .. "%", 14)
local sb = _G.nadiStepperBar(100, bt[key])
_G.nadiPasangStepper(sb, function(s, prog, fromUser)
bt[key] = prog; tv.setText(nama .. ": " .. prog .. "%")
if ctrlPt then ctrlPt.ubah() end
if fromUser then bicaraLayanan(prog .. TEKS.persen) end
end)
w.addView(tv); w.addView(sb.view); pLayout.addView(w)
end
sliderBT(TEKS.bass_nada_rendah, "bass")
sliderBT(TEKS.treble_nada_tinggi, "treble")
elseif jenisEfek == "eq" then
fx.bt = nil
fx.eq = fx.eq or {b1 = prefs.getInt("tone_b1", 50), b2 = prefs.getInt("tone_b2", 50), b3 = prefs.getInt("tone_b3", 50), b4 = prefs.getInt("tone_b4", 50), b5 = prefs.getInt("tone_b5", 50)}
local eq = fx.eq
