bangunPratinjauTone(function() return {b1 = eq.b1, b2 = eq.b2, b3 = eq.b3, b4 = eq.b4, b5 = eq.b5} end)
local bands = {{TEKS.t_60_hz_dentuman, "b1"}, {TEKS.t_250_hz_kehangatan, "b2"}, {TEKS.t_1_khz_inti_suara, "b3"}, {TEKS.t_4_khz_kejelasan, "b4"}, {TEKS.t_12_khz_kilau, "b5"}}
for _, bSpec in ipairs(bands) do
