_G.nadiPasangStepper(sb, function(s, prog, fromUser)
eq[k] = prog; tv.setText(nama .. ": " .. prog .. "%")
if ctrlPt then ctrlPt.ubah() end
if fromUser then bicaraLayanan(prog .. TEKS.persen) end
end)
w.addView(tv); w.addView(sb.view); pLayout.addView(w)
end
end
