local btnUndo, btnRedo
local function segarkanTombolRiwayat()
local rw = _G.mtRw
if btnUndo then
local n = #rw.undo
btnUndo.setText(n > 0 and (TEKS.urungkan .. " (" .. n .. ")") or TEKS.urungkan)
btnUndo.setEnabled(n > 0)
btnUndo.setAlpha(n > 0 and 1.0 or 0.4)
end
if btnRedo then
local n = #rw.redo
btnRedo.setText(n > 0 and (TEKS.ulangi .. " (" .. n .. ")") or TEKS.ulangi)
btnRedo.setEnabled(n > 0)
btnRedo.setAlpha(n > 0 and 1.0 or 0.4)
end
end
local function infoGeserSingkat(ms)
ms = tonumber(ms) or 0
if ms == 0 then return TEKS.normal_0_ms end
if ms < 0 then return TEKS.dimajukan .. math.abs(ms) .. " ms" end
return TEKS.dimundurkan .. ms .. " ms"
end
local function muatUlangDaftarTrack()
adapter.clear()
if #proyekMultiTrack == 0 then
adapter.add(TEKS.meja_kerja_masih_kosong_ketuk_tombol)
else
for i, trk in ipairs(proyekMultiTrack) do
local labelTipe = (trk.tipe == "impor") and TEKS.audio_impor or "[Rekaman]"
adapter.add(i .. ". " .. labelTipe .. " " .. trk.nama .. TEKS.volume .. trk.vol .. TEKS.posisi_waktu .. infoGeserSingkat(trk.offsetMs))
end
end
adapter.notifyDataSetChanged()
segarkanTombolRiwayat()
end
