local tikDash = false
local tvPosDash = buatTeks(TEKS.posisi_0_00_0_00, 13, 0, 0, 0, 5)
local hDash = Handler(Looper.getMainLooper())
local function fmtWaktuDash(ms)
local d = math.floor((tonumber(ms) or 0) / 1000)
return string.format("%d:%02d", math.floor(d / 60), d % 60)
end
local runDash
runDash = Runnable({run = function()
if not tikDash then return end
pcall(function()
local r = _G.rapikanLive("mt_status")
local jl, ps, du = r:match("^(%d)|(%-?%d+)|(%-?%d+)|")
if jl then
tvPosDash.setText(TEKS.posisi .. fmtWaktuDash(ps) .. " / " .. fmtWaktuDash(du))
if jl ~= "1" then tikDash = false end
else
tikDash = false
end
end)
if tikDash then hDash.postDelayed(runDash, 300) end
end})
local function mulaiTikDash()
if tikDash then return end
tikDash = true
hDash.postDelayed(runDash, 300)
end
local function hentikanPemutarDashboard()
pcall(_G.rapikanLive, "mt_henti")
end
pasangKlikItem(listView, function(parent, view, position, id)
if #proyekMultiTrack == 0 then return end
hentikanPemutarDashboard()
renderUIEditTrackKaraoke(position + 1, function() muatUlangDaftarTrack() end)
end)
