local function loncatDash(selisihMs)
if not _G.mtAktif then
bicaraLayanan(TEKS.putar_dulu_seluruh_track)
return
end
local r = _G.rapikanLive("mt_status")
local jl, ps = r:match("^(%d)|(%-?%d+)|")
local baru = math.max(0, (tonumber(ps) or 0) + selisihMs)
_G.rapikanLive("mt_cari", tostring(baru))
tvPosDash.setText(TEKS.posisi .. fmtWaktuDash(baru))
bicaraLayanan(fmtWaktuDash(baru))
end
