end
end, function(err)
hapusTombolMengambang(); prefs.edit().putString("status", "mati").apply()
hapusFile(progStatusFile)
bicaraLayanan(TEKS.gagal_memproses_karya .. tostring(err))
_G.bersihkanCacheDAW()
