local fis = FileInputStream(File(path))
player.setDataSource(fis.getFD())
fis.close()
end)
if not okFd then pcall(function() player.setDataSource(path) end) end
local function siapkanPlayer()
local durasiTotal = player.getDuration()
seekBar.setMax(durasiTotal)
pemutarAktif = true
local diseret = false
local updateRunnable
local seekRunnable = Runnable({
run = function()
if pemutarAktif and player then player.seekTo(seekBar.getProgress()) end
end
})
tvDurasi.setText("00:00 / " .. formatWaktu(durasiTotal))
updateRunnable = Runnable({
run = function()
if pemutarAktif and player and player.isPlaying() and not diseret then
local posisi = player.getCurrentPosition()
seekBar.setProgress(posisi)
tvDurasi.setText(formatWaktu(posisi) .. " / " .. formatWaktu(durasiTotal))
end
if pemutarAktif then handler.postDelayed(updateRunnable, 1000) end
end
})
seekBar.setOnSeekBarChangeListener(SeekBar.OnSeekBarChangeListener{
onProgressChanged = function(sb, progress, fromUser)
if fromUser then
tvDurasi.setText(formatWaktu(progress) .. " / " .. formatWaktu(durasiTotal))
handler.removeCallbacks(seekRunnable)
handler.postDelayed(seekRunnable, 150)
end
end,
onStartTrackingTouch = function(sb) diseret = true end,
onStopTrackingTouch = function(sb)
diseret = false
handler.removeCallbacks(seekRunnable)
if player then player.seekTo(sb.getProgress()) end
end
})
player.setOnCompletionListener(MediaPlayer.OnCompletionListener{
onCompletion = function(mp)
btnJeda.setText(TEKS.putar)
seekBar.setProgress(0)
tvDurasi.setText("00:00 / " .. formatWaktu(durasiTotal))
end
})
btnJeda.setOnClickListener(function()
if player.isPlaying() then
player.pause()
btnJeda.setText(TEKS.putar)
else
player.start()
btnJeda.setText(TEKS.jeda)
end
end)
btnMundur.setOnClickListener(function()
local p = player.getCurrentPosition() - 10000
if p < 0 then p = 0 end
player.seekTo(p)
seekBar.setProgress(p)
end)
btnMaju.setOnClickListener(function()
local p = player.getCurrentPosition() + 10000
if p > durasiTotal then p = durasiTotal end
player.seekTo(p)
seekBar.setProgress(p)
end)
btnTutup.setOnClickListener(function()
dialog.dismiss()
renderDaftarRekaman(kategori)
end)
player.start()
handler.post(updateRunnable)
end
