local function ambilBatch(maks)
local batch, sudah = {}, {}
local function coba(it)
if it and #batch < maks and not it.siap and not sudah[it.path] then
sudah[it.path] = true
table.insert(batch, it)
end
end
local mulai = 1
pcall(function() mulai = listView.getFirstVisiblePosition() + 1 end)
if mulai < 1 then mulai = 1 end
for k = mulai, #filteredFiles do coba(filteredFiles[k]) end
for k = 1, mulai - 1 do coba(filteredFiles[k]) end
for _, it in ipairs(allFiles) do coba(it) end
return batch
end
local function dialogMasihAktif()
if _G.nadiGenDaftar ~= genSaya then return false end
local aktif = true
pcall(function() aktif = dialog.isShowing() end)
return aktif
end
local function jalankanBatch()
if not dialogMasihAktif() then simpanCacheInfo(); return end
local batch = ambilBatch(6)
if #batch == 0 then
statusMuat = ""
segarkanTampilan()
simpanCacheInfo()
return
end
local kelompok = {}
for k = 1, #batch, 2 do
local g = { batch[k] }
if batch[k + 1] then table.insert(g, batch[k + 1]) end
table.insert(kelompok, g)
end
local tersisa = #kelompok
local function terapkan(g, hasilStr)
local baris = {}
for line in string.gmatch(tostring(hasilStr or ""), "[^\n]+") do table.insert(baris, line) end
for k, it in ipairs(g) do
local f = {}
local adaData = false
if baris[k] then
adaData = true
for fld in string.gmatch(baris[k] .. "\t", "([^\t]*)\t") do table.insert(f, fld) end
end
it.durStr = f[1] or "00:00"; it.bit = f[2] or "N/A"; it.chan = f[3] or "N/A"
it.sr = f[4] or "N/A"; it.resVid = f[5] or "N/A"; it.fpsVid = f[6] or "N/A"
it.siap = true
it.infoStr = susunInfo(it)
if adaData then
cacheInfo[it.path] = { k = kunciCache(it), d = it.durStr, b = it.bit, c = it.chan, r = it.sr, v = it.resVid, f = it.fpsVid }
end
end
end
local function selesaiSatu()
tersisa = tersisa - 1
if tersisa > 0 then return end
if dialogMasihAktif() then
statusMuat = TEKS.memuat_detail .. hitungSiap() .. "/" .. #allFiles
segarkanTampilan()
jalankanBatch()
else
simpanCacheInfo()
end
end
local function pekerja(pPaths)
require "import"
import "java.io.File"
import "android.media.MediaExtractor"
import "android.media.MediaFormat"
import "android.media.MediaMetadataRetriever"
local function fmtDur(ms)
local totalDetik = math.floor(ms / 1000)
local jam = math.floor(totalDetik / 3600)
local sisaDetik = totalDetik % 3600
local menit = math.floor(sisaDetik / 60)
local detik = sisaDetik % 60
if jam > 0 then return jam .. " jam " .. menit .. " menit " .. detik .. " detik"
elseif menit > 0 then return menit .. " menit " .. detik .. " detik" end
return detik .. " detik"
end
local out = {}
for p in string.gmatch(pPaths, "[^\n]+") do
local bytes = 0
pcall(function() bytes = File(p).length() end)
local durMs = 0
local chan, sr, resVid, fpsVid = "N/A", "N/A", "N/A", "N/A"
local ex = nil
pcall(function()
ex = MediaExtractor()
ex.setDataSource(p)
for j = 0, ex.getTrackCount() - 1 do
local fmt = ex.getTrackFormat(j)
local mime = fmt.getString(MediaFormat.KEY_MIME)
pcall(function()
local dMs = fmt.getLong(MediaFormat.KEY_DURATION) / 1000
if dMs > durMs then durMs = dMs end
end)
if mime:match("^video/") then
pcall(function()
local w = fmt.getInteger(MediaFormat.KEY_WIDTH)
local h = fmt.getInteger(MediaFormat.KEY_HEIGHT)
resVid = w .. "x" .. h
end)
pcall(function()
local fps = fmt.getInteger(MediaFormat.KEY_FRAME_RATE)
if fps > 0 then fpsVid = fps .. " FPS" end
end)
elseif mime:match("^audio/") then
pcall(function()
local sRate = fmt.getInteger(MediaFormat.KEY_SAMPLE_RATE)
if sRate > 0 then sr = sRate .. " Hz" end
end)
pcall(function()
local c = fmt.getInteger(MediaFormat.KEY_CHANNEL_COUNT)
if c == 1 then chan = "Mono" elseif c == 2 then chan = TEKS.stereo else chan = tostring(c) end
end)
end
end
end)
if ex then pcall(function() ex.release() end) end
if durMs <= 0 then
local mmr = nil
pcall(function()
mmr = MediaMetadataRetriever()
mmr.setDataSource(p)
local d = tonumber(mmr.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION))
if d and d > 0 then durMs = d end
end)
if mmr then pcall(function() mmr.release() end) end
end
local durStr, bit = "00:00", "N/A"
if durMs > 0 then
durStr = fmtDur(durMs)
bit = tostring(math.floor(bytes * 8 / durMs)) .. " kbps"
end
table.insert(out, table.concat({durStr, bit, chan, sr, resVid, fpsVid}, "\t"))
end
return table.concat(out, "\n")
end
for _, g in ipairs(kelompok) do
local paths = {}
for _, it in ipairs(g) do table.insert(paths, it.path) end
task(pekerja, table.concat(paths, "\n"), function(hasilStr)
terapkan(g, hasilStr)
selesaiSatu()
end)
end
end
if hitungSiap() >= #allFiles then
if cacheBaru then simpanCacheInfo() end
else
if cacheBaru then simpanCacheInfo() end
statusMuat = TEKS.memuat_detail .. hitungSiap() .. "/" .. #allFiles
tvHeader.setText(tvHeaderBase .. statusMuat)
jalankanBatch()
end
end)
end
