buatDialogPilihan(TEKS.posisi_panel_melayang_2, namaPosisiOverlay, prefs.getInt("posisi_overlay", 0), function(dPil, which)
dPil.dismiss()
prefs.edit().putInt("posisi_overlay", which).apply()
