local sbOverlay = {}
local function buatSliderOverlay(judul, kunci, minV, maxV, defV)
local nilai = math.max(minV, math.min(maxV, prefs.getInt(kunci, defV)))
local tv = buatTeks(judul .. ": " .. nilai .. TEKS.bawaan .. defV .. "%)", 14, 30, 10, 30, 5, nil, "#2196F3")
local sb = SeekBar(service)
sb.setMax(maxV - minV)
sb.setPadding(30, 10, 30, 20)
sb.setProgress(nilai - minV)
pcall(function() sb.setContentDescription(judul .. TEKS.panel_melayang) end)
pasangSeek(sb, function(sbx, progress, fromUser)
local v = progress + minV
tv.setText(judul .. ": " .. v .. TEKS.bawaan .. defV .. "%)")
prefs.edit().putInt(kunci, v).apply()
if fromUser then
bicaraLayanan(v .. TEKS.persen)
pcall(function() if _G.btnFloatControl then tampilkanTombolMengambang() end end)
end
end)
wadahPiksel.addView(tv)
wadahPiksel.addView(sb)
sbOverlay[#sbOverlay + 1] = {sb = sb, min = minV, def = defV}
end
buatSliderOverlay(TEKS.lebar_panel, "overlay_lebar", 60, 140, 100)
buatSliderOverlay(TEKS.tinggi_panel, "overlay_tinggi", 80, 200, 100)
buatSliderOverlay(TEKS.ukuran_teks_panel, "overlay_teks", 80, 160, 100)
