wadahPiksel.addView(buatTombol(TEKS.atur_ulang_panel_melayang_ke_bawaan, function()
prefs.edit().putInt("posisi_overlay", 0).apply()
for _, it in ipairs(sbOverlay) do
pcall(function() it.sb.setProgress(it.def - it.min) end)
end
pcall(function() btnPosOverlay.setText(teksPosisiOverlay()) end)
pcall(function() if _G.btnFloatControl then tampilkanTombolMengambang() end end)
bicaraLayanan(TEKS.panel_melayang_dikembalikan_ke_bawaan)
end))
layoutLokal.addView(wadahPiksel)
