renderOpsiPengaturan = function(tipe, judul, arrayTeks, arrayNilai, prefKey, defValue)
local layoutLokal = buatWadah(LinearLayout.VERTICAL, 0, 0, 0, 0)
local dialog
layoutLokal.addView(buatTeks(judul, 18, 30, 30, 30, 30))
local jlData = ArrayList()
for _, v in ipairs(arrayTeks) do jlData.add(v) end
local listView = ListView(service)
local adapter = ArrayAdapter(service, android.R.layout.simple_list_item_1, jlData)
listView.setAdapter(adapter)
layoutLokal.addView(listView, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, 0, 1))
local currVal = prefs.getInt(prefKey, defValue)
local currIdx = getIndex(arrayNilai, currVal)
listView.setItemChecked(currIdx, true)
layoutLokal.addView(buatTombol(TEKS.kembali, function()
dialog.dismiss()
renderPengaturan()
end))
pasangKlikItem(listView, function(parent, view, position, id)
if prefKey == "format" then prefs.edit().putInt(prefKey, position + 1).apply()
else prefs.edit().putInt(prefKey, arrayNilai[position + 1]).apply() end
dialog.dismiss()
renderPengaturan()
end)
dialog = buatDialogModular(nil, layoutLokal, function(d)
d.dismiss()
renderPengaturan()
return true
end)
tampilkanDialogUtama(dialog)
end
