_G.nadiBacaGerakanEfek = function(id)
local t = {}
local s = prefs.getString("gerakan_efek_" .. id, "")
local valid = {}
for _, e in ipairs(_G.nadiDaftarEfekGerakan) do valid[e[1]] = true end
for k in tostring(s):gmatch("[^,]+") do if valid[k] then t[k] = true end end
return t
end
_G.nadiSimpanGerakanEfek = function(id, t)
local daftar = {}
for _, e in ipairs(_G.nadiDaftarEfekGerakan) do
if t[e[1]] then table.insert(daftar, e[1]) end
end
prefs.edit().putString("gerakan_efek_" .. id, table.concat(daftar, ",")).apply()
end
