sensor = {judul = TEKS.sensor_suara, khusus = true},
bt = {judul = TEKS.bass_dan_treble, baris = {
{"bass", TEKS.bass_2, 0, 100, "%"},
{"treble", TEKS.treble_2, 0, 100, "%"}}},
eq = {judul = TEKS.equalizer_5_band, baris = {
{"b1", TEKS.band_1_paling_rendah, 0, 100, "%"},
{"b2", TEKS.band_2, 0, 100, "%"},
{"b3", TEKS.band_3, 0, 100, "%"},
{"b4", TEKS.band_4, 0, 100, "%"},
{"b5", TEKS.band_5_paling_tinggi, 0, 100, "%"}}}
}
_G.nadiBacaParamGerakan = function(id)
local ov = {}
local s = prefs.getString("gerakan_param_" .. id, "")
for k, f, v in tostring(s):gmatch("([%w_]+)%.([%w_]+)=(%-?%d+)") do
if _G.nadiSkemaParamEfek[k] then
ov[k] = ov[k] or {}
ov[k][f] = tonumber(v)
if f == "on3" then ov[k][f] = (ov[k][f] ~= 0) end
end
end
return ov
end
_G.nadiSerialParam = function(ov, aktif)
local ks, parts = {}, {}
for k in pairs(ov or {}) do table.insert(ks, k) end
table.sort(ks)
for _, k in ipairs(ks) do
if (not aktif) or aktif[k] then
local fs = {}
for f in pairs(ov[k]) do table.insert(fs, f) end
table.sort(fs)
for _, f in ipairs(fs) do
local nv = ov[k][f]
if type(nv) == "boolean" then nv = nv and 1 or 0 end
table.insert(parts, k .. "." .. f .. "=" .. math.floor(nv))
end
end
end
return table.concat(parts, ";")
end
_G.nadiSimpanParamGerakan = function(id, ov, aktif)
local teks = _G.nadiSerialParam(ov, aktif)
if teks == "" then
prefs.edit().remove("gerakan_param_" .. id).apply()
else
prefs.edit().putString("gerakan_param_" .. id, teks).apply()
end
end
