_G.nadiMaterialEfek = function(ids, ov)
local fx = {}
local set = {}
for _, k in ipairs(ids) do set[k] = true end
local stereo = (prefs.getInt("channel", 1) == 2)
if set.gate then
fx.gate = {thresh = prefs.getInt("gate_thresh", 20), attack = prefs.getInt("gate_attack", 5), release = prefs.getInt("gate_release", 150)}
end
if set.pitch then
local ps = _G.nadiMuatPitchLanjut()
if ps and (ps.glOn or (tonumber(ps.val) or 0) ~= 0) then
fx.pitch = {val = ps.val, semitone = ps.semitone or math.floor((tonumber(ps.val) or 0) + 0.5), lanjut = ps.lanjut and true or false, glOn = ps.glOn and true or false, g0 = ps.g0 or 0, g1 = ps.g1 or 0, gd = ps.gd or 0}
end
end
if set.reverb then
fx.reverb = {room = prefs.getInt("rvb_room", 50), damp = prefs.getInt("rvb_damp", 50), dry = prefs.getInt("rvb_dry", 70), wet = prefs.getInt("rvb_wet", 30), stereo = stereo and prefs.getInt("rvb_stereo", 50) or 0}
end
if set.echo then
fx.echo = {delay = prefs.getInt("eco_delay", 300), fb = prefs.getInt("eco_feedback", 30), damp = prefs.getInt("eco_damp", 50), dry = prefs.getInt("eco_dry", 100), wet = prefs.getInt("eco_wet", 30), stereo = stereo and prefs.getInt("eco_stereo", 50) or 0}
end
if set.bt then
fx.bt = {bass = prefs.getInt("tone_bass", 50), treble = prefs.getInt("tone_treble", 50)}
elseif set.eq then
fx.eq = {b1 = prefs.getInt("tone_b1", 50), b2 = prefs.getInt("tone_b2", 50), b3 = prefs.getInt("tone_b3", 50), b4 = prefs.getInt("tone_b4", 50), b5 = prefs.getInt("tone_b5", 50)}
end
if set.autotune then
fx.autotune = {key = prefs.getInt("at_key", 0), scale = prefs.getInt("at_scale", 0), speed = prefs.getInt("at_speed", 80)}
end
if set.suaradua then
local sd = _G.nadiMuatSuaraDua()
fx.suaradua = {s2 = sd.s2, vol2 = sd.vol2, dly2 = sd.dly2, pan2 = stereo and sd.pan2 or 0, on3 = sd.on3 and true or false, s3 = sd.s3, vol3 = sd.vol3, dly3 = sd.dly3, pan3 = stereo and sd.pan3 or 0, dry = sd.dry, fo = sd.fo, nat = sd.nat}
end
if set.sensor then
fx.sensor = {kind = 1, freq = 1000, vol = 60, mix = 0, fade = 10}
end
if ov then
for k, f in pairs(ov) do
if set[k] then
if k == "pitch" then
local v = f.semitone
if v ~= nil then
if v ~= 0 then
fx.pitch = {val = v, semitone = v, lanjut = false, glOn = false, g0 = 0, g1 = 0, gd = 0}
else
fx.pitch = nil
end
end
elseif fx[k] then
for nm, val in pairs(f) do
if nm == "stereo" and not stereo then
elseif (nm == "pan2" or nm == "pan3") and not stereo then
fx[k][nm] = 0
else
fx[k][nm] = val
end
end
end
end
end
end
return fx
end
_G.nadiGerakanSegmen = function()
if not prefs.getBoolean("gerakan_aktif", false) then return {} end
local log = _G.nadiGerakanLog or {}
local segs = {}
for i, e in ipairs(log) do
if #e.efek > 0 then
local awal = math.max(0, math.floor(tonumber(e.ms) or 0))
local akhir = 0
if log[i + 1] then akhir = math.floor(tonumber(log[i + 1].ms) or 0) end
if akhir == 0 or akhir > awal + 20 then
table.insert(segs, {awalMs = awal, akhirMs = akhir, efek = _G.nadiMaterialEfek(e.efek, e.ov)})
end
end
end
return segs
end
