if _G.nadiGerakanTapTunda then Handler(Looper.getMainLooper()).removeCallbacks(_G.nadiGerakanTapTunda) end
_G.nadiGerakanTapTunda = nil
end)
if d then pcall(function() d.dismiss() end) end
if _G.nadiGerakanTangguh then
