_G.nadiJalurAudioMatiMentah = function()
if _G.nadiAudioMatiJalur and File(_G.nadiAudioMatiJalur).exists() then return _G.nadiAudioMatiJalur end
local function norm(n)
n = tostring(n):lower()
n = n:gsub("%.[%w]+$", "")
n = n:gsub("%.[%w]+$", "")
n = n:gsub("[%s_%-]+", "")
return n
end
local function cari(d, dalam)
local ok, daftar = pcall(function() return File(d).list() end)
if not (ok and daftar) then return nil end
local subdir = {}
for i = 0, #daftar - 1 do
local nama = tostring(daftar[i])
local f = File(d .. "/" .. nama)
if f.isFile() then
if norm(nama) == "keyboardtelahditutup" then return d .. "/" .. nama end
elseif dalam and f.isDirectory() then
table.insert(subdir, d .. "/" .. nama)
end
end
for _, sd in ipairs(subdir) do
local r = cari(sd, false)
if r then return r end
end
return nil
end
local dasar = {}
local dd = _G.jalurDexNadi and _G.jalurDexNadi:match("^(.*)/[^/]*$")
if dd then table.insert(dasar, {dd, true}) end
pcall(function()
local ld = service.getLuaDir()
if ld and ld ~= "" then table.insert(dasar, {(ld:gsub("/$", "")), true}) end
end)
local induk = {}
for _, e in ipairs(dasar) do
local par = e[1]:match("^(.*)/[^/]*$")
if par and par ~= "" then table.insert(induk, {par, false}) end
end
for _, e in ipairs(induk) do table.insert(dasar, e) end
local dicari = {}
for _, e in ipairs(dasar) do
table.insert(dicari, e[1])
local r = cari(e[1], e[2])
if r then
_G.nadiAudioMatiJalur = r
return r
end
end
_G.nadiAudioMatiDicari = table.concat(dicari, ", ")
return nil
end
