_G.nadiGerakanBukaKanvas = function(saatKeluar)
if _G.nadiGerakanDialog then return end
local kustom = _G.nadiGerakanKustom
local st = {maxJari = 0, awalT = 0, sx = 0, sy = 0, px = 0, py = 0, ex = 0, ey = 0, dirs = {}, cur = nil, tapJari = 0, tapHitung = 0}
local MIN = 80
local hnd = Handler(Looper.getMainLooper())
local function arah(dx, dy)
if math.abs(dx) >= math.abs(dy) then return dx > 0 and "kanan" or "kiri" end
return dy > 0 and "bawah" or "atas"
end
local function proyeksi(d, x, y)
if d == "kanan" then return x elseif d == "kiri" then return -x elseif d == "bawah" then return y end
return -y
end
local function pusat(ev, kecuali)
local n = ev.getPointerCount()
local jx, jy, c = 0, 0, 0
for i = 0, n - 1 do
if i ~= kecuali then jx = jx + ev.getX(i); jy = jy + ev.getY(i); c = c + 1 end
end
if c == 0 then return st.px, st.py end
return jx / c, jy / c
end
local function picu(id)
if not _G.nadiIdGerakanValid[id] then return end
if not prefs.contains("gerakan_efek_" .. id) then
pcall(_G.nadiBunyiGerak)
return
end
local daftar = _G.nadiBacaDaftarGerakan(id)
local log = _G.nadiGerakanLog
local terakhir = log[#log]
local kunciDaftar = table.concat(daftar, ",")
local aktifSet = {}
for _, k in ipairs(daftar) do aktifSet[k] = true end
local ovG = _G.nadiBacaParamGerakan(id)
local pk = _G.nadiSerialParam(ovG, aktifSet)
local kunciBaru = kunciDaftar .. "|" .. pk
local kunciLama = terakhir and (table.concat(terakhir.efek, ",") .. "|" .. (terakhir.pk or "")) or ""
if terakhir and terakhir.gid == id and #terakhir.efek > 0 and kunciBaru == kunciLama then
local msOff = _G.nadiGerakanWaktu and _G.nadiGerakanWaktu() or 0
table.insert(log, {ms = msOff, efek = {}, ov = {}, pk = "", gid = nil})
pcall(_G.nadiBunyiMati)
return
end
if terakhir and kunciBaru == kunciLama then
pcall(_G.nadiBunyiGerak)
_G.nadiGetarGerak(30)
return
end
if (not terakhir) and kunciDaftar == "" then
pcall(_G.nadiBunyiGerak)
_G.nadiGetarGerak(30)
return
end
local ms = _G.nadiGerakanWaktu and _G.nadiGerakanWaktu() or 0
table.insert(log, {ms = ms, efek = daftar, ov = ovG, pk = pk, gid = id})
pcall(_G.nadiBunyiGerak)
_G.nadiGetarGerak(40)
end
local function selesaiTap(j, n)
if j == 1 then
if n == 2 then pcall(_G.nadiBunyiGerak); _G.nadiGerakanTutup(true) end
return
end
if n >= 1 and n <= 3 and j >= 2 and j <= 4 then picu("k" .. j .. "_" .. n) end
end
local function tap(j)
if st.tapJari ~= j then st.tapHitung = 0 end
st.tapJari = j
st.tapHitung = st.tapHitung + 1
if _G.nadiGerakanTapTunda then hnd.removeCallbacks(_G.nadiGerakanTapTunda) end
_G.nadiGerakanTapTunda = Runnable({run = function()
local n, jj = st.tapHitung, st.tapJari
st.tapHitung = 0
st.tapJari = 0
_G.nadiGerakanTapTunda = nil
selesaiTap(jj, n)
end})
hnd.postDelayed(_G.nadiGerakanTapTunda, 350)
end
local function selesaiSwipe()
local j = st.maxJari
local d = st.dirs
local id
if j == 1 and #d == 1 then id = "s1_" .. d[1]
elseif j == 1 and #d == 2 then id = "s1_" .. d[1] .. "_" .. d[2]
elseif (j == 2 or j == 3) and #d == 1 then id = "s" .. j .. "_" .. d[1] end
if id then picu(id) end
end
local DialogK = luajava.bindClass("android.app.Dialog")
local dlg = DialogK(service)
pcall(function() dlg.requestWindowFeature(1) end)
local canvas = LinearLayout(service)
canvas.setClickable(true)
canvas.setFocusable(true)
canvas.setFocusableInTouchMode(true)
canvas.setBackgroundColor(Color.parseColor("#000000"))
canvas.setOnTouchListener(luajava.createProxy("android.view.View$OnTouchListener", {
onTouch = function(v, event)
local aksi = event.getActionMasked()
local now = System.currentTimeMillis()
if aksi == 0 then
st.maxJari = 1
st.awalT = now
local x, y = pusat(event, -1)
st.sx, st.sy, st.px, st.py = x, y, x, y
st.ex, st.ey = x, y
st.dirs = {}
st.cur = nil
elseif aksi == 5 or aksi == 6 then
local kecuali = (aksi == 6) and event.getActionIndex() or -1
local jumlah = event.getPointerCount()
if aksi == 5 and jumlah > st.maxJari then st.maxJari = jumlah end
local x, y = pusat(event, kecuali)
local dx, dy = x - st.px, y - st.py
st.sx = st.sx + dx; st.sy = st.sy + dy
st.ex = st.ex + dx; st.ey = st.ey + dy
st.px, st.py = x, y
elseif aksi == 2 then
local x, y = pusat(event, -1)
st.px, st.py = x, y
if not st.cur then
local dx, dy = x - st.sx, y - st.sy
if math.max(math.abs(dx), math.abs(dy)) >= MIN then
st.cur = arah(dx, dy)
st.dirs = {st.cur}
st.ex, st.ey = x, y
end
else
if proyeksi(st.cur, x, y) > proyeksi(st.cur, st.ex, st.ey) then st.ex, st.ey = x, y end
local dx, dy = x - st.ex, y - st.ey
if math.max(math.abs(dx), math.abs(dy)) >= MIN then
local d = arah(dx, dy)
if d ~= st.cur and #st.dirs < 3 then
st.cur = d
table.insert(st.dirs, d)
st.ex, st.ey = x, y
end
end
end
elseif aksi == 1 then
local lama = now - st.awalT
if #st.dirs == 0 then
if lama < 300 and st.maxJari >= 1 and st.maxJari <= 4 then tap(st.maxJari) end
elseif lama < 2000 then
selesaiSwipe()
end
st.maxJari = 0
st.dirs = {}
st.cur = nil
elseif aksi == 3 then
st.maxJari = 0
st.dirs = {}
st.cur = nil
end
return true
end
}))
pcall(_G.nadiMuatMati)
if kustom and kustom.bangun then pcall(kustom.bangun, canvas) end
dlg.setContentView(canvas)
dlg.setCancelable(true)
pcall(function() dlg.setCanceledOnTouchOutside(false) end)
pcall(function()
local w = dlg.getWindow()
w.setType(WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY)
w.setLayout(-1, -1)
w.setBackgroundDrawable(luajava.bindClass("android.graphics.drawable.ColorDrawable")(Color.parseColor("#000000")))
end)
dlg.setOnDismissListener(luajava.createProxy("android.content.DialogInterface$OnDismissListener", {
onDismiss = function(d2)
if _G.nadiGerakanDialog then _G.nadiGerakanTutup(false) end
end
}))
_G.nadiGerakanDialog = dlg
_G.nadiGerakanSaatKeluar = saatKeluar
_G.nadiGerakanSaatTutupKustom = kustom and kustom.saatTutup or nil
if not _G.nadiGerakanLog then _G.nadiGerakanLog = {} end
if not _G.nadiGerakanWaktu then _G.nadiGerakanWaktu = _G.nadiGerakanWaktuRekaman end
dlg.show()
_G.nadiGerakanPenanda()
end
