if res ~= "SUKSES" and res ~= "SUKSES_KOSONG" then error(res) end
end)
return ok, err
end, tWav, tOut, curKey, curScale, curSpeed, service.getDir("dex", 0).getAbsolutePath(), _G.jalurDexNadi, function(ok, err)
