Thread(Runnable{run = function()
local ok, err = pcall(function()
local pCfgPrev = _G.nadiPitchCfg(false)
if pCfgPrev then
local fw = luajava.newInstance("java.io.FileWriter", prevDir .. "/_pitch.cfg")
fw.write(luajava.newInstance("java.lang.String", pCfgPrev))
fw.close()
end
local dPath = service.getDir("dex", 0).getAbsolutePath()
local cL = luajava.bindClass("dalvik.system.DexClassLoader")(_G.jalurDexNadi, dPath, nil, service.getClassLoader())
local FastMuxerClass = cL.loadClass("FastMuxer")
local sR = prefs.getInt("samplerate", 44100)
local ch = prefs.getInt("channel", 1)
local bR = prefs.getInt("bitrate", 128000)
local types = luajava.newArray(luajava.bindClass("java.lang.Class"), 9)
for i=0,2 do types[i] = luajava.bindClass("java.lang.String") end
for i=3,6 do types[i] = luajava.bindClass("java.lang.Integer").TYPE end
for i=7,8 do types[i] = luajava.bindClass("java.lang.Float").TYPE end
local method = FastMuxerClass.getDeclaredMethod("prosesAudio", types)
local args = luajava.newArray(luajava.bindClass("java.lang.Object"), 9)
args[0], args[1], args[2] = prevRaw, prevDir .. "/_kosong.raw", prevWav
args[3], args[4], args[5], args[6] = luajava.newInstance("java.lang.Integer", "1"), luajava.newInstance("java.lang.Integer", tostring(sR)), luajava.newInstance("java.lang.Integer", tostring(ch)), luajava.newInstance("java.lang.Integer", tostring(bR))
args[7], args[8] = luajava.newInstance("java.lang.Float", "1.0"), luajava.newInstance("java.lang.Float", "1.0")
local res = method.invoke(nil, args)
if tostring(res) ~= "SUKSES" and tostring(res) ~= "SUKSES_KOSONG" then
error(tostring(res))
end
end)
Handler(Looper.getMainLooper()).post(Runnable{run = function()
