prevPlayer.prepare()
fis.close()
prevPlayer.setOnCompletionListener(MediaPlayer.OnCompletionListener{
onCompletion = function(mp)
isPlayingPrev = false
btnPutarPrev.setText(TEKS.putar_pratinjau)
end
})
prevPlayer.start()
btnPutarPrev.setText(TEKS.memutar_ketuk_henti)
end)
if not okP then
isPlayingPrev = false
btnPutarPrev.setText(TEKS.putar_pratinjau)
bicaraLayanan(TEKS.gagal_memutar_audio_2 .. tostring(errP))
end
end})
end}).start()
end
end)
