if not fSum.exists() or fSum.length() < 4000 then
return nil, TEKS.belum_ada_suara_contoh_ketuk_tombol
end
return {jenis = "mentah", path = jalurMik, sr = prefs.getInt("samplerate", 44100), ch = prefs.getInt("channel", 1),
kunci = jalurMik .. ":" .. tostring(fSum.length()) .. ":" .. tostring(fSum.lastModified())}
end
})
local function buatBarisSlider(label, curVal, onChange)
local lay = buatWadah(LinearLayout.VERTICAL, 0, 15, 0, 15)
local tv = buatTeks(label .. ": " .. curVal .. "%", 14)
local sb = _G.nadiStepperBar(100, curVal)
_G.nadiPasangStepper(sb, function(s, prog, fromUser) tv.setText(label .. ": " .. prog .. "%"); onChange(prog); if fromUser then bicaraLayanan(prog .. TEKS.persen) end end)
lay.addView(tv)
lay.addView(sb.view)
pLayout.addView(lay)
return tv, sb
end
local function buatBarisVolume(label, curVal, onChange)
local lay = buatWadah(LinearLayout.HORIZONTAL, 0, 15, 0, 15, Gravity.CENTER)
local tv = buatTeks(label .. ": " .. curVal .. "%", 15, 5, 0, 5, 0)
tv.setLayoutParams(LinearLayout.LayoutParams(0, -2, 1))
tv.setGravity(Gravity.CENTER)
local function update(v)
if v > 100 then v = 100 elseif v < 0 then v = 0 end
tv.setText(label .. ": " .. v .. "%")
onChange(v)
bicaraLayanan(v .. TEKS.persen)
return v
end
local btnMin = buatTombol(TEKS.turun, function() curVal = update(curVal - 1) end)
local btnPlus = buatTombol(TEKS.naik, function() curVal = update(curVal + 1) end)
tv.setOnClickListener(function()
buatDialogInput(label .. " (0-100)", tostring(curVal), "OK", TEKS.batal, true, function(d, inputStr)
local val = tonumber(inputStr)
if val then curVal = update(math.floor(val)) end
d.dismiss()
end)
end)
lay.addView(btnMin)
lay.addView(tv)
lay.addView(btnPlus)
pLayout.addView(lay)
return tv
end
