rvbDamp = sel.damp or 50; prefs.edit().putInt("rvb_damp", rvbDamp).apply(); sbDamp.setProgress(rvbDamp); tvDamp.setText(TEKS.peredam_gema_makin_tinggi_gema_makin_2 .. rvbDamp .. "%")
rvbDry = sel.dry or 70; prefs.edit().putInt("rvb_dry", rvbDry).apply(); tvDry.setText(TEKS.volume_suara_asli_2 .. rvbDry .. "%")
rvbWet = sel.wet or 30; prefs.edit().putInt("rvb_wet", rvbWet).apply(); tvWet.setText(TEKS.kekuatan_suara_efek_gema_2 .. rvbWet .. "%")
rvbStereo = sel.stereo or 50; prefs.edit().putInt("rvb_stereo", rvbStereo).apply()
