local prevDir = service.getExternalFilesDir(nil).getAbsolutePath()
local prevRaw = prevDir .. "/_temp_preview_mic.raw"
local prevWav = prevDir .. "/_temp_preview_out.wav"
local flagPrev = prevDir .. "/_prev_rekam.flag"
local pausePrev = prevDir .. "/_prev_jeda.flag"
local prevPlayer = nil
local isRecordingPrev = false
local isPlayingPrev = false
local btnRekamPrev = buatTombol(TEKS.ketuk_untuk_rekam_2)
local btnPutarPrev = buatTombol(TEKS.putar_pratinjau)
local barisPrev = buatWadah(LinearLayout.HORIZONTAL, 0, 0, 0, 0, Gravity.CENTER)
barisPrev.addView(btnRekamPrev)
barisPrev.addView(btnPutarPrev)
pLayout.addView(barisPrev)
btnRekamPrev.setOnClickListener(function()
if isPlayingPrev then bicaraLayanan(TEKS.hentikan_pemutaran_2); return end
if isRecordingPrev then
isRecordingPrev = false; stPrev.rekam = false; btnRekamPrev.setText(TEKS.ketuk_untuk_rekam_2)
hapusFile(flagPrev); getar(50)
else
isRecordingPrev = true; stPrev.rekam = true; ctrlPt.hentikan(); btnRekamPrev.setText(TEKS.merekam_ketuk_henti)
hapusFile(prevRaw); hapusFile(prevWav)
if prevPlayer then pcall(function() prevPlayer.stop(); prevPlayer.release() end); prevPlayer = nil end
eksekusiAudioRecordTaskMic(prevRaw, flagPrev, pausePrev, prefs.getInt("samplerate", 44100), prefs.getInt("channel", 1), prefs.getInt("mic", 6))
getar(50)
end
end)
btnPutarPrev.setOnClickListener(function()
if isRecordingPrev then bicaraLayanan(TEKS.hentikan_rekaman); return end
if isPlayingPrev then
isPlayingPrev = false; btnPutarPrev.setText(TEKS.putar_pratinjau)
if prevPlayer then pcall(function() prevPlayer.stop(); prevPlayer.release() end); prevPlayer = nil end; getar(50)
else
if not File(prevRaw).exists() then bicaraLayanan(TEKS.rekam_dulu); return end
isPlayingPrev = true; ctrlPt.hentikan(); btnPutarPrev.setText("Memproses...")
_G.nadiPantauProgres(btnPutarPrev)
Thread(Runnable{run = function()
local ok, err = pcall(function()
pcall(function()
local strCfg = rvbTarget .. "," .. tostring(rvbRoom/100):gsub(",", ".") .. "," .. tostring(rvbDamp/100):gsub(",", ".") .. "," .. tostring(rvbDry/100):gsub(",", ".") .. "," .. tostring(rvbWet/100):gsub(",", ".") .. _G.nadiStereoCfg("rvb")
local fw = luajava.newInstance("java.io.FileWriter", prevDir .. "/_reverb.cfg")
fw.write(luajava.newInstance("java.lang.String", strCfg))
fw.close()
end)
local dPath = service.getDir("dex", 0).getAbsolutePath()
local cL = luajava.bindClass("dalvik.system.DexClassLoader")(_G.jalurDexNadi, dPath, nil, service.getClassLoader())
local kls = cL.loadClass("FastMuxer")
local sR = prefs.getInt("samplerate", 44100)
local ch = prefs.getInt("channel", 1)
local bR = prefs.getInt("bitrate", 128000)
local types = luajava.newArray(luajava.bindClass("java.lang.Class"), 9)
for i=0,2 do types[i] = luajava.bindClass("java.lang.String") end
for i=3,6 do types[i] = luajava.bindClass("java.lang.Integer").TYPE end
for i=7,8 do types[i] = luajava.bindClass("java.lang.Float").TYPE end
local method = kls.getDeclaredMethod("prosesAudio", types)
local args = luajava.newArray(luajava.bindClass("java.lang.Object"), 9)
args[0], args[1], args[2] = prevRaw, prevDir .. "/_kosong.raw", prevWav
args[3], args[4], args[5], args[6] = luajava.newInstance("java.lang.Integer", "1"), luajava.newInstance("java.lang.Integer", tostring(sR)), luajava.newInstance("java.lang.Integer", tostring(ch)), luajava.newInstance("java.lang.Integer", tostring(bR))
args[7], args[8] = luajava.newInstance("java.lang.Float", "1.0"), luajava.newInstance("java.lang.Float", "1.0")
local res = method.invoke(nil, args)
if tostring(res) ~= "SUKSES" and tostring(res) ~= "SUKSES_KOSONG" then error(tostring(res)) end
end)
Handler(Looper.getMainLooper()).post(Runnable{run = function()
if not ok then
isPlayingPrev = false; btnPutarPrev.setText(TEKS.putar_pratinjau)
bicaraLayanan(TEKS.gagal_memproses .. tostring(err)); return
end
local okP, errP = pcall(function()
if prevPlayer then prevPlayer.release() end
prevPlayer = MediaPlayer()
local fis = luajava.newInstance("java.io.FileInputStream", File(prevWav))
prevPlayer.setDataSource(fis.getFD())
prevPlayer.prepare()
fis.close()
prevPlayer.setOnCompletionListener(MediaPlayer.OnCompletionListener{
onCompletion = function(mp) isPlayingPrev = false; btnPutarPrev.setText(TEKS.putar_pratinjau) end
})
prevPlayer.start()
btnPutarPrev.setText(TEKS.memutar_ketuk_henti)
end)
if not okP then isPlayingPrev = false; btnPutarPrev.setText(TEKS.putar_pratinjau); bicaraLayanan(TEKS.gagal_memutar_audio_2 .. tostring(errP)) end
end})
end}).start()
end
end)
