local tProsesVokal = luajava.newArray(luajava.bindClass("java.lang.Class"), 9)
local sT = luajava.bindClass("java.lang.String"); local iT = luajava.bindClass("java.lang.Integer").TYPE; local fT = luajava.bindClass("java.lang.Float").TYPE
tProsesVokal[0]=sT; tProsesVokal[1]=sT; tProsesVokal[2]=sT; tProsesVokal[3]=iT; tProsesVokal[4]=iT; tProsesVokal[5]=iT; tProsesVokal[6]=iT; tProsesVokal[7]=fT; tProsesVokal[8]=fT;
local metVokal = kls.getDeclaredMethod("prosesAudio", tProsesVokal)
local tempVokalMatang = prevDir .. "/_temp_vokal_matang.wav"
luajava.bindClass("java.io.File")(tempVokalMatang).delete()
local argsVokal = luajava.newArray(luajava.bindClass("java.lang.Object"), 9)
