argsVokal[3] = luajava.newInstance("java.lang.Integer", "1"); argsVokal[4] = luajava.newInstance("java.lang.Integer", tostring(sR)); argsVokal[5] = luajava.newInstance("java.lang.Integer", tostring(ch)); argsVokal[6] = luajava.newInstance("java.lang.Integer", tostring(bR));
argsVokal[7] = luajava.newInstance("java.lang.Float", "1.0"); argsVokal[8] = luajava.newInstance("java.lang.Float", "1.0");
local resVokal = tostring(metVokal.invoke(nil, argsVokal))
