tProsesVo[11]=iT; tProsesVo[12]=fT; tProsesVo[13]=fT; tProsesVo[14]=fT; tProsesVo[15]=fT;
if voRadioP then tProsesVo[16]=luajava.bindClass("java.lang.Boolean").TYPE; tProsesVo[17]=luajava.bindClass("java.lang.Long").TYPE; tProsesVo[18]=fT; tProsesVo[19]=fT end
local metVo = kls.getDeclaredMethod("prosesVoiceOverDinamis", tProsesVo)
local aVo = luajava.newArray(luajava.bindClass("java.lang.Object"), (voRadioP) and 20 or 16)
aVo[0] = tempVokalMatang
aVo[1] = ""
aVo[2] = bgmCacheFile
aVo[3] = prevWav
aVo[4] = luajava.newInstance("java.lang.Integer", "1")
aVo[5] = luajava.newInstance("java.lang.Integer", tostring(sR))
aVo[6] = luajava.newInstance("java.lang.Integer", tostring(ch))
aVo[7] = luajava.newInstance("java.lang.Integer", tostring(bR))
aVo[8] = luajava.newInstance("java.lang.Float", "1.0")
aVo[9] = luajava.newInstance("java.lang.Float", "1.0")
aVo[10] = luajava.newInstance("java.lang.Float", tostring(prefs.getInt(voRadioP and "vor_vol" or "vo_vol", 30) / 100.0))
aVo[11] = luajava.newInstance("java.lang.Integer", "1")
aVo[12] = luajava.newInstance("java.lang.Float", tostring(prefs.getInt("vo_thresh", 20)))
aVo[13] = luajava.newInstance("java.lang.Float", tostring(prefs.getInt("vo_depth", 20)))
aVo[14] = luajava.newInstance("java.lang.Float", tostring(prefs.getInt("vo_attack", 100)))
aVo[15] = luajava.newInstance("java.lang.Float", tostring(prefs.getInt("vo_release", 500)))
if voRadioP then
aVo[16] = luajava.newInstance("java.lang.Boolean", "true")
aVo[17] = luajava.newInstance("java.lang.Long", string.format("%d", math.floor(tonumber(prefs.getInt("vor_mulai", 0)) or 0)))
aVo[18] = luajava.newInstance("java.lang.Float", tostring(tonumber(prefs.getInt("vor_hold", 5)) or 0))
aVo[19] = luajava.newInstance("java.lang.Float", tostring(tonumber(prefs.getInt("vor_fade", 3)) or 0))
end
local resVo = tostring(metVo.invoke(nil, aVo))
luajava.bindClass("java.io.File")(tempVokalMatang).delete()
if resVo ~= "SUKSES" then error(TEKS.gagal_ducking .. resVo) end
end)
