_G.eksekusiHentikanRekaman = function(dialogPanel)
timerPanelAktif = false
if _G.nadiGerakanTutup then _G.nadiGerakanTutup(false) end
if dialogPanel then pcall(function() dialogPanel.dismiss() end) end
if _G.screenOffReceiver then
pcall(function() service.unregisterReceiver(_G.screenOffReceiver) end)
_G.screenOffReceiver = nil
end
_G.hentikanSensorGoyang()
if flagFile.exists() then flagFile.delete(); pcall(function() service.stopForeground(true) end) end
if _G.nadiRecorder then
pcall(function() _G.nadiRecorder.stop(); _G.nadiRecorder.release() end)
_G.nadiRecorder = nil
end
lepaskanKamera()
getar(500)
local finalPath = prefs.getString("final_out_path", "")
local pDir = "storage/emulated/0"
if finalPath ~= "" then pcall(function() pDir = File(finalPath).getParent() end) end
local tempVid = prefs.getString("temp_video_path", "")
local cSample = prefs.getInt("samplerate", 44100)
local cChannel = prefs.getInt("channel", 1)
local cBitrate = prefs.getInt("bitrate", 128000)
local cFormatIdx = prefs.getInt("format", 1)
local tempAudioOut = (string.find(modePerekaman, "VIDEO") ~= nil or cFormatIdx == 2) and (pDir .. "/_temp_audio.m4a") or (pDir .. "/_temp_audio.wav")
prefs.edit().putString("status", "memproses").putString("jenis_proses", "rekaman").putLong("akumulasi", 0).putLong("waktu_mulai", 0).apply()
if prefs.getBoolean("sembunyi_panel_proses", false) then
tampilkanTombolMengambang()
else
renderProsesLatarBelakang()
end
eksekusiPostProcessing(modePerekaman, (cFormatIdx == 2) and 2 or 1, tempAudioOut, tempVid, finalPath, cSample, cChannel, cBitrate,
function()
local kunciLain = nil
if cFormatIdx >= 3 and string.find(modePerekaman, "VIDEO") == nil then kunciLain = _G.nadiKunciFormat[cFormatIdx] end
_G.nadiGerakanSetelahGabung(finalPath, string.find(modePerekaman, "VIDEO") ~= nil, cSample, cChannel, cBitrate, function()
local function lanjut()
hapusTombolMengambang()
pcall(function() _G.pdMux.dismiss() end)
prefs.edit().putString("status", "mati").apply()
local fileTarget = File(finalPath)
if prefs.getBoolean("konfirmasi_nama", false) and finalPath ~= "" and fileTarget.exists() then
Handler(Looper.getMainLooper()).post(Runnable({ run = function()
local fullNama = fileTarget.getName()
local ext = fullNama:match("^.+(%.%w+)$") or ""
local base = fullNama:sub(1, #fullNama - #ext)
buatDialogInput(TEKS.beri_nama_rekaman, base, TEKS.simpan, "", false, function(d, newBase)
if newBase == "" then newBase = base end
local newPath = fileTarget.getParent() .. "/" .. newBase .. ext
if File(newPath).exists() and newPath ~= finalPath then bicaraLayanan(TEKS.nama_bentrok_disimpan_asli)
else
fileTarget.renameTo(File(newPath))
bicaraLayanan(TEKS.rekaman .. newBase .. TEKS.tersimpan)
end
d.dismiss()
if prefs.getString("status", "mati") == "mati" and masterDialog and masterDialog.isShowing() then masterDialog.dismiss(); renderMenuUtama() end
end)
end}))
else
Handler(Looper.getMainLooper()).post(Runnable({ run = function()
bicaraLayanan(TEKS.rekaman_berhasil_disimpan)
if prefs.getString("status", "mati") == "mati" and masterDialog and masterDialog.isShowing() then masterDialog.dismiss(); renderMenuUtama() end
end}))
end
end
if kunciLain then
_G.nadiKonversiFileAkhir(finalPath, kunciLain, formatExt[cFormatIdx], 0, 0, cBitrate, function(pathBaru)
if pathBaru then
finalPath = pathBaru
else
bicaraLayanan(TEKS.konversi_ke_format_pilihan_gagal_rekaman)
end
lanjut()
end)
else
lanjut()
end
end)
end,
function(err)
hapusTombolMengambang()
prefs.edit().putString("status", "mati").apply()
Handler(Looper.getMainLooper()).post(Runnable({ run = function()
bicaraLayanan(TEKS.proses_gagal_2)
local errLayout = buatWadah(LinearLayout.VERTICAL)
local errDialog
