errLayout.addView(buatTombol(TEKS.salin_pesan_error, function()
service.getSystemService(Context.CLIPBOARD_SERVICE).setPrimaryClip(ClipData.newPlainText(TEKS.error_log, tostring(err)))
end))
errLayout.addView(buatTombol(TEKS.tutup, function()
