if masterDialog and masterDialog.isShowing() then masterDialog.dismiss(); renderMenuUtama() end
end))
errDialog = buatDialogKustom(TEKS.laporan_crash_perekam, errLayout)
end}))
end)
end
renderPanelKontrol = function()
local layoutLokal = buatWadah(LinearLayout.VERTICAL, 30, 30, 30, 30)
local dialog
layoutLokal.addView(buatTeks(TEKS.panel_kontrol_perekam, 18, 0, 0, 0, 20))
layoutLokal.addView(buatTeks(TEKS.durasi_rekaman, 14, 0, 0, 0, 5, Gravity.CENTER))
local tvWaktu = buatTeks(formatWaktu(prefs.getLong("akumulasi", 0)), 36, 0, 0, 0, 5, Gravity.CENTER)
layoutLokal.addView(tvWaktu)
local tvStatusRek = buatTeks("", 14, 0, 0, 0, 15, Gravity.CENTER, "#888888")
layoutLokal.addView(tvStatusRek)
local currStatus = prefs.getString("status", "sedang berjalan")
local btnJeda = buatTombol((currStatus == "terjeda") and TEKS.lanjutkan or TEKS.jeda)
local btnHenti = buatTombol(TEKS.hentikan, function()
_G.eksekusiHentikanRekaman(dialog)
end)
local btnSembunyi = buatTombol(TEKS.sembunyikan, function()
dialog.hide()
tampilkanTombolMengambang()
end)
local btnGerakanPanel = buatTombol(TEKS.mode_usap_gerakan_efek, function()
if _G.nadiGerakanBuka then _G.nadiGerakanBuka(nil) end
end)
layoutLokal.addView(btnJeda)
layoutLokal.addView(btnHenti)
if (prefs.getBoolean("gerakan_aktif", false)) then layoutLokal.addView(btnGerakanPanel) end
layoutLokal.addView(btnSembunyi)
timerPanelAktif = true
local updateRunnable
updateRunnable = Runnable({
run = function()
if timerPanelAktif and tvWaktu then
local s = prefs.getString("status", "mati")
local total = prefs.getLong("akumulasi", 0)
if s == "sedang berjalan" then total = total + (System.currentTimeMillis() - prefs.getLong("waktu_mulai", 0)) end
tvWaktu.setText(formatWaktu(total))
do
local tdet = math.floor(total / 1000)
local jm = math.floor(tdet / 3600)
local mn = math.floor((tdet % 3600) / 60)
local dt = tdet % 60
local lisan = ""
if jm > 0 then lisan = lisan .. jm .. " jam " end
if mn > 0 then lisan = lisan .. mn .. " menit " end
lisan = lisan .. dt .. " detik"
pcall(function() tvWaktu.setContentDescription(TEKS.durasi_rekaman_2 .. lisan) end)
tvStatusRek.setText(TEKS.status_2 .. ((s == "terjeda") and "terjeda" or "merekam") .. " - " .. lisan)
end
local teksSeharusnya = (s == "terjeda") and TEKS.lanjutkan or TEKS.jeda
if (s == "terjeda" or s == "sedang berjalan") and tostring(btnJeda.getText()) ~= teksSeharusnya then
btnJeda.setText(teksSeharusnya)
end
if timerPanelAktif then handler.postDelayed(updateRunnable, 1000) end
end
end
})
btnJeda.setOnClickListener(function()
local s = prefs.getString("status", "mati")
if s == "sedang berjalan" then
if _G.eksekusiJeda() then btnJeda.setText(TEKS.lanjutkan) end
elseif s == "terjeda" then
if _G.eksekusiLanjutkan() then btnJeda.setText(TEKS.jeda) end
end
end)
handler.post(updateRunnable)
dialog = buatDialogModular(nil, layoutLokal, function(d)
d.hide()
tampilkanTombolMengambang()
return true
end, function(d) timerPanelAktif = false end)
tampilkanDialogUtama(dialog)
end
