local runProg
runProg = Runnable({
run = function()
if isDialogAktif and tvProg then
local fPath = prefs.getString("final_out_path", "")
local statusTxt = nil
pcall(function()
if isEditor then
local progEditor = luajava.bindClass("java.io.File")(service.getExternalFilesDir(nil).getAbsolutePath() .. "/_editor_status.txt")
if progEditor.exists() then
local br = luajava.bindClass("java.io.BufferedReader")(luajava.bindClass("java.io.InputStreamReader")(luajava.bindClass("java.io.FileInputStream")(progEditor)))
