elseif progAudioA2V.exists() then targetFile = progAudioA2V
elseif progAudioFxVid.exists() then targetFile = progAudioFxVid
elseif progAudioStatus.exists() then targetFile = progAudioStatus
elseif progAudioVo.exists() then targetFile = progAudioVo
elseif progFinal.exists() then targetFile = progFinal end
