elseif jenisProses == "audio_ke_video" then awalan = TEKS.membuat_video
elseif jenisProses == "video_ke_audio" then awalan = TEKS.mengekstrak_audio
elseif jenisProses == "efek_audio" then awalan = TEKS.menerapkan_efek_audio
elseif jenisProses == "efek_video" then awalan = TEKS.menerapkan_efek_video
elseif jenisProses == "status_cerita" then awalan = TEKS.membuat_status
elseif jenisProses == "vo_audio" or jenisProses == "vo_video" then awalan = TEKS.mencampur_voice_over end
statusTxt = awalan .. isi2 .. "%"
end
end
end
end)
pcall(function()
local pctU, labU = _G.nadiBacaProgresUmum()
if pctU then statusTxt = ((labU and labU ~= "") and labU or "Memproses") .. ": " .. pctU .. "%" end
end)
if statusTxt then tvProg.setText(statusTxt) end
hProg.postDelayed(runProg, 500)
end
end
})
hProg.post(runProg)
dialog = buatDialogModular(nil, layoutLokal, function(d)
isDialogAktif = false
d.dismiss()
masterDialog = nil
tampilkanTombolMengambang()
bicaraLayanan(TEKS.berjalan_di_latar_belakang)
return true
end, function(d)
isDialogAktif = false
end)
tampilkanDialogUtama(dialog)
end
local cekStatus = prefs.getString("status", "mati")
if cekStatus == "mati" then
renderMenuUtama()
elseif cekStatus == "memproses" then
renderProsesLatarBelakang()
else
if prefs.getBoolean("henti_cepat", false) and _G.eksekusiHentikanRekaman then
_G.eksekusiHentikanRekaman(nil)
else
renderPanelKontrol()
end
end